// Added for Per-Link QA Verification
function getProjectsWithPendingLinks() {
    global $con;
    
    // Step 1: Find recent projects that have pending links (mimicking original fast query)
    $pendingQuery = "SELECT pro_id, user_id FROM webxl_task_links 
                     WHERE send_to_qa = 0 
                     ORDER BY id DESC LIMIT 500";
    $pRun = mysqli_query($con, $pendingQuery);
    if(!$pRun || mysqli_num_rows($pRun) == 0) return json_encode([]);
    
    $proIds = [];
    $userIds = [];
    while($row = mysqli_fetch_assoc($pRun)) {
        if(!empty($row['pro_id'])) $proIds[] = $row['pro_id'];
        if(!empty($row['user_id'])) $userIds[] = $row['user_id'];
    }
    if(empty($proIds)) return json_encode([]);
    
    $proIdStr = implode(',', array_unique($proIds));
    $userIdStr = implode(',', array_unique($userIds));

    // Step 2: Aggregate only for those active projects - Optimized to prevent hanging
    $query = "SELECT 
                agg.pro_id, 
                agg.user_id, 
                c.project, 
                com.cname, 
                u.name as user_name, 
                ta.links as required_qty,
                agg.total_posted_links,
                agg.approved_qty,
                agg.rejected_qty,
                agg.unsent_qty
            FROM (
                SELECT 
                    pro_id, 
                    user_id,
                    MAX(id) as max_id,
                    COUNT(id) as total_posted_links,
                    SUM(CASE WHEN qa_status = 1 THEN 1 ELSE 0 END) as approved_qty,
                    SUM(CASE WHEN qa_status = 0 THEN 1 ELSE 0 END) as rejected_qty,
                    SUM(CASE WHEN send_to_qa = 0 THEN 1 ELSE 0 END) as unsent_qty
                FROM webxl_task_links
                WHERE pro_id IN ($proIdStr) AND user_id IN ($userIdStr)
                GROUP BY pro_id, user_id
            ) agg
            LEFT JOIN webxl_create_project c ON agg.pro_id = c.pro_id 
            LEFT JOIN webxl_company com ON c.com_id = com.id
            LEFT JOIN webxl_user u ON agg.user_id = u.user_id
            LEFT JOIN (
                SELECT pro_id, user_id, MAX(links) as links
                FROM webxl_task_assign
                WHERE pro_id IN ($proIdStr) AND user_id IN ($userIdStr)
                GROUP BY pro_id, user_id
            ) ta ON agg.pro_id = ta.pro_id AND agg.user_id = ta.user_id
            HAVING approved_qty < required_qty OR required_qty IS NULL
            ORDER BY agg.max_id DESC";
              
    $run = mysqli_query($con, $query);
    if(!$run) return json_encode([]);
    return json_encode(mysqli_fetch_all($run, MYSQLI_ASSOC));
}

function getProjectsWithRejectedLinks() {
    global $con;
    
    // Step 1: Find recent projects that have rejected links
    $rejectedQuery = "SELECT pro_id, user_id FROM webxl_task_links 
                      WHERE qa_status = 0 
                      ORDER BY id DESC LIMIT 500";
    $rRun = mysqli_query($con, $rejectedQuery);
    if(!$rRun || mysqli_num_rows($rRun) == 0) return json_encode([]);
    
    $proIds = [];
    $userIds = [];
    while($row = mysqli_fetch_assoc($rRun)) {
        if(!empty($row['pro_id'])) $proIds[] = $row['pro_id'];
        if(!empty($row['user_id'])) $userIds[] = $row['user_id'];
    }
    if(empty($proIds)) return json_encode([]);
    
    $proIdStr = implode(',', array_unique($proIds));
    $userIdStr = implode(',', array_unique($userIds));

    // Step 2: Aggregate only for those active projects - Optimized to prevent hanging
    $query = "SELECT 
                agg.pro_id, 
                agg.user_id, 
                c.project, 
                com.cname, 
                u.name as user_name, 
                ta.links as required_qty,
                agg.total_posted_links,
                agg.approved_qty,
                agg.rejected_qty,
                agg.unsent_qty
            FROM (
                SELECT 
                    pro_id, 
                    user_id,
                    MAX(id) as max_id,
                    COUNT(id) as total_posted_links,
                    SUM(CASE WHEN qa_status = 1 THEN 1 ELSE 0 END) as approved_qty,
                    SUM(CASE WHEN qa_status = 0 THEN 1 ELSE 0 END) as rejected_qty,
                    SUM(CASE WHEN send_to_qa = 0 THEN 1 ELSE 0 END) as unsent_qty
                FROM webxl_task_links
                WHERE pro_id IN ($proIdStr) AND user_id IN ($userIdStr)
                GROUP BY pro_id, user_id
            ) agg
            LEFT JOIN webxl_create_project c ON agg.pro_id = c.pro_id 
            LEFT JOIN webxl_company com ON c.com_id = com.id
            LEFT JOIN webxl_user u ON agg.user_id = u.user_id
            LEFT JOIN (
                SELECT pro_id, user_id, MAX(links) as links
                FROM webxl_task_assign
                WHERE pro_id IN ($proIdStr) AND user_id IN ($userIdStr)
                GROUP BY pro_id, user_id
            ) ta ON agg.pro_id = ta.pro_id AND agg.user_id = ta.user_id
            HAVING rejected_qty > 0
            ORDER BY agg.max_id DESC";
              
    $run = mysqli_query($con, $query);
    if(!$run) return json_encode([]);
    return json_encode(mysqli_fetch_all($run, MYSQLI_ASSOC));
}

