function getLinksForQAVerification() {
    global $con;
    $query = "SELECT l.*, c.project, com.cname, u.name as user_name,
              (SELECT COUNT(id) FROM webxl_task_links WHERE pro_id = l.pro_id AND user_id = l.user_id AND send_to_qa = 0) as pending_qty
              FROM webxl_task_links l 
              LEFT JOIN webxl_create_project c ON l.pro_id = c.pro_id 
              LEFT JOIN webxl_company com ON c.com_id = com.id
              LEFT JOIN webxl_user u ON l.user_id = u.user_id
              WHERE l.send_to_qa = 1 AND l.qa_status IS NULL ORDER BY l.id DESC LIMIT 500";
    $run = mysqli_query($con, $query);
    if(!$run) return json_encode([]);
    return json_encode(mysqli_fetch_all($run, MYSQLI_ASSOC));
}

