        if(array_key_exists($ext, $allowed)) {
            $newfilename = time() . '_' . $id . '.' . $ext;
            $dest = __DIR__ . "/../assets/images/qa_rejects/" . $newfilename;
            if(move_uploaded_file($_FILES["reject_image"]["tmp_name"], $dest)) {
                $image_path = "assets/images/qa_rejects/" . $newfilename;
            } else {
                $err = error_get_last();
                echo "Error: Failed to save the uploaded file. Tmp: " . $_FILES["reject_image"]["tmp_name"] . " Dest: " . $dest . " " . ($err ? $err['message'] : 'No error message');
                exit;
            }
        } else {
            echo "Error: Invalid image format. Only JPG, PNG, GIF, WEBP allowed.";
            exit;
        }
    } else if (isset($_FILES['reject_image']) && $_FILES['reject_image']['error'] != 4) {
        echo "Error: Image upload failed. Please try a smaller image.";
        exit;
    }
    
    $update_img = "";
    if($image_path != "") {
        $update_img = ", qa_reject_image = '$image_path'";
    } else {
        echo "Error: Image is required for rejection.";
        exit;
    }

    mysqli_query($con, "UPDATE webxl_task_links SET qa_status = 0, qa_com = '$comment', qa_date = '$date' $update_img WHERE id = $id");
    echo "Success";
    exit;
}

