function format_percentage($percentage, $precision = 0)
{
    return round($percentage, $precision);
}
function calculate_percentage($number, $total)
{
    if ($total == 0) {
        return 0;
    }
    return ($number / $total) * 100;
}
function calculate_percentage_for_display($thisMonth, $lastMont)
{
    return format_percentage(calculate_percentage($thisMonth, $lastMont));
}
