function userABtarget($user_id)
{
    global $con;
    $quedates = AutoQueSystemDate();
    $dates = explode("/", $quedates);
    $start = $dates[0];
    $end = $dates[1];
    $query = "SELECT webxl_setterget.terget_cat,webxl_setterget.user_id,webxl_setterget.terget_id,webxl_setterget.start_date,webxl_setterget.end_date, 
    webxl_terget.terget_name,webxl_terget.target_number,webxl_terget.price,webxl_terget.conversion,webxl_terget.bonus,webxl_terget.type,webxl_terget.bonus,webxl_terget.reward,webxl_terget.kwa,webxl_terget.vas,webxl_terget.pleanty
    FROM webxl_setterget LEFT JOIN webxl_terget ON webxl_setterget.terget_id=webxl_terget.terget_id WHERE webxl_setterget.terget_cat='1'  AND webxl_terget.type='new' AND webxl_setterget.user_id = '$user_id'
     AND  webxl_setterget.start_date >= '$start' AND webxl_setterget.end_date <= '$end'";
    $runu = mysqli_query($con, $query);
    $userABtarget = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    return json_encode($userABtarget);
}
