function aliBabaQuesMont()
{
    $current_year = date('Y');
    $Q_p_1 = date('Y-m-d', strtotime("$current_year-04-01"));
    $Q_p_2 = date('Y-m-d', strtotime("$current_year-06-30"));

    $Q2_p_1 = date('Y-m-d', strtotime("$current_year-07-01"));
    $Q2_p_2 = date('Y-m-d', strtotime("$current_year-09-30"));

    $Q3_p_1 = date('Y-m-d', strtotime("$current_year-10-01"));
    $Q3_p_2 = date('Y-m-d', strtotime("$current_year-12-31"));

    $Q4_p_1 = date('Y-m-d', strtotime("$current_year-01-01"));
    $Q4_p_2 = date('Y-m-d', strtotime("$current_year-03-31"));

    if (date('Y-m-d') >= $Q_p_1 && date('Y-m-d') <= $Q_p_2) {
        $q1_Array = ['Apr', 'May', 'Jun'];
        return $q1_Array;
    }
    if (date('Y-m-d') >= $Q2_p_1 && date('Y-m-d') <= $Q2_p_2) {
        $q2_Array = ['Jul', 'Aug', 'Sep'];
        return $q2_Array;
    }
    if (date('Y-m-d') >= $Q3_p_1 && date('Y-m-d') <= $Q3_p_2) {
        $q3_Array = ['Oct', 'Nov', 'Dec'];
        return $q3_Array;
    }
    if (date('Y-m-d') >= $Q4_p_1 && date('Y-m-d') <= $Q4_p_2) {
        $q4_Array = ['Jan', 'Feb', 'Mar'];
        return $q4_Array;
    }
}
function aliBabaQuesMontYearly()
{
    $current_year = date('Y');
    $Q_p_1 = date('Y-m-d', strtotime("$current_year-04-01"));
    $Q_p_2 = date('Y-m-d', strtotime("$current_year-06-30"));

    $Q2_p_1 = date('Y-m-d', strtotime("$current_year-07-01"));
    $Q2_p_2 = date('Y-m-d', strtotime("$current_year-09-30"));

    $Q3_p_1 = date('Y-m-d', strtotime("$current_year-10-01"));
    $Q3_p_2 = date('Y-m-d', strtotime("$current_year-12-31"));

    $Q4_p_1 = date('Y-m-d', strtotime("$current_year-01-01"));
    $Q4_p_2 = date('Y-m-d', strtotime("$current_year-03-31"));

    if (date('Y-m-d') >= $Q4_p_1 && date('Y-m-d') <= $Q3_p_2) {
        $q1_Array = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
        return $q1_Array;
    }
}
