    ];

    $orderMap = array_flip($allowedMethods);

    // reset/default
    if (empty($from_date) && empty($to_date)) {
        $statsMap = TalkStatsByMethod($user_id, '1 DAY', $role_id);
    } else {
        $statsMap = TalkStatsByMethodRange($user_id, $from_date, $to_date, $role_id);
    }

    $target_role_id = ($role_id == 29) ? 25 : $role_id;
    $dbTargets = userDailyTargetBook($target_role_id, $user_id);

    // Map targets by method name for quick lookup
    $targetMap = [];
    if (!empty($dbTargets)) {
        foreach ($dbTargets as $dbTarget) {
            $targetMap[$dbTarget['method']] = $dbTarget['target'];
        }
    }

    $total_default_time = 0;
    $total_talk_time = 0;

    $output = '<ul class="list-group border-0" data-simplebar style="max-height:305px;">';

    foreach ($allowedMethods as $method) {
        $targetVal = isset($targetMap[$method]) ? (int)$targetMap[$method] : 0;

        $achievedCalls = (int) ($statsMap[$method]['calls'] ?? 0);
        $talkTime = (int) ($statsMap[$method]['talk'] ?? 0);
        $defaultTime = (int) ($achievedCalls * attributeTime($method));

        $total_talk_time += $talkTime;

        if ($talkTime > 0) {
            $total_default_time += $defaultTime;
        }

        $output .= '
        <li class="list-group-item tus_scroll" style="padding:4px 10px 0px 10px !important;">
            <div class="row">
                <div class="col-md-3">
                    <i class="bx bx-right-arrow-circle font-size-14 text-success" style="float:left;padding:0 6px 0 0;"></i>
                    <h3 class="font-size-11" style="margin:0;">' . htmlspecialchars($method) . '</h3>
                </div>

                <div class="col-md-3 text-center align-middle">
                    <h3 class="font-size-11" style="background-color:#eee;width:70px;padding:2px 5px;margin:0;">
                        ' . $targetVal . ' (' . $achievedCalls . ') ' . calculate_percentage_for_display($achievedCalls, $targetVal) . '%
                    </h3>
                </div>

                <div class="col-md-3 text-center align-middle">
                    <h3 class="font-size-11" style="background-color:#eee;width:70px;padding:2px 5px;margin:0;">
                        ' . $talkTime . '
                    </h3>
                </div>

                <div class="col-md-3 text-center">
                    <h3 class="font-size-11" style="background-color:#eee;width:70px;padding:2px 5px;margin:0;">
                        ' . $defaultTime . '
                    </h3>
                </div>
            </div>
        </li>';
    }

    $spentTime = (int) ($total_talk_time + $total_default_time);
    $freeTime = 480 - $spentTime;
    if ($freeTime < 0)
        $freeTime = 0;

    $output .= '
        <h6 class="text-center font-size-11 mt-2">
            Talk Time (' . (int) $total_talk_time . ')
            W-H 8(480 M)
            Spent(' . (int) $spentTime . ' M)
            Free(' . (int) $freeTime . ' M)
        </h6>
    </ul>';

    echo $output;
    exit;
}
function TalkStatsByMethodRange($user_id, $from_date = '', $to_date = '', $role_id = null)
{
    global $con;

    $user_id = mysqli_real_escape_string($con, $user_id);
    $from_date = mysqli_real_escape_string($con, $from_date);
    $to_date = mysqli_real_escape_string($con, $to_date);

    if ($role_id == 25) {
        $date_col = 'created_at';
        $method_col = 'method';
        $time_col = 'talk_time';
        $user_col = 'added_by';
        $table = 'webxl_follow_up_services';
    } else {
        $date_col = 'create_date';
        $method_col = 'cm';
        $time_col = 'tk_mint';
        $user_col = 'uid';
        $table = 'webxl_followup';
    }

    if (!empty($from_date) && !empty($to_date)) {
        $where = "DATE($date_col) BETWEEN '$from_date' AND '$to_date'";
    } else {
        $where = "DATE($date_col) = CURDATE()";
    }

    $sql = "SELECT $method_col AS method,
                   COUNT(*) AS total_calls,
                   IFNULL(SUM($time_col),0) AS total_talk_time
            FROM $table
            WHERE $user_col = '$user_id'
              AND $where
            GROUP BY $method_col";

    $res = mysqli_query($con, $sql);

    $map = [];
    while ($row = mysqli_fetch_assoc($res)) {
        $map[$row['method']] = [
            'calls' => (int) $row['total_calls'],
            'talk' => (int) $row['total_talk_time'],
        ];
    }

    return $map;
}
function userDailyTargetTeam($method, $user_id, $dateFillter = null, $from_date = null, $to_date = null)
{
    global $con;

    $method = mysqli_real_escape_string($con, $method);
    $user_id = (int) $user_id;

    // agar custom date range mila ho to usay priority do
    if (!empty($from_date) && !empty($to_date)) {

        $from_date = date('Y-m-d', strtotime($from_date));
        $to_date = date('Y-m-d', strtotime($to_date));

        // agar ulta select ho gaya ho to swap
        if ($from_date > $to_date) {
            $temp = $from_date;
            $from_date = $to_date;
            $to_date = $temp;
        }

        $query = "
            SELECT SUM(webxl_day_book.followup) AS TotalFollowUp
            FROM webxl_day_book
            WHERE webxl_day_book.method = '$method'
              AND webxl_day_book.user_id = '$user_id'
              AND DATE(webxl_day_book.date) BETWEEN '$from_date' AND '$to_date'
        ";
    } else {

        // Old logic fallback 
        $query = "
            SELECT SUM(webxl_day_book.followup) AS TotalFollowUp
            FROM webxl_day_book
            WHERE webxl_day_book.method = '$method'
              AND webxl_day_book.user_id = '$user_id'
              AND DATE(webxl_day_book.date) > DATE_SUB(CURDATE(), INTERVAL $dateFillter)
        ";
    }

    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);

    return (int) ($rowu['TotalFollowUp'] ?? 0);
}
function DailyTalkTime1($user_id, $days = 1)
{
    global $con;

    $query = "SELECT SUM(talk_time) as total 
              FROM call_logs 
              WHERE user_id = '$user_id'
              AND date >= DATE_SUB(CURDATE(), INTERVAL $days DAY)";

    $res = mysqli_query($con, $query);
    $row = mysqli_fetch_assoc($res);
    return $row['total'] ?? 0;
}

