function userTotalECMngTeamPerformace($user_idid, $start, $end)
{
    global $con;
    $query = "SELECT webxl_gmaccount.com_id,webxl_gmaccount.user_id,webxl_gmaccount.startData,webxl_gmaccount.endData,
    webxl_verify_gm.package,webxl_verify_gm.price,
    webxl_verify_gm.status,webxl_verify_gm.create_date,webxl_verify_gm.create_date,webxl_verify_gm.alibaba,
    webxl_verify_gm.renwal,webxl_verify_gm.pay_date,webxl_setterget.terget_id,webxl_setterget.target_num,webxl_setterget.terget_cat,webxl_setterget.start_date FROM `webxl_gmaccount`
    LEFT JOIN webxl_verify_gm ON webxl_gmaccount.com_id=webxl_verify_gm.com_id
    LEFT JOIN webxl_setterget ON webxl_gmaccount.user_id=webxl_setterget.user_id
    WHERE webxl_setterget.terget_cat=1 AND webxl_setterget.start_date='0000-00-00' AND webxl_gmaccount.user_id='$user_idid' AND webxl_gmaccount.startData BETWEEN '$start' AND '$end' GROUP BY webxl_gmaccount.user_id ORDER BY webxl_setterget.id DESC";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    return json_encode($rowu);
}
