      WHERE webxl_kwa.type='$type' AND webxl_kwa.create_at BETWEEN '$start' AND '$end' ORDER BY webxl_kwa.id DESC";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    return json_encode($rowu);
}
if (isset($_POST['packageAdmin'])) {
    sleep(1);
    $packageAdmin = $_POST['packageAdmin'];
    $start = $_POST['start'];
    $end = $_POST['end'];

    $i = 0;
    $statusClass = '';
    $alibabaClass = '';
    $renwal = '';
    $output = '';
    if ($packageAdmin == 'Verified Supplier') {
        $companies = json_decode(AdminDashDailyGmMonthly2VM($packageAdmin, $start, $end));
    } elseif ($packageAdmin == 'Kwa' || $packageAdmin == 'Sponsor Add') {
        $companies = json_decode(AdminVmuserTotalRCMngKWA2($packageAdmin, $start, $end));
    } else {
        $companies = json_decode(AdminDashDailyGmMonthly2($packageAdmin, $start, $end));
    }
    foreach ($companies as $company) {
        $i++;
        $conam = comname($company->com_id);
        $usernam = username($company->user_id);
        if ($company->status == 'Cash Received') {
            $statusClass = 'success';
        } elseif ($company->status == 'Online Paid') {
            $statusClass = 'warning';
        } else {
            $statusClass = 'secondary';
        }
        if ($company->renwal == '1') {
            $alibabaClass = 'success';
            $renwal = 'New';
        } elseif ($company->renwal == '2') {
            $alibabaClass = 'warning';
            $renwal = 'Ec';
        } else {
            $alibabaClass = 'secondary';
            $renwal = 'Rc';
        }

        $output .= '<tr>
                <td>' . $i . '</td>
                <td>' . comname($company->com_id) . '</td>
                <td>' . $company->package . '</td>
                <td>' . username($company->user_id) . '</td>
                <td><div class="text-left">
                            <span class="badge rounded-pill badge-soft-' . $statusClass . ' font-size-11">' . $company->status . '</span>
                        </div></td>
                <td><div class="text-left">
                            <span class="badge rounded-pill badge-soft-' . $alibabaClass . ' font-size-11">' . $renwal . '</span>
                        </div></td>
                        <td>' . $company->price . '</td>

            </tr>';
    }
    echo $output;
}
