function ImportantNotYetContact($user_id)
{
    global $con;

    $query = "
        SELECT
            wc.id,
            wc.assignId,
            wc.abAccount,
            wc.comType,
            wc.website,
            wc.source,
            wc.grade,
            wc.create_date,

            -- services (comma separated)
            GROUP_CONCAT(DISTINCT wa.name ORDER BY wa.name SEPARATOR ', ') AS service_names,
            GROUP_CONCAT(DISTINCT wfus.service_type ORDER BY wfus.created_at DESC SEPARATOR ', ') AS service_types,
            MAX(wfus.next_date)   AS next_date,
            MAX(wfus.created_at)  AS last_service_created_at

        FROM webxl_company wc
        LEFT JOIN webxl_last_followup lf
            ON lf.com_id = wc.id

        LEFT JOIN webxl_followup wf
            ON wf.com_id = wc.id

        LEFT JOIN webxl_follow_up_services wfus
            ON wfus.follow_up_id = wf.id
           AND wfus.added_by = ?

        LEFT JOIN webxl_attribute wa
            ON wa.refid = wfus.service_id

        WHERE lf.com_id IS NULL
          AND wc.assignId = ?

        GROUP BY wc.id
        ORDER BY wc.create_date DESC
    ";

    $stmt = mysqli_prepare($con, $query);
    mysqli_stmt_bind_param($stmt, "ii", $user_id, $user_id);
    mysqli_stmt_execute($stmt);
    $res = mysqli_stmt_get_result($stmt);

    $rowu = mysqli_fetch_all($res, MYSQLI_ASSOC);
    return json_encode($rowu);
}

