{
    global $con;
    $query = "SELECT webxl_invoice.invoice_id, COUNT(webxl_invoice.invoice_id) AS totalAccDashInvoice ,webxl_invoice.grand_total,webxl_invoice.pay, SUM(webxl_invoice.pay) AS TotalMonthVas, SUM(webxl_invoice.grand_total) AS TotalAccgrand_total FROM webxl_invoice LEFT JOIN webxl_company ON webxl_invoice.com_id=webxl_company.id WHERE webxl_invoice.pay !='' AND webxl_invoice.pay != webxl_invoice.grand_total";
