    $query = "SELECT webxl_invoice.invoice_id,webxl_invoice.create_date, COUNT(webxl_invoice.invoice_id) AS totalAccDashInvoice ,webxl_invoice.grand_total, SUM(webxl_invoice.grand_total) AS TotalMonthVas FROM webxl_invoice LEFT JOIN webxl_company ON webxl_invoice.com_id=webxl_company.id WHERE DATE(webxl_invoice.create_date) > DATE_SUB(NOW(), INTERVAL $headChange)";
    $runu = mysqli_query($con, $query);
