    $cotu = mysqli_num_rows($runu);
    $TotalMonthVas = $rowu['TotalMonthVas'];
    $totalAccDashInvoice = $rowu['totalAccDashInvoice'];
    $TT = $totalAccDashInvoice . '(' . round($TotalMonthVas, 0) . ')';


    $query = "SELECT webxl_invoice.invoice_id,webxl_invoice.create_date, COUNT(webxl_invoice.invoice_id) AS totalAccDashInvoice ,webxl_invoice.pay, SUM(webxl_invoice.pay) AS TotalMonthVas FROM webxl_invoice LEFT JOIN webxl_company ON webxl_invoice.com_id=webxl_company.id WHERE webxl_invoice.pay !='' AND DATE(webxl_invoice.create_date) > DATE_SUB(NOW(), INTERVAL $headChange)";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);
    $cotu = mysqli_num_rows($runu);
    $TotalMonthVas = $rowu['TotalMonthVas'];
    $totalAccDashInvoice = $rowu['totalAccDashInvoice'];
    $TNC = $totalAccDashInvoice . '(' . round($TotalMonthVas, 0) . ')';

    $query = "SELECT webxl_create_project.com_id,webxl_create_project.pro_id,webxl_create_project.create_data,webxl_invoice.com_id,webxl_invoice.pay, COUNT(webxl_create_project.pro_id) AS totalAccDashProject,
    SUM(webxl_invoice.pay) AS TotalMonthVas FROM webxl_create_project LEFT JOIN webxl_invoice ON webxl_create_project.pro_id=webxl_invoice.com_id WHERE DATE(webxl_create_project.create_data) > DATE_SUB(NOW(), INTERVAL $headChange)";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);
    $cotu = mysqli_num_rows($runu);
    $TotalMonthVas = $rowu['TotalMonthVas'];
    $totalAccDashProject = $rowu['totalAccDashProject'];
    $TRC = $totalAccDashProject . '(' . round($TotalMonthVas, 0) . ')';

    $query = "SELECT webxl_invoice.invoice_id,webxl_invoice.create_date, COUNT(webxl_invoice.invoice_id) AS totalAccDashInvoice ,webxl_invoice.grand_total,webxl_invoice.pay, SUM(webxl_invoice.pay) AS TotalMonthVas, SUM(webxl_invoice.grand_total) AS TotalAccgrand_total FROM webxl_invoice LEFT JOIN webxl_company ON webxl_invoice.com_id=webxl_company.id WHERE webxl_invoice.pay !='' AND webxl_invoice.pay != webxl_invoice.grand_total AND  DATE(webxl_invoice.create_date) > DATE_SUB(NOW(), INTERVAL $headChange)";
