    }
    if ($monthlyComFiilter == 'BV') {
        $query = "SELECT webxl_company.id,webxl_company.com_id,webxl_company.cname,webxl_company.contact,webxl_company.ntn,webxl_company.grade,webxl_company.comment,webxl_company.create_date,
        webxl_company.assignId,webxl_com_detail.name,webxl_com_detail.cinc,webxl_com_detail.email,webxl_com_detail.phone,webxl_gmaccount.create_data AS bvDate FROM webxl_company
         LEFT JOIN webxl_com_detail ON webxl_company.id=webxl_com_detail.com_id
         LEFT JOIN webxl_gmaccount ON webxl_company.id=webxl_gmaccount.com_id WHERE DATE(webxl_gmaccount.create_data) > DATE_SUB(NOW(), INTERVAL 1 MONTH) ORDER BY id DESC";
    }
    if ($monthlyComFiilter == 'REC') {
        $monthlyComFiilter = 'Amount';
        $query = "SELECT webxl_company.id,webxl_company.com_id,webxl_company.cname,webxl_company.contact,webxl_company.ntn,webxl_company.grade,webxl_company.comment,webxl_company.create_date,
            webxl_company.assignId,webxl_com_detail.name,webxl_com_detail.cinc,webxl_com_detail.email,webxl_com_detail.phone,webxl_payments.amount,webxl_payments.create_date AS recDate FROM webxl_company
             LEFT JOIN webxl_com_detail ON webxl_company.id=webxl_com_detail.com_id
             LEFT JOIN webxl_payments ON webxl_company.id=webxl_payments.com_id WHERE DATE(webxl_payments.create_date) > DATE_SUB(NOW(), INTERVAL 1 MONTH) ORDER BY id DESC";
    }
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_all($runu, MYSQLI_ASSOC);

    $output = '<table id="datatable" class="table table-striped table-bordered dt-responsive  nowrap w-100">
                                                    <thead>
                                                    <tr>
                                                        <th>ID</th>
                                                        <th>Company</th>
                                                        <th data-priority="1">Account</th>
                                                        <th data-priority="6=">' . $monthlyComFiilter . '</th>
                                                        <th data-priority="6">Create</th>
                                                    </tr>
                                                    </thead>
                                                    <tbody>
                                                         ';

    foreach ($rowu as $copmany) {

        $output .= '<tr>
                                                        <td>' . $copmany['com_id'] . '</td>
                                                        <td>' . $copmany['cname'] . '</td>
                                                        <td>' . $copmany['name'] . '</td>';
        if ($monthlyComFiilter == 'GM') {
            $BGD = $copmany['gmDate'];
        }
        if ($monthlyComFiilter == 'BV') {
            $BGD = $copmany['bvDate'];
        }
        if ($monthlyComFiilter == 'REC') {
            $BGD = $copmany['recDate'];
        }
        if ($monthlyComFiilter == 'Amount') {
            $output .= '<td>' . $copmany['amount'] . '</td>
                                                        <td>' . date('d-m-Y h:i A', strtotime($BGD)) . '</td>';
