function getInvoiceItemByComAndDep($com_id, $dep_id, $project_name = '', $offset = 0)
{
    global $con;

    $com_id = (int) $com_id;
    $dep_id = (int) $dep_id;
    $offset = (int) $offset;
    $project_name = mysqli_real_escape_string($con, $project_name);

    $item_name = '';
    if ($dep_id == 9) {
        $item_name = 'Alibaba Product Posting';
    } elseif ($dep_id == 10) {
        $item_name = 'Alibaba Minisite';
    }

    $item_filter = "wi.item = '$item_name'";
    if (!empty($project_name)) {
        $item_filter = "(wi.item = '$item_name' OR wi.item = '$project_name')";
    }

    if (empty($item_name) && empty($project_name)) {
        return [];
    }

    $query = "
        SELECT 
            wi.invoice_id,
            wi.detail,
            SUM(wi.unit_price) as unit_price,
            SUM(wi.qty) as qty
        FROM webxl_invoice w
        INNER JOIN webxl_invoice_item wi ON w.invoice_id = wi.invoice_id
        WHERE w.com_id = '$com_id'
        AND $item_filter
        GROUP BY wi.invoice_id
        ORDER BY w.invoice_id DESC
        LIMIT 1 OFFSET $offset
    ";

    $run = mysqli_query($con, $query);

    if (!$run) {
        return [];
    }

    return mysqli_fetch_assoc($run);
}

/**
 * Calculates the absolute offset of a project among all projects of its type for a company.
 * This is used to match the project with its corresponding invoice in the dashboard.
 */
function getProjectAbsoluteOffset($com_id, $pro_id, $project_name)
{
    global $con;
    $com_id = (int) $com_id;
    $pro_id = (int) $pro_id;
    $project_name = mysqli_real_escape_string($con, $project_name);

    // Get all projects of this type for this company, ordered by pro_id DESC (newest first)
    // This matches the DESC order used in getInvoiceItemByComAndDep
    $query = "SELECT pro_id FROM webxl_create_project WHERE com_id = '$com_id' AND project = '$project_name' ORDER BY pro_id DESC";
    $result = mysqli_query($con, $query);
    if (!$result) {
        return 0;
    }

    $offset = 0;
    while ($row = mysqli_fetch_assoc($result)) {
        if ($row['pro_id'] == $pro_id) {
            return $offset;
        }
        $offset++;
    }
    return 0;
}
