function AllDandDandPandPTaskBusyTeamCompleteProject($dep_id)
{
    global $con;
    $query = "
SELECT 
    webxl_quotation_services.name,
    webxl_quotation_services.dep_id,
    webxl_create_project.project,
    webxl_create_project.com_id,
    webxl_create_project.pro_id,
    webxl_task_assign.id,
    webxl_task_assign.pro_id,
    webxl_task_assign.assign_date,
    webxl_task_assign.user_id,
    webxl_task_assign.task_id,
    webxl_task_assign.hours,
    webxl_task_assign.min,
    webxl_task_assign.links,
    webxl_task_assign.timespent,
    webxl_task_assign.totalTimespent,
    webxl_task_assign.stauts,
    webxl_task_assign.mng_status,
    webxl_tasks_list.name AS task_name,
    webxl_tasks_list.hours,
    webxl_tasks_list.mins,
    webxl_tasks_list.detail
FROM webxl_quotation_services
LEFT JOIN webxl_create_project 
    ON webxl_quotation_services.name = webxl_create_project.project
LEFT JOIN webxl_task_assign 
    ON webxl_create_project.pro_id = webxl_task_assign.pro_id
LEFT JOIN webxl_tasks_list 
    ON webxl_task_assign.task_id = webxl_tasks_list.id
WHERE 
    webxl_quotation_services.dep_id = '$dep_id' 
    AND webxl_task_assign.stauts = 'End'
    AND (
        webxl_task_assign.mng_status = '0' 
        OR webxl_task_assign.mng_status = '1' 
        OR webxl_task_assign.mng_status = ''
        OR webxl_task_assign.mng_status IS NULL
    )
    AND (
        DATE(webxl_task_assign.assign_date) > DATE_SUB(NOW(), INTERVAL 3 MONTH)
        OR DATE(webxl_task_assign.last_update) = CURDATE()
    )
ORDER BY webxl_task_assign.pro_id DESC
";

    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_all($runu, MYSQLI_ASSOC);

    // print_r($query);
    return json_encode($rowu);
}

