function AllDandDandPandPprojectsVerificationTaskComplete($dep_id)
{
    global $con;
    $query = "SELECT webxl_quotation_services.name,webxl_quotation_services.dep_id,webxl_create_project.project,webxl_create_project.com_id,webxl_create_project.pro_id,webxl_task_assign.pro_id,webxl_task_assign.mng_status, COUNT(webxl_task_assign.pro_id) AS totalddAndppProject,
    webxl_payments.amount, SUM(webxl_payments.amount) AS TotalppAndDDAmount FROM webxl_quotation_services 
    LEFT JOIN webxl_create_project ON webxl_quotation_services.name=webxl_create_project.project
    LEFT JOIN webxl_payments ON webxl_create_project.com_id=webxl_payments.com_id
    LEFT JOIN webxl_task_assign ON webxl_create_project.pro_id=webxl_task_assign.pro_id WHERE webxl_task_assign.mng_status='complete' AND webxl_quotation_services.dep_id='$dep_id'";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);
    $TotalppAndDDAmount = $rowu['TotalppAndDDAmount'];
    $totalddAndppProject = $rowu['totalddAndppProject'];
    return $totalddAndppProject;
}
function AllDandDandPandPprojectsVerificationTaskPending($dep_id)
{
