    $role_id = $_POST['role_id'];

    // Define shift constants
    $SHIFT_START = '09:00:00';
    $SHIFT_END = '18:00:00';
    $BREAK_MINUTES = 90; // 1.5 hours break time
    $TOTAL_WORK_MINUTES = (9 * 60) - $BREAK_MINUTES; // 9 hours - break time = 450 minutes

    function calculateUserFreeTime($user_id, $userTasks, $TOTAL_WORK_MINUTES, $SHIFT_START)
    {
        // Get user's login time
        $loginTime = loginTimestamp($user_id, true);
        $currentTime = time();

        // Convert shift start to timestamp for today
        $shiftStartToday = strtotime(date('Y-m-d') . ' ' . $SHIFT_START);

        // If user logged in before 9 AM, consider login time as 9 AM
        $effectiveLoginTime = max($loginTime, $shiftStartToday);

        // Calculate total time user has been working (in minutes)
        $totalWorkingMinutes = ($currentTime - $effectiveLoginTime) / 60;

        // Don't exceed the total shift minutes
        $totalWorkingMinutes = min($totalWorkingMinutes, $TOTAL_WORK_MINUTES);

        // Calculate total spent time on all tasks (in minutes)
        $totalSpentMinutes = 0;
        foreach ($userTasks as $task) {
            list($d, $h, $m, $s) = sscanf($task->timespent, "%dd %d:%d:%d");
            $totalSpentMinutes += ($d * 1440) + ($h * 60) + $m + ($s / 60);
        }

        // Calculate remaining free time
        $freeMinutes = $totalWorkingMinutes - $totalSpentMinutes;

        // Never show negative time
        $freeMinutes = max(0, $freeMinutes);

        return $freeMinutes;
    }

    function calculateTaskFreeTime($user_id, $task, $totalUserFreeMinutes, $taskCount)
    {
        // Distribute total free time equally among tasks
        $freeTimePerTask = $taskCount > 0 ? $totalUserFreeMinutes / $taskCount : 0;

        // Never show negative time
        $freeTimePerTask = max(0, $freeTimePerTask);

        return $freeTimePerTask;
    }

    function formatMinutesToHours($minutes)
    {
        $hours = floor($minutes / 60);
        $mins = $minutes % 60;
        return sprintf("%02d:%02d", $hours, $mins);
    }
