                    $query_log = "SELECT * FROM `webxl_login` WHERE `user_id`='$name_user_id' AND DATE(last_login) = CURDATE() ORDER BY last_login ASC";
                    $retval_log = mysqli_query($con, $query_log);
                    $row_log = mysqli_fetch_assoc($retval_log);
                    $log_u_id = $row_log['user_id'];

                    if ($name_user_id == $log_u_id) {
                        // Get user's tasks for free time calculation
                        if ($role_id == '35') {
                            $userTasks = json_decode(AllDandDandPandPTaskBusyTeamPosting($DepNameId));
                        } else {
                            $userTasks = json_decode(AllDandDandPandPTaskBusyTeam($DepNameId));
                        }

                        // Filter tasks for this specific user
                        $userSpecificTasks = [];
                        foreach ($userTasks as $task) {
                            if ($task->user_id == $name_user_id) {
                                $userSpecificTasks[] = $task;
                            }
                        }

                        // Calculate correct free time using our new logic
                        $userFreeMinutes = calculateUserFreeTime($name_user_id, $userSpecificTasks, $TOTAL_WORK_MINUTES, $SHIFT_START);
                        $userFreeTimeFormatted = formatMinutesToHours($userFreeMinutes);

                        $output .= '<tr class="align-middle">
                                        <td>
                                            <div class="d-flex align-items-center">
                                                <img class="rounded-circle avatar-xs me-2" src="assets/images/user/' . $row_u['picture'] . '">
                                                <span>' . $name . '</span>
                                            </div>
                                        </td>
                                        <td><span class="badge rounded-pill badge-soft-success">' . $userFreeTimeFormatted . '</span></td>
                                        <td>' . loginTime($name_user_id) . '</td>
                                        <td>' . formatMinutesToHours($TOTAL_WORK_MINUTES) . '</td>
                                    </tr>';
                    }
                }
            }
        }
        $output .= '</tbody></table></div>';
    }

    echo $output;
}
