function loginTimestamp($name_user_id, $returnTimestamp = false)
{
    global $con;
    $query_log = "SELECT * FROM `webxl_login` 
                  WHERE `user_id`='$name_user_id' 
                  AND DATE(last_login) = CURDATE() 
                  ORDER BY last_login DESC";
    $retval_log = mysqli_query($con, $query_log);
    $row_log = mysqli_fetch_assoc($retval_log);

    if (!$row_log) {
        return $returnTimestamp ? 0 : "No login found";
    }

    $ts = strtotime($row_log['last_login']);

    if ($returnTimestamp) {
        return $ts; // for calculations
    } else {
        return date('h:i A', $ts); // for display
    }
}

function loginTime($name_user_id)
{
    global $con;
    $query_log = "SELECT * FROM `webxl_login` WHERE `user_id`='$name_user_id' AND DATE(last_login) = CURDATE() ORDER BY last_login DESC";
    $retval_log = mysqli_query($con, $query_log);
    $row_log = mysqli_fetch_assoc($retval_log);
    return date('h:i A', strtotime($row_log['last_login']));
}
