function allReceptionClients()
{
    global $con;
    $query = "SELECT webxl_visit_meeting.id,webxl_visit_meeting.com_id,webxl_visit_meeting.user_id,webxl_visit_meeting.status,webxl_visit_meeting.service,webxl_visit_meeting.start_time,webxl_visit_meeting.end_time,webxl_visit_meeting.note,webxl_company.id,webxl_company.cname FROM webxl_visit_meeting LEFT JOIN webxl_company ON webxl_visit_meeting.com_id=webxl_company.id ORDER BY webxl_company.id DESC";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    return json_encode($rowu);
}
