function AllHodTotalPprojects()
{
    global $con;
    $query = "SELECT webxl_payments.amount,webxl_payments.invoice_id,webxl_payments.com_id,webxl_status_hod.id,webxl_status_hod.acc_status, COUNT(webxl_status_hod.id) AS totalddAndppProject FROM webxl_payments
    LEFT JOIN webxl_status_hod ON webxl_status_hod.invoice_id=webxl_payments.invoice_id WHERE webxl_status_hod.acc_status=1";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);
    $totalddAndppProject = $rowu['totalddAndppProject'];
    return $totalddAndppProject;
}
