function AllApprovedQuotationsByUserId($user_id)
{
    global $con;
    $query = "SELECT *, (SELECT COUNT(*) FROM webxl_invoice WHERE webxl_invoice.qou_id = webxl_quotations.quo_id AND qou_id IS NOT NULL AND qou_id != 0 AND qou_id != '') as invoice_count FROM webxl_quotations WHERE hod_status='Approved' AND user_id='$user_id' ORDER BY quo_id DESC";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    return json_encode($rowu);
}

function AllConvertedQuotationsByUserId($user_id)
{
    global $con;
    $query = "SELECT *, (SELECT invoice_id FROM webxl_invoice WHERE webxl_invoice.qou_id = webxl_quotations.quo_id ORDER BY invoice_id DESC LIMIT 1) as generated_invoice_id FROM webxl_quotations WHERE hod_status='Approved' AND user_id='$user_id' AND quo_id IN (SELECT qou_id FROM webxl_invoice WHERE qou_id IS NOT NULL AND qou_id != 0 AND qou_id != '' AND DATE(create_date) >= DATE_SUB(CURDATE(), INTERVAL 7 DAY)) ORDER BY quo_id DESC";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    return json_encode($rowu);
}

