                    $user_bv_display = "N/A"; // Default value

                    if ($user_bv_result && mysqli_num_rows($user_bv_result) > 0) {
                        $bv_data = mysqli_fetch_assoc($user_bv_result);
                        $raw_date = $bv_data['user_bv_date'];

                        if ($raw_date != '0000-00-00' && !empty($raw_date)) {
                            $user_bv_display = date("d/m/Y", strtotime($raw_date));
                        }
                    }

                    $output .= '<tr>
                     <td class="text-nowrap">' . $n . '</td>
                     <td class="text-nowrap">' . $row['com_id'] . '</td>
                     <td class="text-nowrap">' . 'Test' . $comDatacname . '</td>
                     <td class="text-nowrap">' . $comDetail['phone'] . '</td>
                    <td class="text-nowrap">' . $row['package'] . '</td>
                   <td class="text-nowrap">' . $row['status'] . '</td>
                   <td class="text-nowrap">' . username($comDataAssign) . '</td>
                   <td class="text-nowrap">' . $user_bv_display . '</td> 
                   <td class="text-nowrap">' . date('d-m-Y', strtotime($year_day0)) . '</td>
                   <td class="text-nowrap">' . $renwal . '</td>
                   <td class="text-nowrap">' . date('d-m-Y', strtotime($row['create_date'])) . '</td>
                   <td class="text-nowrap">' . ($row['pay_date'] ? date('d-m-Y', strtotime($row['pay_date'])) : 'Pending') . '</td>
                 </tr>';
                }
            }
        }
    }

    $output .= '</tbody></table>
    <script>
$(document).ready(function() {
function generateTitle() {
        return "Bv Pending And Checking Report";
    }
    $("#Vasbvexpor").DataTable( {
        dom: "Bfrtip",
        searching: false,
        paging: false,
        ordering: false,
        buttons: [
            { extend: "copyHtml5", footer: true,
            filename: function() { return "bv_pending_checking_" + new Date().toISOString().slice(0, 10); },
                title: function() { return generateTitle(); }   },
            { extend: "excelHtml5", footer: true,
            filename: function() { return "bv_pending_checking_" + new Date().toISOString().slice(0, 10); },
                title: function() { return generateTitle(); }    },
            { extend: "csvHtml5", footer: true,
            filename: function() { return "bv_pending_checking_" + new Date().toISOString().slice(0, 10); },
                title: function() { return generateTitle(); }    },
            { extend: "pdfHtml5", footer: true,
            filename: function() { return "bv_pending_checking_" + new Date().toISOString().slice(0, 10); },
                title: function() { return generateTitle(); }    }
        ]
    });

} );
     </script>
  ';

    echo $output;
}
