function TotalLeadsDashCountByUserCountry_incomplete_data_total($country, $user_id)
{
    global $con;

    // Start query
    $query = "
        SELECT COUNT(webxl_leads.id) AS totalddAndppProject
        FROM webxl_leads
        LEFT JOIN webxl_company ON webxl_leads.com_id = webxl_company.id
        LEFT JOIN webxl_com_detail ON webxl_company.id = webxl_com_detail.com_id
        WHERE webxl_company.country = '$country' 
        AND webxl_leads.user_id = '$user_id'
         AND (
            webxl_company.comType = '' OR webxl_company.comType IS NULL OR
            webxl_company.city = '' OR webxl_company.city IS NULL OR
            webxl_company.contact = '' OR webxl_company.contact IS NULL OR
            webxl_company.website = '' OR webxl_company.website IS NULL OR
            webxl_company.address = '' OR webxl_company.address IS NULL OR
            webxl_company.comment = '' OR webxl_company.comment IS NULL OR
            webxl_company.tags = '' OR webxl_company.tags IS NULL OR
            webxl_com_detail.phone = '' OR webxl_com_detail.phone IS NULL OR
            webxl_com_detail.name = '' OR webxl_com_detail.name IS NULL OR
            webxl_com_detail.cinc = '' OR webxl_com_detail.cinc IS NULL OR
            webxl_com_detail.email = '' OR webxl_com_detail.email IS NULL
        )";
    // Execute query
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);

    // Return count or 0 if no result
    return $rowu['totalddAndppProject'] ?? 0;
}
function TotalLeadsDashCountByUserCountry_incomplete_data($country, $user_id, $key)
{
    global $con;

    // Start query
    $query = "
        SELECT COUNT(webxl_leads.id) AS totalddAndppProject
        FROM webxl_leads
        LEFT JOIN webxl_company ON webxl_leads.com_id = webxl_company.id
        LEFT JOIN webxl_com_detail ON webxl_company.id = webxl_com_detail.com_id
        WHERE webxl_company.country = '$country' 
        AND webxl_leads.user_id = '$user_id'";

    // Append condition based on the $key value
    if (in_array($key, ['comType', 'city', 'contact', 'website', 'address', 'comment', 'tags'])) {
        $query .= " AND (webxl_company.$key = '' OR webxl_company.$key IS NULL)";
    } elseif (in_array($key, ['phone', 'name', 'cinc', 'email'])) {
        $query .= " AND (webxl_com_detail.$key = '' OR webxl_com_detail.$key IS NULL)";
    }

    // Execute query
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);

    // Return count or 0 if no result
    return $rowu['totalddAndppProject'] ?? 0;
}


