function getLpQaStatus($com_id)
{
    global $con;

    $com_id = mysqli_real_escape_string($con, $com_id);

    // Listing Page project find karo
    $projectQuery = "
        SELECT pro_id
        FROM webxl_project_status
        WHERE com_id = '$com_id'
        AND product = 'Listing Page'
        LIMIT 1
    ";

    $projectResult = mysqli_query($con, $projectQuery);

    if (!$projectResult || mysqli_num_rows($projectResult) == 0) {
        return '-';
    }

    $projectRow = mysqli_fetch_assoc($projectResult);
    $pro_id = $projectRow['pro_id'];

    // QA Status check karo
    $query = "
        SELECT qa_status, qa_com, qa_date
        FROM webxl_task_assign
        WHERE pro_id = '$pro_id'
        ORDER BY id DESC
        LIMIT 1
    ";

    $result = mysqli_query($con, $query);

    if (!$result || mysqli_num_rows($result) == 0) {
        return 'Pending';
    }

    $row = mysqli_fetch_assoc($result);

    $qa_status = $row['qa_status'];
    $qa_com    = $row['qa_com'];
    $qa_date   = $row['qa_date'];

    $isQaStatusEmpty = empty($qa_status);
    $isQaComEmpty    = empty($qa_com);
    $isQaDateEmpty   = empty($qa_date) || $qa_date == '0000-00-00 00:00:00';

    if ($isQaStatusEmpty && $isQaComEmpty && $isQaDateEmpty) {
        return 'Pending';
    }

    if ($qa_status == 1 && !$isQaComEmpty && !$isQaDateEmpty) {
        return 'Approved';
    }

    return 'Pending';
}
