function TotalITDashDomainsExpire($limit = null, $offset = null)
{
    global $con;
    $query = "SELECT webxl_sell.id,webxl_sell.com_id,webxl_sell.domain_name,webxl_sell.reg_date,webxl_sell_products.sell_id,webxl_sell_products.pro_type,webxl_sell_products.key_id,webxl_sell_products.start_date,webxl_sell_products.end_date,webxl_sell_products.deactive_reason FROM webxl_sell
    LEFT JOIN webxl_sell_products ON webxl_sell.id=webxl_sell_products.sell_id 
    WHERE webxl_sell_products.deactive_reason = '' AND  webxl_sell_products.pro_type = 'domain' AND MONTH(webxl_sell_products.end_date - INTERVAL 1 MONTH) = MONTH(now()) AND  YEAR(webxl_sell_products.end_date - INTERVAL 1 YEAR) = YEAR(now()) 
    AND webxl_sell.com_id NOT IN (SELECT com_id FROM webxl_invoice WHERE domain_renewal = 1 AND create_date >= DATE_SUB(NOW(), INTERVAL 6 MONTH)) 
    ORDER BY webxl_sell.id DESC";
    if ($limit !== null) {
        $query .= " LIMIT " . (int)$limit;
        if ($offset !== null) {
            $query .= " OFFSET " . (int)$offset;
        }
    }
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    return json_encode($rowu);
}
