function TotalComplaintDash()
{
    global $con;
    $query = "SELECT webxl_complaints.id,webxl_complaints.ticket_no,webxl_complaints.com_id,webxl_complaints.service,webxl_complaints.user_id,webxl_complaints.dep,webxl_complaints.priority,webxl_complaints.detail,webxl_complaints.status,webxl_complaints.person_status,webxl_complaints.dep_status,webxl_complaints.create_date,webxl_company.cname FROM webxl_complaints
    LEFT JOIN webxl_company ON webxl_complaints.com_id=webxl_company.id ORDER BY webxl_complaints.id DESC";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    return json_encode($rowu);
}
function TotalComplaintDashPending()
{
    global $con;

    $query = "SELECT 
        webxl_complaints.id,
        webxl_complaints.ticket_no,
        webxl_complaints.user_comment,
        webxl_complaints.manager_comment,
        webxl_complaints.com_id,
        webxl_complaints.service,
        webxl_complaints.user_id,
        webxl_complaints.dep,
        webxl_complaints.priority,
        webxl_complaints.detail,
        webxl_complaints.status,
        webxl_complaints.person_status,
        webxl_complaints.dep_status,
        webxl_complaints.create_date,
        webxl_company.cname 
    FROM webxl_complaints
    LEFT JOIN webxl_company ON webxl_complaints.com_id = webxl_company.id 
    WHERE webxl_complaints.status = 'Pending' 
    AND (webxl_complaints.is_deleted = '0' OR webxl_complaints.is_deleted IS NULL)
    ORDER BY webxl_complaints.id DESC";

    $runu = mysqli_query($con, $query);

    if ($runu) {
        $rowu = mysqli_fetch_all($runu, MYSQLI_ASSOC);
        return json_encode($rowu);
    } else {
        // Return empty array if query fails
        return json_encode([]);
    }
}
