function ImportantOtherCustomerService($user_id)
{
    global $con;
    $query = "SELECT webxl_servicepool.id,webxl_servicepool.com_id,webxl_servicepool.user_id,webxl_servicepool.create_date,webxl_company.id,webxl_company.assignId,webxl_company.grade,webxl_followup.create_date,webxl_followup.id AS fid,webxl_followup.note,
    webxl_followup.purpose_call,webxl_followup.uid,webxl_followup.com_id FROM webxl_servicepool
