    foreach ($companies as $list) {
        $date90_days = date('Y-m-d', strtotime($list->create_date . ' + 90 days'));
        $new_7_day_drop = date('Y-m-d', strtotime($date90_days . ' - 7 days'));
        if ($today_create_date >= $new_7_day_drop && $today_create_date < $date90_days) {
            $n++;
        }
    }
    return $n;
}
function userDropoutService($user_id)
