function allUserCustomerServicePoolAccordingMontQAll($startMonth, $endMonth)
{
    if ($startMonth == '01' || $endMonth == '03') {
        $currentYear = date('Y');
        $vurrentYear = $currentYear + 1;
    } else {
        $vurrentYear = date('Y');
    }

    $start = "$vurrentYear-$startMonth-01";
    $end = "$vurrentYear-$endMonth-31";

    global $con;
    $query = "SELECT sp.com_id, 
                    ga.com_id AS gm_com_id,
                    sp.id,
                    sp.user_id,
                    sp.create_date,
                    ga.user_id AS assignid,
                    ga.startData,
                    ga.endData,
                    ga.LastStartDate,
                    ga.LastExpireDate
              FROM webxl_servicepool sp
              LEFT JOIN (
                    SELECT com_id, user_id, startData, endData, LastStartDate, LastExpireDate
                    FROM webxl_gmaccount 
                    WHERE endData BETWEEN '$start' AND '$end'
                    AND LastStartDate IS NOT NULL
                    AND endData IS NOT NULL
                    AND LastStartDate != '0000-00-00'
                    AND endData != '0000-00-00'
                    GROUP BY com_id, user_id, LastStartDate, LastExpireDate
              ) ga ON sp.com_id = ga.com_id
              GROUP BY sp.com_id, ga.com_id
              HAVING ga.startData IS NOT NULL AND ga.endData IS NOT NULL
              ORDER BY ga.endData ASC";

    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    return json_encode($rowu);
}



