function allUserCustomerCurrentDate($user_id)
{
    global $con;
    $query = "SELECT webxl_company.id,webxl_company.com_id,webxl_company.cname,webxl_company.contact,webxl_company.ntn,webxl_company.grade,webxl_company.comment,webxl_company.assignId,webxl_company.create_date,webxl_com_detail.name,webxl_com_detail.cinc,webxl_com_detail.email,webxl_com_detail.phone FROM webxl_company LEFT JOIN webxl_com_detail ON webxl_company.id=webxl_com_detail.com_id WHERE webxl_company.assignId='$user_id' AND webxl_company.create_date = CURRENT_DATE() ORDER BY id DESC";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    return json_encode($rowu);
    mysqli_close($con);
}
