    $query = "SELECT webxl_company.id,webxl_company.assignId,webxl_followup.nc,webxl_followup.id,webxl_followup.purpose_call,webxl_followup.com_id,COUNT(webxl_followup.com_id) AS totalConatct, webxl_last_followup.create_date FROM webxl_company
