    WHERE webxl_last_followup.uid='$user_id' AND webxl_followup.uid='$user_id' AND webxl_company.assignId='$user_id' AND webxl_last_followup.com_id='$com_id' AND webxl_followup.com_id='$com_id'  ORDER BY webxl_followup.id DESC";
