function TeamMember($user_id)
{
    global $con;

    $user_id = trim($user_id);

    $query = "SELECT * FROM webxl_user WHERE underWork = ?";

    $stmt = mysqli_prepare($con, $query);
    if (!$stmt) {
        return json_encode(['error' => 'Prepare failed: ' . mysqli_error($con)]);
    }

    mysqli_stmt_bind_param($stmt, "s", $user_id);

    if (!mysqli_stmt_execute($stmt)) {
        $err = mysqli_stmt_error($stmt);
        mysqli_stmt_close($stmt);
        return json_encode(['error' => 'Execute failed: ' . $err]);
    }

    $result = mysqli_stmt_get_result($stmt);
    $team_members = mysqli_fetch_all($result, MYSQLI_ASSOC);

    mysqli_free_result($result);
    mysqli_stmt_close($stmt);

    return json_encode($team_members);
}

function ViewOldGmPool($user_id)
{
    global $con;

    $r_id = isset($_COOKIE['role_id']) ? $_COOKIE['role_id'] : null;

    if ($r_id == 27) {
        $team_json = TeamMember($user_id);
        $team = json_decode($team_json, true);

        $user_ids = [$user_id];

        if (!empty($team) && !isset($team['error'])) {
            foreach ($team as $member) {
                if (isset($member['user_id'])) {
                    $user_ids[] = $member['user_id'];
                }
            }
        }

        $user_ids_escaped = array_map(function ($id) use ($con) {
            return mysqli_real_escape_string($con, $id);
        }, $user_ids);

        $user_ids_string = "'" . implode("','", $user_ids_escaped) . "'";

        $match_column = ($r_id == 29) ? 'sp_id' : 'user_id';

        $query = "SELECT 
            webxl_verify_gm.*,
            webxl_gmaccount.bvDate,
            webxl_gmaccount.startData,
            webxl_gmaccount.endData,
            webxl_gmaccount.create_data,
            webxl_gmaccount.renwal,
            webxl_servicepool.id as servicepool_id
        FROM webxl_verify_gm
        LEFT JOIN webxl_gmaccount ON webxl_verify_gm.com_id = webxl_gmaccount.com_id
        LEFT JOIN webxl_servicepool ON webxl_verify_gm.com_id = webxl_servicepool.com_id
        WHERE webxl_verify_gm.$match_column IN ($user_ids_string)
        ORDER BY webxl_verify_gm.id DESC";
    } else {
        $user_id = mysqli_real_escape_string($con, $user_id);

        $match_column = ($r_id == 29) ? 'sp_id' : 'user_id';

        $query = "SELECT 
            webxl_verify_gm.*,
            webxl_gmaccount.bvDate,
            webxl_gmaccount.startData,
            webxl_gmaccount.endData,
            webxl_gmaccount.create_data,
            webxl_gmaccount.renwal,
            webxl_servicepool.id as servicepool_id
        FROM webxl_verify_gm
        LEFT JOIN webxl_gmaccount ON webxl_verify_gm.com_id = webxl_gmaccount.com_id
        LEFT JOIN webxl_servicepool ON webxl_verify_gm.com_id = webxl_servicepool.com_id
        WHERE webxl_verify_gm.$match_column = '$user_id'
        ORDER BY webxl_verify_gm.id DESC";
    }

    $runu = mysqli_query($con, $query);

    if (!$runu) {
        return json_encode(['error' => 'Database query failed: ' . mysqli_error($con)]);
    }

    $rowu = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    mysqli_free_result($runu);

    $json_result = json_encode($rowu, JSON_INVALID_UTF8_SUBSTITUTE);

    if ($json_result === false) {
        error_log("JSON encode failed: " . json_last_error_msg());
        return json_encode(['error' => 'JSON encoding failed: ' . json_last_error_msg()]);
    }

    return $json_result;
}
