function accessUrls($rec_id, $getUrl)
{
    $menu2 = json_decode(allDrmSettingPermission(), true);
    $userRoleDep = userRoleDep($rec_id);
    $DepName = DepName($userRoleDep);
    $json = '';
    foreach ($menu2 as $list) {
        $depsids = explode(",", $list['dep']);
        $urls = explode(",", $list['url']);
        $curPageName = $getUrl;
        if (in_array($DepName, $depsids)) {

            if (in_array($curPageName, $urls)) {
                $json = $curPageName;
            }
        }
    }
    return $json;
}
