if (isset($_POST['add_invoice_installment'])) {
    $invoice_id = $_POST['add_invoice_installment'];
    $company_id = $_POST['company_id'];
    $amount = $_POST['amount']; // Total payment amount
    $method = $_POST['method'];
    $receipt_number = $_POST['receipt_number'];
    $pay = $_POST['pay'];
    $pay += $amount;

    // Insert payment into the webxl_payments table
    $qu_payment = "INSERT INTO `webxl_payments` (`invoice_id`, `com_id`, `amount`, `method`, `receipt_number`, `create_date`) VALUES ('$invoice_id', '$company_id', '$amount', '$method', '$receipt_number', '$datetime')";
    $re_payment = mysqli_query($con, $qu_payment);
    $rep_id = mysqli_insert_id($con);

    // Update the webxl_invoice table
    $qu_payment = "UPDATE `webxl_invoice` SET `pay` = '$pay', `account` = 'Paid' WHERE `invoice_id` = '$invoice_id'";
    $re_payment = mysqli_query($con, $qu_payment);

    // Retrieve invoice items
    $query = "SELECT * FROM webxl_invoice_item WHERE `invoice_id` = '$invoice_id'";
    $retval = mysqli_query($con, $query);

    $total_remain = 0;
    $items = [];

    // Calculate total remaining balance for all items
    while ($row = mysqli_fetch_assoc($retval)) {
        $row['item_remain'] = $row['pkr'] - $row['pay'];
        $total_remain += $row['item_remain'];
        $items[] = $row;
    }

    // Iterate over items and allocate payment
    foreach ($items as &$item) {
        $inv_item_id = $item['id'];
        $inv_item = $item['item'];
        $item_remain = $item['item_remain'];

        // Calculate proportional payment for this item
        $proportional_payment = floor(($item_remain / $total_remain) * $amount);

        // Ensure payment does not exceed remaining balance
        $final_payment = min($proportional_payment, $item_remain);
        $item['pay'] = $item['pay'] + $final_payment;
        $amount -= $final_payment;
        $total_remain -= $item_remain;

        // Update the item in the database
        $query1 = "UPDATE `webxl_invoice_item` SET `pay` = '{$item['pay']}' WHERE `id` = '$inv_item_id'";
        mysqli_query($con, $query1);

        // Insert the payment record for this item
        $query_item = "INSERT INTO `webxl_invoice_item_pay`(`inv_item_id`, `invoice_id`, `item`, `pay`, `method`) VALUES ('$inv_item_id', '$invoice_id', '$inv_item', '$final_payment','$method')";
        mysqli_query($con, $query_item);
    }

    // Redistribute any leftover amount if it exists
    if ($amount > 0) {
        foreach ($items as &$item) {
            $inv_item_id = $item['id'];
            $item_remain = $item['pkr'] - $item['pay'];

            if ($item_remain > 0 && $amount > 0) {
                $additional_payment = min($item_remain, $amount);
                $item['pay'] += $additional_payment;
                $amount -= $additional_payment;

                // Update the item in the database again
                $query1 = "UPDATE `webxl_invoice_item` SET `pay` = '{$item['pay']}' WHERE `id` = '$inv_item_id'";
                mysqli_query($con, $query1);

                // Insert the additional payment record for this item
                $query_item = "INSERT INTO `webxl_invoice_item_pay`(`inv_item_id`, `invoice_id`, `item`, `pay`, `method`) VALUES ('$inv_item_id', '$invoice_id', '{$item['item']}', '$additional_payment','$method')";
                mysqli_query($con, $query_item);
            }
        }
    }
}


