function TodaytaskAssign($user_id)
{  // get user name
    global $con;
    $hours2 = 0;
    $min2 = 0;
    $totalH = 0;
    $todayLogin = loginTime($user_id);
    $todayLoginTime = date('h:i A', strtotime($todayLogin));
    $start_date = new DateTime('09:00');
    $since_start = $start_date->diff(new DateTime($todayLoginTime));
    $quryu = "SELECT * FROM webxl_task_assign WHERE user_id = '$user_id' And DATE(assign_date) = CURDATE()";
    $runu = mysqli_query($con, $quryu);
    while ($rowu = mysqli_fetch_assoc($runu)) {
        $hours2 = $hours2 + $rowu['hours'];
        $min2 = $min2 + $rowu['min'];
        if ($todayLogin != '') {
            $totalhL = 8 - $since_start->h;
            $totalmL = 60 - $since_start->i;
            $totalH = $totalhL - $hours2;
            $totalM = $totalmL - $min2;
        } else {
            $totalH = 8 - $hours2;
            $totalM = 60 - $min2;
        }
    }
    // return $min2;
    if ($min2 == 0) {
        return $totalH . ':0';
    } else {
        return $totalH . ':0';
        // return $totalH.':'.$totalM;
    }
}
function TodaytaskAssignForFree($user_id)
{
    global $con;

    // Get user login time
    $todayLogin = loginTime($user_id);
    if (empty($todayLogin)) {
        return "0 min"; // No login found
    }

    // Convert login time to timestamp
    $loginTimestamp = strtotime($todayLogin);

    // Get the first assigned task for today (earliest time)
    $query = "
        SELECT assign_date 
        FROM webxl_task_assign 
        WHERE user_id = '$user_id' 
          AND DATE(assign_date) = CURDATE() 
        ORDER BY assign_date ASC 
        LIMIT 1
    ";
    $result = mysqli_query($con, $query);

    if ($row = mysqli_fetch_assoc($result)) {
        $taskAssignTime = strtotime($row['assign_date']);

        // Difference in minutes
        $diffMinutes = floor(($taskAssignTime - $loginTimestamp) / 60);

        if ($diffMinutes < 0) {
            $diffMinutes = 0; // Avoid negative values
        }
    } else {
        // If no task assigned today, assume full 8 hours (480 minutes)
        $diffMinutes = 480;
    }

    // Convert minutes to hours:minutes
    $hours = floor($diffMinutes / 60);
    $mins = $diffMinutes % 60;

    // Return both
    return $diffMinutes . " min (" . $hours . "h " . $mins . "m)";
}


