function ramzan($userID, $startData, $endData)
{ // Ramzan salary Detail
    global $con;
    $result = 0;
    $netSalary = 0;
    $month = date('m', strtotime($startData));
    $query = "select * from `webxl_attendance` WHERE user_id = $userID And `date` BETWEEN '$startData' AND '$endData'";

    $retval = mysqli_query($con, $query);
    $cot = mysqli_num_rows($retval);
    if ($cot > 0) {

        $row = mysqli_fetch_assoc($retval);
        do {
            $unpaidleave = 0;
            $paidleave = 0;
            $cutSalary = 0;
            $totalCuting = 0;
            $leaveCut = 0;
            $timeIn = $row['timeIn'];
            $timeOut = $row['timeOut'];
            $late = $row['late_absent'];
            $gotLives = json_decode(AllGovtLeaves($month));
            foreach ($gotLives as $gLives) {
                $listGovt = array($gLives->name);
                if (in_array($late, $listGovt, TRUE)) {
                    if ($late != 'True' && $late != '0:0' && $late != $gLives->name) {
                        $userData = getUserData($row['user_id']);
                        $relaxtion = $userData['relaxationMin'];
                        $netSalary = $userData['netSalary'];
                        $perDaySalary = $netSalary / 30;
                        $perHourSalary = $perDaySalary / 8;
                        $perMinSalary = $perHourSalary / 60;

                        $totalCuting = $cutSalary;
                        $totalSalary = $netSalary - $totalCuting;
                        $parts = explode(':', $late);

                        $minutes = ($parts[0] * 60 + ($parts[1]));
                        $result = $result + $minutes;
                    }
                }
            }
        } while ($row = mysqli_fetch_assoc($retval));
    }
    if ($netSalary > 0) {
        $cutting_salary = round(($perMinSalary * $result), 0);
        return $cutting_salary;
    }
}
