function daybook($cm, $user)
{
    global $con;
    $toDate = date('Y-m-d');
    global $datetime;
    $qury = "select * from `webxl_day_book` where `user_id` ='$user' AND  `method` ='$cm' AND `date` = '$toDate'";

    $run = mysqli_query($con, $qury);
    $count = mysqli_num_rows($run);
    $row = mysqli_fetch_assoc($run);

    if ($count == 1) {
        $follow = $row['followup'];
        $follow = $follow + 1;
        $qu = "UPDATE `webxl_day_book` SET `followup` = '$follow' WHERE `user_id` ='$user' AND  `method` ='$cm' AND `date` = '$toDate'";
        $run = mysqli_query($con, $qu);
    } else {
        $qury = "INSERT INTO `webxl_day_book` (`user_id`, `method`, `followup`, `date`, `last_update`) VALUES ('$user', '$cm', '1', '$toDate', '$datetime')";

        $run = mysqli_query($con, $qury);
    }
    return $run;
}


function getApprovedCount($type)
{
    global $con;

    $base = "FROM webxl_verify_gm
             WHERE alibaba = 'Pending'
             AND (webxl_behalf = '' OR webxl_behalf IS NULL) ";

    if ($type === 'Approved') {
        $where = "AND ceo_disc_status = 'Approved'
                  AND acc_disc_status != 'Rejected' ";
    } elseif ($type === 'Pending') {
        $where = "AND acc_disc_status = 'Rejected' ";
    } elseif ($type === 'Rejected') {
        $where = "AND ceo_disc_status = 'Rejected' ";
    } else {
        return json_encode([]);
    }

    $sql = "SELECT id " . $base . $where . "ORDER BY id DESC";

    $result = mysqli_query($con, $sql);
    if (!$result)
        return json_encode([]);

    $rows = [];
    while ($row = mysqli_fetch_assoc($result)) {
        $rows[] = $row;
    }

    return json_encode($rows);
}
function getApprovedCombinedCount()
{
    global $con;

    $sql = "
        SELECT COUNT(*) AS total
        FROM webxl_verify_gm
