            $sqlCurrency = "SELECT * FROM `webxl_currency` WHERE id='1'";
            $result_c = mysqli_query($con, $sqlCurrency);
            $row_c = mysqli_fetch_assoc($result_c);
            $today_dollar_rate = $row_c['doller'];
            $new_pkr = $today_dollar_rate * $total_dollar_h_d;
            $old_pkr = $old_dollar_rate * $total_dollar_h_d;

            if ($dominKey > 0) {
                $sdate = $row_domain['start_date'];
                $edate = $row_domain['end_date'];
                $newdate = date('Y-m-d');

                $new_end_date = date('Y-m-d', strtotime($edate . ' - 30 days'));
                if ($newdate >= $new_end_date && $edate > $newdate) {

                    $n++;
                    $total_new_pkr = $total_new_pkr + $new_pkr;
                };
            }
        } while ($row = mysqli_fetch_assoc($retval));
    }
    return round($total_new_pkr, 0);
}
