function getMACAddress()
{
    ob_start();
    // Execute the command to get MAC addresses
    system('getmac');
    $output = ob_get_clean();

    // Split the output by lines
    $lines = explode("\n", $output);

    // Iterate over the lines to find a valid MAC address
    foreach ($lines as $line) {
        if (preg_match('/([0-9A-F]{2}[:-]){5}([0-9A-F]{2})/i', $line, $matches)) {
            return $matches[0];
        }
    }

    return 'MAC Address not found';
}
function getClientIP()
{
    $ipAddress = '';
    if (!empty($_SERVER['HTTP_CLIENT_IP'])) {
        // IP address from shared internet
        $ipAddress = $_SERVER['HTTP_CLIENT_IP'];
    } elseif (!empty($_SERVER['HTTP_X_FORWARDED_FOR'])) {
        // IP address from the proxy
        $ipAddress = $_SERVER['HTTP_X_FORWARDED_FOR'];
    } else {
        // IP address from the remote address
        $ipAddress = $_SERVER['REMOTE_ADDR'];
    }
    return $ipAddress;
}
function getSystemName()
{
    return gethostname();
}
function getUserAgent()
{
    return $_SERVER['HTTP_USER_AGENT'];
}
// ______________________________Habib function Implementation()____________________________
function logActivity($action_type, $description, $user_id = null, $username = null, $table_name = null, $record_id = null, $old_values = null, $new_values = null, $module = null, $status = 'success')
{
    global $con; // Using your database connection variable

    try {
        // Get user IP address using your existing function
        $ip_address = getClientIP();

        // Get user agent using your existing function
        $user_agent = getUserAgent();

        // Convert arrays to JSON strings
        $old_values_json = $old_values ? json_encode($old_values) : null;
        $new_values_json = $new_values ? json_encode($new_values) : null;

        $sql = "INSERT INTO activity_logs (
            user_id, username, action_type, action_description, 
            table_name, record_id, old_values, new_values, 
            ip_address, user_agent, module, status
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)";

        $stmt = mysqli_prepare($con, $sql);
        mysqli_stmt_bind_param(
            $stmt,
            "issssissssss",
            $user_id,
            $username,
            $action_type,
            $description,
            $table_name,
            $record_id,
            $old_values_json,
            $new_values_json,
            $ip_address,
            $user_agent,
            $module,
            $status
        );

        return mysqli_stmt_execute($stmt);
    } catch (Exception $e) {
        // Log error to error log file if database logging fails
        error_log("Activity Log Error: " . $e->getMessage());
        return false;
    }
}
