///////////////////////////////////////////////LatestfollowupMethod////////////////////////////////
if (isset($_POST['comname']) && isset($_POST['meeting_user'])) {

    mysqli_report(MYSQLI_REPORT_ERROR | MYSQLI_REPORT_STRICT);

    try {
        $comname = mysqli_real_escape_string($con, $_POST['comname']);
        $meeting_user = mysqli_real_escape_string($con, $_POST['meeting_user']);

        $reservation = isset($_POST['reservation']) ? mysqli_real_escape_string($con, $_POST['reservation']) : '';

        $talk_mint_res = 'NULL';
        if (isset($_POST['talk_mint_res']) && trim($_POST['talk_mint_res']) !== '') {
            $talk_mint_res = (int) $_POST['talk_mint_res'];
        }

        $main_services = (isset($_POST['main_services']) && is_array($_POST['main_services'])) ? $_POST['main_services'] : [];
        if (empty($main_services)) {
            echo "Error: No main service selected!";
            exit;
        }

        $main_service_id_map = [
            '1' => '316',
            '2' => '317',
            '3' => '318',
            '4' => '319',
            '5' => '332'
        ];

        $uname = username($user_id);

        $selected_services = [];
        $all_grades = [];
        $all_purposes = [];
        $all_methods = [];
        $all_comments = [];
        $all_notes = [];

        $locked_services = [];
        $maxIdx = 50;

        foreach ($main_services as $service_id_raw) {

            $service_key = (string) $service_id_raw;
            $db_service_id = $main_service_id_map[$service_key] ?? $service_key;

            $subKey = "sub_services_{$service_key}";
            $selected_names = (isset($_POST[$subKey]) && is_array($_POST[$subKey])) ? $_POST[$subKey] : [];

            for ($idx = 0; $idx <= $maxIdx; $idx++) {
                $purpose = trim($_POST["purpose_{$service_key}_{$idx}"] ?? '');
                $grade = trim($_POST["grade_{$service_key}_{$idx}"] ?? '');
                $method = trim($_POST["method_{$service_key}_{$idx}"] ?? '');
                $comment = trim($_POST["comment_{$service_key}_{$idx}"] ?? '');
                $nextDate = trim($_POST["next_date_{$service_key}_{$idx}"] ?? '');
                $note = trim($_POST["note_{$service_key}_{$idx}"] ?? '');

                $hasAny = ($purpose !== '' || $grade !== '' || $method !== '' || $comment !== '' || $nextDate !== '' || $note !== '');
                if (!$hasAny) {
                    continue;
                }

                if ($purpose === '' || $grade === '' || $method === '' || $comment === '' || $nextDate === '' || $note === '') {
                    echo "Error: Missing required fields for service {$service_key} row {$idx}";
                    exit;
                }

                $talk_time = 'NULL';
                if (isset($_POST["talk_time_{$service_key}_{$idx}"]) && trim($_POST["talk_time_{$service_key}_{$idx}"]) !== '') {
                    $talk_time = (int) $_POST["talk_time_{$service_key}_{$idx}"];
                }

                $sub_service_name = $selected_names[$idx] ?? '';
                if ($sub_service_name === '') {
                    $sub_service_name = array_values($selected_names)[0] ?? ''; 
                }

                $safe_sub_service_name = mysqli_real_escape_string($con, $sub_service_name);

                // Check 2-month (60-day) lock for the service
                $lock_query = "
                    SELECT wfs.added_by, wu.name, wfs.created_at 
                    FROM webxl_follow_up_services wfs 
                    JOIN webxl_followup wf ON wfs.follow_up_id = wf.id 
                    LEFT JOIN webxl_user wu ON wfs.added_by = wu.user_id
                    WHERE wf.com_id = '{$comname}' 
                    AND wfs.service_id = '{$db_service_id}' 
                    AND wfs.service_type = '{$safe_sub_service_name}'
                    AND wfs.created_at >= DATE_SUB(NOW(), INTERVAL 60 DAY) 
                    ORDER BY wfs.id DESC LIMIT 1
                ";
                $lock_res = mysqli_query($con, $lock_query);
                if (mysqli_num_rows($lock_res) > 0) {
                    $lock_row = mysqli_fetch_assoc($lock_res);
                    if ($lock_row['added_by'] != $user_id) {
                        $user_name = $lock_row['name'] ?? 'another user';
                        $created_date = date('F d, Y \a\t h:i A', strtotime($lock_row['created_at']));
                        
                        $service_name_map = ['316' => 'Alibaba Membership', '317' => 'Alibaba Services', '318' => 'Design Development', '319' => 'Domain Hosting', '332' => 'AI Services'];
                        $service_name_locked = $service_name_map[$db_service_id] ?? 'Selected service';
                        
                        $locked_services[] = "'{$sub_service_name}' under '{$service_name_locked}' (locked by {$user_name})";
                        continue;
                    }
                }

                $selected_services[] = [
                    'main_service_id' => $db_service_id,
                    'service_key' => $service_key,
                    'sub_service_name' => $sub_service_name,
                    'service_index' => $idx,
                    'purpose' => mysqli_real_escape_string($con, $purpose),
                    'grade' => mysqli_real_escape_string($con, $grade),
                    'method' => mysqli_real_escape_string($con, $method),
                    'comment' => mysqli_real_escape_string($con, $comment),
                    'next_date' => mysqli_real_escape_string($con, $nextDate),
                    'note' => mysqli_real_escape_string($con, $note),
                    'talk_time' => $talk_time
                ];

                $all_grades[] = $grade;
                $all_purposes[] = $purpose;
                $all_methods[] = $method;
                $all_comments[] = $comment;
                $all_notes[] = $note;
            }
        }

        if (empty($selected_services)) {
            if (!empty($locked_services)) {
                $locked_names = implode(', ', array_unique($locked_services));
                echo "Error:Unable to Proceed|All selected services are currently locked and cannot be updated: {$locked_names}.";
            } else {
                echo "Error: No sub-service data found!";
            }
            exit;
        }

        $first_service = $selected_services[0];

        $primary_purpose = $first_service['purpose'];
        $primary_grade = $first_service['grade'];
        $primary_method = $first_service['method'];
        $primary_note = implode(' | ', array_unique(array_filter(array_map('trim', $all_notes))));
        $primary_talk_time = $first_service['talk_time'];
        $primary_next_date = $first_service['next_date'];

        $service_map = [
            '316' => 'Alibaba Membership',
            '317' => 'Alibaba Services',
            '318' => 'Design Development',
            '319' => 'Domain Hosting',
            '332' => 'AI Services'
        ];

        $service_names = [];
        foreach ($main_services as $sid_raw) {
            $sid_raw = (string) $sid_raw;
            $mapped = $main_service_id_map[$sid_raw] ?? $sid_raw;
            if (isset($service_map[$mapped])) {
                $service_names[] = $service_map[$mapped];
            }
        }
        $service_for = mysqli_real_escape_string($con, implode(', ', $service_names));

        $qury = "
            INSERT INTO `webxl_followup`
            (`com_id`, `uid`, `username`, `purpose_call`, `service_for`, `cm`, `nc`, `ncm`, `answer`, `note`, `tk_mint`, `create_date`)
            VALUES
            ('{$comname}', '{$user_id}', '{$uname}', '{$primary_purpose}', '{$service_for}', '{$primary_method}', '{$primary_next_date}', '{$reservation}', '', '{$primary_note}', {$primary_talk_time}, '{$datetime}')
        ";
        mysqli_query($con, $qury);
        $follow_up_id = mysqli_insert_id($con);

        if (!$follow_up_id) {
            echo "Something went wrong while saving followup.";
            exit;
        }

        foreach ($selected_services as $service_data) {

            $main_service_id = $service_data['main_service_id'];
            $service_key = $service_data['service_key'];
            $sub_service_name = mysqli_real_escape_string($con, $service_data['sub_service_name']);
            $service_index = (int) $service_data['service_index'];
            $grade = mysqli_real_escape_string($con, $service_data['grade']);
            $comment = mysqli_real_escape_string($con, $service_data['comment']);
            $purpose = mysqli_real_escape_string($con, $service_data['purpose']);
            $method = mysqli_real_escape_string($con, $service_data['method']);
            $next_date = mysqli_real_escape_string($con, $service_data['next_date']);
            $note = mysqli_real_escape_string($con, $service_data['note']);
            $talk_time = $service_data['talk_time'];

            $service_insert_query = "
                INSERT INTO `webxl_follow_up_services`
                (`service_id`, `follow_up_id`, `service_type`, `service_grade`, `service_comment`, `purpose`, `method`, `next_date`, `note`, `talk_time`, `added_by`, `created_at`, `updated_at`)
                VALUES
                ('{$main_service_id}', '{$follow_up_id}', '{$sub_service_name}', '{$grade}', '{$comment}', '{$purpose}', '{$method}', '{$next_date}', '{$note}', {$talk_time}, '{$user_id}', '{$datetime}', '{$datetime}')
            ";
            mysqli_query($con, $service_insert_query);
            $service_detail_id = mysqli_insert_id($con);

            $file_input_name = "meeting_proof_{$service_key}_{$service_index}";

            if ($service_detail_id > 0 && isset($_FILES[$file_input_name]) && isset($_FILES[$file_input_name]['name']) && is_array($_FILES[$file_input_name]['name']) && !empty($_FILES[$file_input_name]['name'][0])) {

                $upload_dir = '../uploads/meeting_proofs/';
                if (!is_dir($upload_dir)) {
                    mkdir($upload_dir, 0755, true);
                }

                $allowed_extensions = ['jpg', 'jpeg', 'png', 'gif'];
                $total_files = count($_FILES[$file_input_name]['name']);

                for ($i = 0; $i < $total_files; $i++) {
                    if (!isset($_FILES[$file_input_name]['error'][$i]) || $_FILES[$file_input_name]['error'][$i] != 0) {
                        continue;
                    }

                    $file_name = $_FILES[$file_input_name]['name'][$i] ?? '';
                    $file_tmp = $_FILES[$file_input_name]['tmp_name'][$i] ?? '';
                    $file_size = $_FILES[$file_input_name]['size'][$i] ?? 0;

                    if ($file_name === '' || $file_tmp === '') {
                        continue;
                    }

                    $file_ext = strtolower(pathinfo($file_name, PATHINFO_EXTENSION));
                    if (!in_array($file_ext, $allowed_extensions, true)) {
                        continue;
                    }
                    if ($file_size > 5242880) {
                        continue;
                    }

                    $unique_name = uniqid() . '_' . time() . '.' . $file_ext;
                    $file_path = $upload_dir . $unique_name;

                    if (move_uploaded_file($file_tmp, $file_path)) {
                        $image_insert_query = "
                            INSERT INTO `webxl_follow_up_images`
                            (`user_id`, `company_id`, `follow_up_id`, `service_detail_id`, `image`, `created_at`)
                            VALUES
                            ('{$meeting_user}', '{$comname}', '{$follow_up_id}', '{$service_detail_id}', '{$unique_name}', '{$datetime}')
                        ";
                        mysqli_query($con, $image_insert_query);
                    }
                }
            }
        }

        $ti = "Follow Up";
        $de = "Follow up with multiple services: {$service_for}. Notes: {$primary_note}";
        comHistory($comname, $ti, $de);

        $row_qury = mysqli_fetch_assoc(mysqli_query($con, "SELECT grade FROM `webxl_company` WHERE id = '{$comname}'"));
        if ($row_qury && ($row_qury['grade'] ?? '') != $primary_grade) {
            mysqli_query($con, "UPDATE `webxl_company` SET `grade` = '{$primary_grade}' WHERE id = '{$comname}'");
            $g = $row_qury['grade'];
            comHistory($comname, "Grade Changed", "Company Grade Change from {$g} To {$primary_grade}");
        }

        $checkLast = mysqli_query($con, "SELECT id FROM `webxl_last_followup` WHERE com_id = '{$comname}'");
        if (mysqli_num_rows($checkLast) > 0) {
            $qury = "
                UPDATE `webxl_last_followup`
                SET `uid` = '{$user_id}',
                    `username` = '{$uname}',
                    `cm` = '{$primary_method}',
                    `nc` = '{$primary_next_date}',
                    `ncm` = '{$reservation}',
                    `note` = '{$primary_note}',
                    `create_date` = '{$datetime}'
                WHERE com_id = '{$comname}'
            ";
            mysqli_query($con, $qury);
        } else {
            $qury = "
                INSERT INTO `webxl_last_followup`
                (`com_id`, `uid`, `username`, `cm`, `nc`, `ncm`, `note`, `create_date`)
                VALUES
                ('{$comname}', '{$user_id}', '{$uname}', '{$primary_method}', '{$primary_next_date}', '{$reservation}', '{$primary_note}', '{$datetime}')
            ";
            mysqli_query($con, $qury);
        }
        daybook($primary_method, $user_id);

        if (!empty($locked_services)) {
            $locked_names = implode(', ', array_unique($locked_services));
            echo "Error:Partial Success|Followup saved for unlocked services. However, the following services were skipped because they are locked: {$locked_names}.";
        } else {
            echo "Followup saved successfully with " . count($selected_services) . " services!";
        }
    } catch (Exception $e) {
        error_log("Followup error: " . $e->getMessage());
        echo "Something went wrong while saving followup: " . $e->getMessage();
    }
}



