function checkInvoiceCondition($invoice_id, $con)
{
    $query = "SELECT grand_total, hod FROM webxl_invoice WHERE invoice_id = '$invoice_id' LIMIT 1";
    $result = mysqli_query($con, $query);

    if ($row = mysqli_fetch_assoc($result)) {
        if ($row['grand_total'] == 0 && $row['hod'] == 'Pending') {
            return true;
        }
    }
    return false;
}

//quotation funcation
if (isset($_POST['cotName'])) {
    $errors = [];

    try {
        $coname = mysqli_real_escape_string($con, trim($_POST['cotName']));
        $cotid = mysqli_real_escape_string($con, trim($_POST['cotid']));
        $coContact = mysqli_real_escape_string($con, trim($_POST['coContact']));
        $clientemail = mysqli_real_escape_string($con, trim($_POST['clientemail']));
        $clienaddres = mysqli_real_escape_string($con, trim($_POST['clienaddres']));
        $userid = mysqli_real_escape_string($con, trim($_POST['userid']));
        $fromyear = mysqli_real_escape_string($con, trim($_POST['from_year']));
        $toyear = mysqli_real_escape_string($con, trim($_POST['to_year']));
        $domain = mysqli_real_escape_string($con, trim($_POST['domain']));
        $subTotal = floatval($_POST['subTotalValue']);
        $discount = floatval($_POST['discount']);
        $gstn = mysqli_real_escape_string($con, trim($_POST['gstn']));
        $totalAmount = floatval($_POST['grandTotalValue']);
        $fpay_p = floatval($_POST['fpay_p']);
        $paynote = mysqli_real_escape_string($con, trim($_POST['paynote']));
        $quo_save = mysqli_real_escape_string($con, trim($_POST['quo_save']));
        $quo_type = isset($_POST['quo_type']) ? mysqli_real_escape_string($con, trim($_POST['quo_type'])) : '';
        $min_tim = mysqli_real_escape_string($con, trim($_POST['min_tim']));
        $max_tim = mysqli_real_escape_string($con, trim($_POST['max_tim']));
        $total_time = $min_tim . "-" . $max_tim;
        $dollar_rate = isset($_POST['services']) ? mysqli_real_escape_string($con, trim($_POST['services'])) : '0';

        $datetime = date('Y-m-d H:i:s');

        if (empty($coname))
            $errors[] = "Company name is required";
        if (empty($clientemail))
            $errors[] = "Client email is required";
        if (empty($_POST['productName']) || !is_array($_POST['productName'])) {
            $errors[] = "Product selection is required";
        }

        // Check if user has added a follow-up for this company, but ONLY if they are quoting non-Alibaba services
        $unfollowed_services = [];
        if (!empty($_POST['productName']) && is_array($_POST['productName'])) {
            foreach ($_POST['productName'] as $item_ti) {
                $item_ti_esc = mysqli_real_escape_string($con, $item_ti);
                $service_check = "SELECT name FROM webxl_quotation_services WHERE id = '$item_ti_esc'";
                $service_res = mysqli_query($con, $service_check);
                if ($service_row = mysqli_fetch_assoc($service_res)) {
                    $sname = strtolower($service_row['name']);
                    // If the product is NOT an Alibaba-related service, require a follow-up
                    if (
                        strpos($sname, 'alibaba') === false && 
                        strpos($sname, 'product posting') === false && 
                        strpos($sname, 'minisite') === false && 
                        strpos($sname, 'listing page') === false &&
                        strpos($sname, 'ggs') === false &&
                        strpos($sname, 'kwa') === false &&
                        strpos($sname, 'kap') === false &&
                        strpos($sname, 'psa') === false &&
                        strpos($sname, 'verified supplier') === false
                    ) {
                        // Check if THIS SPECIFIC service has a follow-up
                        $sname_esc = mysqli_real_escape_string($con, $service_row['name']);
                        $has_specific_followup_query = "SELECT wfs.id FROM webxl_follow_up_services wfs JOIN webxl_followup wf ON wfs.follow_up_id = wf.id WHERE wf.com_id = '{$cotid}' AND wfs.added_by = '{$userid}' AND LOWER(wfs.service_type) = LOWER('{$sname_esc}') LIMIT 1";
                        $has_specific_followup_res = mysqli_query($con, $has_specific_followup_query);
                        if (mysqli_num_rows($has_specific_followup_res) == 0) {
                            $unfollowed_services[] = $service_row['name'];
                        }
                    }
                }
            }
        }

        if (count($unfollowed_services) > 0) {
            $errors[] = "You cannot add a quotation for the following services because you have not added a follow-up specifically for them: " . implode(", ", $unfollowed_services) . ". Please add a follow-up first.";
        }

        if (!empty($errors)) {
            throw new Exception("Validation errors: " . implode(", ", $errors));
        }

        $quo_title = "";
        if (!empty($_POST['productName']) && is_array($_POST['productName'])) {
            $service_names = [];
            foreach ($_POST['productName'] as $item_ti) {
                $item_ti = mysqli_real_escape_string($con, $item_ti);
                $service = "SELECT name FROM webxl_quotation_services WHERE id = '$item_ti'";
                $runservice = mysqli_query($con, $service);

                if (!$runservice) {
                    throw new Exception("Service query failed: " . mysqli_error($con));
                }

                if ($rowservice = mysqli_fetch_assoc($runservice)) {
                    $service_names[] = $rowservice['name'];
                }
            }
            $quo_title = implode(" & ", $service_names);
        }

        $update_quo_id = isset($_POST['update_quo_id']) ? mysqli_real_escape_string($con, trim($_POST['update_quo_id'])) : '';

        // Prevent duplicate quotation for the same company and package
        // ONLY apply this if the quotation is for a 'Package' (ignoring 'Services')
        if (stripos($quo_title, 'package') !== false) {
            $check_duplicate = "SELECT quo_id FROM webxl_quotations WHERE com_id = '$cotid' AND quo_title = '$quo_title' AND quo_type = '$quo_type' AND hod_status != 'Rejected'";
            if (!empty($update_quo_id)) {
                $check_duplicate .= " AND quo_id != '$update_quo_id'";
            }
            $dup_result = mysqli_query($con, $check_duplicate);
            if ($dup_result && mysqli_num_rows($dup_result) > 0) {
                throw new Exception("A quotation for '$quo_title' of type '$quo_type' already exists against this company. Only 1 quotation is allowed per package per type per company.");
            }
        }

        if (!empty($update_quo_id)) {
            // Check current status
            $status_query = mysqli_query($con, "SELECT hod_status FROM webxl_quotations WHERE quo_id = '$update_quo_id'");
            $status_row = mysqli_fetch_assoc($status_query);
            $current_status = $status_row['hod_status'] ?? '';

            $status_update_str = "";
            if ($current_status === 'Rejected') {
                $status_update_str = "`hod_status` = 'Pending', `hod_comment` = '', ";
            }

            $sql1 = "UPDATE `webxl_quotations` SET 
                $status_update_str
                `cname` = '$coname', 
                `phone` = '$coContact', 
                `email` = '$clientemail', 
                `address` = '$clienaddres', 
                `sub_total` = '$subTotal', 
                `discount` = '$discount', 
                `grand_total` = '$totalAmount', 
                `gst` = '$gstn', 
                `first_pay` = '$fpay_p', 
                `quo_title` = '$quo_title', 
                `quo_note` = '$paynote', 
                `quo_save` = '$quo_save', 
                `quo_type` = '$quo_type',
                `dliver_time` = '$total_time',
                `dollar_rate` = '$dollar_rate'
            WHERE `quo_id` = '$update_quo_id'";

            $run = mysqli_query($con, $sql1);
            if (!$run) {
                throw new Exception("Main update failed: " . mysqli_error($con));
            }

            $quo_id = $update_quo_id;

            // Delete old items
            $del_items = "DELETE FROM `webxl_quotation_items` WHERE `quo_id` = '$quo_id'";
            mysqli_query($con, $del_items);
        } else {
            $sql1 = "INSERT INTO `webxl_quotations` (
                `com_id`, `cname`, `phone`, `email`, `address`, `user_id`, 
                `sub_total`, `discount`, `grand_total`, `gst`, `first_pay`, 
                `quo_title`, `quo_note`, `quo_save`, `quo_type`, `dliver_time`,`hod_status`,`create_date`, `dollar_rate`
            ) VALUES (
                '$cotid', '$coname', '$coContact', '$clientemail', '$clienaddres', '$userid',
                '$subTotal', '$discount', '$totalAmount', '$gstn', '$fpay_p',
                '$quo_title', '$paynote', '$quo_save', '$quo_type', '$total_time','Pending', '$datetime', '$dollar_rate'
            )";

            $run = mysqli_query($con, $sql1);
            if (!$run) {
                throw new Exception("Main insert failed: " . mysqli_error($con));
            }

            $quo_id = mysqli_insert_id($con);
            if (!$quo_id) {
                throw new Exception("Failed to get quotation ID");
            }
        }

        if (isset($_POST['productName']) && is_array($_POST['productName'])) {
            $item = $_POST['productName'];
            $detail = isset($_POST['detail']) ? $_POST['detail'] : [];
            $rate = isset($_POST['rate']) ? $_POST['rate'] : [];
            $ab_discount = isset($_POST['ab_discount']) ? $_POST['ab_discount'] : [];
            $quantity = isset($_POST['quantity']) ? $_POST['quantity'] : [];
            $fromyear = isset($_POST['from_year']) ? $_POST['from_year'] : [];
            $toyear = isset($_POST['to_year']) ? $_POST['to_year'] : [];
            $domain = isset($_POST['domain']) ? $_POST['domain'] : [];

            $item_count = count($item);

            for ($i = 0; $i < $item_count; $i++) {
                if (!isset($item[$i]) || trim($item[$i]) === '' || !isset($rate[$i]) || !isset($quantity[$i])) {
                    continue;
                }

                $current_item = mysqli_real_escape_string($con, $item[$i]);
                $current_detail = isset($detail[$i]) ? mysqli_real_escape_string($con, $detail[$i]) : '';
                $current_rate = floatval($rate[$i]);
                $current_ab_discount = isset($ab_discount[$i]) ? floatval($ab_discount[$i]) : 0;
                $current_quantity = intval($quantity[$i]);

                // new fields
                $current_fromyear = isset($fromyear[$i]) && !empty($fromyear[$i])
                    ? date("Y-m-d H:i:s", strtotime($fromyear[$i]))
                    : null;

                $current_toyear = isset($toyear[$i]) && !empty($toyear[$i])
                    ? date("Y-m-d H:i:s", strtotime($toyear[$i]))
                    : null;

                $current_domain = isset($domain[$i]) ? mysqli_real_escape_string($con, $domain[$i]) : '';

                $service = "SELECT name FROM webxl_quotation_services WHERE id = '$current_item'";
                $runservice = mysqli_query($con, $service);

                $servicename = '';
                if ($rowservice = mysqli_fetch_assoc($runservice)) {
                    $servicename = mysqli_real_escape_string($con, $rowservice['name']);
                }

                $sqlitem = "INSERT INTO `webxl_quotation_items` (
                    `quo_id`, `item`, `detail`, `unit_price`, `ab_discount`, `qty`, `from_year`, `to_year`, `domain`
                ) VALUES (
                    '$quo_id', '$servicename', '$current_detail', '$current_rate', '$current_ab_discount', '$current_quantity',
                    " . ($current_fromyear ? "'$current_fromyear'" : "NULL") . ",
                    " . ($current_toyear ? "'$current_toyear'" : "NULL") . ",
                    '$current_domain'
                )";

                $run_item = mysqli_query($con, $sqlitem);

                if (!$run_item) {
                    error_log("Item insert failed for item $i: " . mysqli_error($con));
                }
            }
        }

        echo $quo_id;
        // header('Location: https://webexcels.pk/drm/quotation_view.php?id=' . $quo_id);
        exit();
    } catch (Exception $e) {
        error_log("Quotation save error: " . $e->getMessage());
        echo "Error: " . $e->getMessage();
    }
}

