        foreach ($obj->getWorksheetIterator() as $sheet) {
            $getHighestRow = $sheet->getHighestRow();
            for ($i = 2; $i <= $getHighestRow; $i++) {
                $number = 0;
                $number .= $sheet->getCellByColumnAndRow(0, $i)->getValue();
                $call_type = $sheet->getCellByColumnAndRow(1, $i)->getValue();
                $call_date = $sheet->getCellByColumnAndRow(2, $i)->getValue();
                $call_date_e = $sheet->getCellByColumnAndRow(3, $i)->getValue();
                $call_in_out = $sheet->getCellByColumnAndRow(4, $i)->getValue();
                $call_duration = $sheet->getCellByColumnAndRow(5, $i)->getValue();

                if ($call_type == 'VOICE') {
                    $call_date_set = date('Y-m-d H:i:s', strtotime($call_date));
                    $check_phone = "SELECT * FROM webxl_com_detail WHERE phone = '$number'";
                    $rcheckphone = mysqli_query($con, $check_phone);
                    $countphone = mysqli_num_rows($rcheckphone);
                    $rowphone = mysqli_fetch_assoc($rcheckphone);
                    $get_id = $rowphone['com_id'];
                    if ($countphone > 0) {
                        $get_company = "SELECT * FROM webxl_company WHERE id = '$get_id'";
                        $get_com = mysqli_query($con, $get_company);
                        $get_company = mysqli_fetch_assoc($get_com);
                        $get_coname = $get_company['cname'];
                        $get_coid = $get_company['id'];
                        $get_assignId = $get_company['assignId'];

                        $qury = "INSERT INTO `webxl_callbook` (`id`, `user_id_call`, `call_number`, `call_type`, `call_time`, `duration`, `cname`, `com_id`, `assignId`) VALUES (NULL, '$phone_person', '$number', '$call_in_out', '$call_date_set', '$call_duration', '$get_coname', '$get_coid', '$get_assignId')";
                        $run = mysqli_query($con, $qury);

                        $des_cell = "Call Duration is " . $call_duration;
                        $title_his = "Call on Phone";


                        comCallHistory($get_coid, $title_his, $des_cell, $phone_person);

                        $output1 .= '<tr>
         <td>' . $number . '</td>
         <td>' . $get_coname . '</td>
         <td>' . $call_date_set . '</td>
         <td>' . $call_duration . '</td>
         <td>' . $call_in_out . '</td>
          </tr>';
                    } else {
                        $qury = "INSERT INTO `webxl_callbook` (`id`, `user_id_call`, `call_number`, `call_type`, `call_time`, `duration`, `cname`) VALUES (NULL, '$phone_person', '$number', '$call_in_out', '$call_date_set', '$call_duration', 'Null')";
                        $run = mysqli_query($con, $qury);


                        $output1 .= '<tr>
         <td>' . $number . '</td>
         <td>null</td>
         <td>' . $call_date . '</td>
         <td>' . $call_duration . '</td>
         <td>' . $call_in_out . '</td>

          </tr>';
                    }
                }
            }
        }
    } else {
        echo "Invalid file format";
    }
    $output1 .= '</tbody></table>';
    //    header("Location: http://localhost:8080/crm/index.php?datalist=$output1");
    echo $output1;
}
