//invoice funcccation
function createInvoiceFromPayload($con, $data, $datetime)
{
    $doller = doller();
    $rew_newal_domain = isset($data['rew_newal_domain']) ? $data['rew_newal_domain'] : 0;

    $coname = mysqli_real_escape_string($con, $data['invoicecotName']);
    $cotid = mysqli_real_escape_string($con, $data['cotid']);
    $coContact = mysqli_real_escape_string($con, $data['coContact']);
    $clientemail = mysqli_real_escape_string($con, $data['clientemail']);
    $clienaddres = mysqli_real_escape_string($con, $data['clienaddres']);
    $userid = mysqli_real_escape_string($con, $data['userid']);
    $subTotal = mysqli_real_escape_string($con, $data['subTotalValue']);
    $discount = mysqli_real_escape_string($con, $data['discount']);
    $gstn = mysqli_real_escape_string($con, $data['gstn']);
    $totalAmount = mysqli_real_escape_string($con, $data['grandTotalValue']);
    $pkr = mysqli_real_escape_string($con, $data['pkr']);
    $invoice_dep = isset($data['invoice_dep']) ? mysqli_real_escape_string($con, $data['invoice_dep']) : NULL;

    if ($pkr == 0 || $pkr == '0.00') {
        $hod = 'Pending';
    } else {
        $hod = 'Approved';
    }

    $sql_invoice = "UPDATE `webxl_company` SET `invoice_send` = '$datetime' WHERE `id` = '$cotid'";
    mysqli_query($con, $sql_invoice);

    $sql1 = "INSERT INTO `webxl_invoice`
    (`invoice_id`,`is_auto`, `com_id`, `invoice_dep`, `cname`, `phone`, `email`, `address`, `user_id`, `sub_total`, `discount`, `grand_total`, `gst`, `create_date`, `doller_rate`, `domain_renewal`, `hod`, `account`)
    VALUES
    (NULL,'1', '$cotid', " . ($invoice_dep !== NULL ? "'$invoice_dep'" : "NULL") . ", '$coname', '$coContact', '$clientemail', '$clienaddres', '$userid', '$subTotal', '$discount', '$pkr', '$gstn', '$datetime', '$doller', '$rew_newal_domain', '$hod', 'Not Pay')";

    $run = mysqli_query($con, $sql1);

    if (!$run) {
        return [
            'status' => false,
            'message' => mysqli_error($con)
        ];
    }

    $invoice_id = mysqli_insert_id($con);

    $item = $data['productName'];
    $detail = $data['detail'];
    $rate = $data['rate'];
    $quantity = $data['quantity'];
    $discounts = $data['discounts'];
    $total = $data['totalValue'];

    $x = count($rate);

    for ($i = 0; $i < $x; $i++) {
        $itemId = mysqli_real_escape_string($con, $item[$i]);

        $service = "SELECT * FROM `webxl_quotation_services` WHERE `id` = '$itemId'";
        $runservice = mysqli_query($con, $service);
        $rowservice = mysqli_fetch_assoc($runservice);
        $servicename = $rowservice['name'];

        $detailVal = mysqli_real_escape_string($con, $detail[$i]);
        $rateVal = mysqli_real_escape_string($con, $rate[$i]);
        $qtyVal = mysqli_real_escape_string($con, $quantity[$i]);
        $totalVal = mysqli_real_escape_string($con, $total[$i]);
        $discountVal = mysqli_real_escape_string($con, $discounts[$i]);

        $Pkr = $totalVal - $discountVal;

        $sqlitem = "INSERT INTO `webxl_invoice_item`
        (`id`, `invoice_id`, `item`, `detail`, `unit_price`, `qty`, `totalPkr`, `pkr`)
        VALUES
        (NULL, '$invoice_id', '$servicename', '$detailVal', '$rateVal', '$qtyVal', '$totalVal', '$Pkr')";

        $itemRun = mysqli_query($con, $sqlitem);

        if (!$itemRun) {
            return [
                'status' => false,
                'message' => mysqli_error($con)
            ];
        }
    }

    return [
        'status' => true,
        'invoice_id' => $invoice_id
    ];
}

function createDevelopmentDepartmentInvoice($con, $comid, $user, $datetime)
{
    // company data
    $companySql = "SELECT * FROM `webxl_company` WHERE `id` = '$comid' LIMIT 1";
    $companyRun = mysqli_query($con, $companySql);

    if ($companyRun === false) {
        return [
            'status' => false,
            'message' => mysqli_error($con)
        ];
    }

    $companyRow = mysqli_fetch_assoc($companyRun);

    if (!$companyRow) {
        return [
            'status' => false,
            'message' => 'Company not found'
        ];
    }

    // company detail
    $detailSql = "SELECT * FROM `webxl_com_detail` WHERE `com_id` = '$comid' LIMIT 1";
    $detailRun = mysqli_query($con, $detailSql);

    if ($detailRun === false) {
        return [
            'status' => false,
            'message' => mysqli_error($con)
        ];
    }

    $detailRow = mysqli_fetch_assoc($detailRun);

    // variables
    $companyName = $companyRow['cname'];
    $companyAddress = $companyRow['address'];
    $companyPhone = isset($detailRow['phone']) ? $detailRow['phone'] : '';
    $companyEmail = isset($detailRow['email']) ? $detailRow['email'] : '';
    $holderName = isset($detailRow['name']) ? trim($detailRow['name']) : '';

    // payload
    $invoicePayload = [
        'orderDate' => date('m-d-Y'),
        'holdername' => $holderName,
        'invoice_dep' => 'Development',

        'invoicecotName' => $companyName,
        'cotid' => $comid,
        'clientemail' => $companyEmail,
        'coContact' => $companyPhone,
        'userid' => $user,
        'clienaddres' => $companyAddress,

        'services' => 280,
        'productName' => [48],

        'detail' => [
            'Graphically Rich Title Page theme designing<br/>
Branding Style Design<br/>
Professionally Products Listing design<br/>
About us page<br/>
Products listing manage in content style so your ranking will be higher<br/>
Promotion Banners like special Product<br/>
Company Certification Banners<br/>
Factory Production Banner<br/>
Awards Banners<br/>
Exhibition Banner<br/>'
        ],

        'rate' => [199],
        'rateValue' => [199],
        'quantity' => [1],
        'totalValue' => [55720],
        'discounts' => [55720.00],
        'discountValue' => [0],

        'subTotal' => 55720.00,
        'subTotalValue' => 55720.00,
        'gstn' => 0,
        'vatValue' => 0.00,

        'totalAmount' => 55720.00,
        'totalAmountValue' => 55720.00,

        'rew_newal_domain' => 0,
        'discount' => 55720,
        'grandTotal' => 0.00,
        'grandTotalValue' => 0.00,

        'pkr' => 0.00
    ];

    // create invoice
    return createInvoiceFromPayload($con, $invoicePayload, $datetime);
}

