    } else {
        $qu_payment = "INSERT INTO `webxl_status_hod` (`invoice_id`, `com_id`, `acc_status`, `acc_comm`, `hod_status`, `hod_comm`, `create_date`) VALUES ('$invoice_id', '$company_id', '1', 'Approve', '1', 'Approve', '$datetime')";
        $re_payment = mysqli_query($con, $qu_payment);
        if (!$re_payment) {
            echo $con->error;
        }
    }

    $amountDivide = $amount;

    foreach ($projectStart as $item) {

        if ($amountDivide > 0) {
            // Fetch the item data from the database
            $query = "SELECT * FROM webxl_invoice_item WHERE `id` = '$item'";
            $retval = mysqli_query($con, $query);
            $row = mysqli_fetch_assoc($retval);

            $itemAmount = $row['pay']; // Current payment for the item
            $AmountPkr = $row['pkr']; // Total price of the item
            $inv_item = $row['item']; // Item description
            // Item description

            // Calculate the exact 30% payment for the item
            $percentage = 30;
            $payLimit = ($percentage / 100) * $AmountPkr; // 30% of the item's total price

            // Calculate the remaining balance for the item
            $remainingAmount = $AmountPkr - $itemAmount;

            // Determine the maximum payment allowed for this item
            $payReq = min($payLimit, $remainingAmount);

            // Add the payments to each item
            if ($amountDivide > 0) {
                // Calculate the total sum of 30% payments for all items
                $total30PercentAmount = 0;
                $totalItemsQuery = "SELECT * FROM webxl_invoice_item WHERE `invoice_id` = '$invoice_id'";
                $totalItemsResult = mysqli_query($con, $totalItemsQuery);

                while ($totalItem = mysqli_fetch_assoc($totalItemsResult)) {
                    $total30PercentAmount += ($percentage / 100) * $totalItem['pkr']; // Sum of all 30% amounts
                }

                // Determine if the total added amount exceeds the sum of 30% of all items
                if ($amountDivide + $total30PercentAmount > $total30PercentAmount) {
                    // Calculate excess amount
                    $excessAmount = $amountDivide + $total30PercentAmount - $total30PercentAmount;

                    // Proportionally distribute the excess amount across all items based on their 30% share
                    $itemsQuery = "SELECT * FROM webxl_invoice_item WHERE `invoice_id` = '$invoice_id'";
                    $itemsResult = mysqli_query($con, $itemsQuery);

                    while ($itemRow = mysqli_fetch_assoc($itemsResult)) {
                        // Calculate the 30% payment for each item
                        $item30Percent = ($percentage / 100) * $itemRow['pkr'];

                        // Calculate the proportion of the excess amount for each item
                        $itemProportion = $item30Percent / $total30PercentAmount;
                        $additionalPayment = $excessAmount * $itemProportion;

                        // Update the item amount with the additional payment
                        $newItemAmount = $itemRow['pay'] + $additionalPayment;

                        // Update the item in the database
                        $updateQuery = "UPDATE `webxl_invoice_item` SET `pay` = '$newItemAmount' WHERE `id` = '{$itemRow['id']}'";
                        mysqli_query($con, $updateQuery);

                        // Log the additional payment made for this item
                        $logQuery = "INSERT INTO `webxl_invoice_item_pay`(`inv_item_id`, `invoice_id`, `item`, `pay`, `method`) 
                         VALUES ('{$itemRow['id']}', '$invoice_id', '{$itemRow['item']}', '$additionalPayment', '$method')";
                        mysqli_query($con, $logQuery);
                    }

                    // Update remaining balance for the last item
                    $amountDivide = 0; // Fully distributed
                } else {
                    // No excess, just distribute the amountDivide
                    if ($amountDivide >= $payReq) {
                        // Full required payment can be made
                        $itemAmount = $itemAmount + $payReq;
                        $amountDivide = $amountDivide - $payReq;
                    } else {
                        // Partial payment based on remaining amount
                        $itemAmount = $itemAmount + $amountDivide;
                        $amountDivide = 0; // Fully distributed
                    }

                    // Update the item's payment in the database
                    $query1 = "UPDATE `webxl_invoice_item` SET `pay` = '$itemAmount' WHERE `id` = '$item'";
                    mysqli_query($con, $query1);

                    // Log the payment made for this item
                    $loggedPayment = min($payReq, $amountDivide + $payReq); // Log the actual amount added to the item
                    $query_item = "INSERT INTO `webxl_invoice_item_pay`(`inv_item_id`, `invoice_id`, `item`, `pay`, `method`) 
                       VALUES ('$item', '$invoice_id', '$inv_item', '$loggedPayment', '$method')";
                    mysqli_query($con, $query_item);
                }
            }

            // Final adjustment for any leftover amounts
            if ($amountDivide > 0 && $item === $lastItemInLoop) {
                // Add leftover amount to the last item's payment
                $itemAmount = $itemAmount + $amountDivide;
                $amountDivide = 0;

                // Update the last item's payment in the database
                $query1 = "UPDATE `webxl_invoice_item` SET `pay` = '$itemAmount' WHERE `id` = '$item'";
                mysqli_query($con, $query1);

                // Log the leftover adjustment for the item
                $query_item = "INSERT INTO `webxl_invoice_item_pay`(`inv_item_id`, `invoice_id`, `item`, `pay`, `method`) 
                   VALUES ('$item', '$invoice_id', '$inv_item', '$amountDivide', '$method')";
                mysqli_query($con, $query_item);
            }
        }
        if ($amount == 0) {
            $query = "SELECT * FROM webxl_invoice_item WHERE `id` = '$item'";
            $retval = mysqli_query($con, $query);
            $row = mysqli_fetch_assoc($retval);

