        $expense_voucher_number = trim($_POST['add_expense_voucher_number'] ?? '');

        if (empty($expense_phead_id))
            throw new Exception('Please select an expense head.');
        if (empty($add_expense_head_office))
            throw new Exception('Please select an office.');
        if (empty($expense_amount) || !is_numeric($expense_amount) || floatval($expense_amount) <= 0)
            throw new Exception('Please enter a valid amount.');
        if (empty($expense_voucher_number))
            throw new Exception('Please enter a voucher number.');
        if (!is_numeric($expense_voucher_number))
            throw new Exception('Voucher number must be numeric.');
        if (empty($expense_create_date))
            throw new Exception('Please select creation date.');

        $date_obj = DateTime::createFromFormat('Y-m-d\TH:i', $expense_create_date);
        if ($date_obj === false)
            throw new Exception('Invalid date format.');
        $create_date = $date_obj->format('Y-m-d H:i:s');

        $created_by = 1;
        if (!empty($_COOKIE['id'])) {
            $created_by = intval($_COOKIE['id']);
        } elseif (!empty($_SESSION['user_id'])) {
            $created_by = intval($_SESSION['user_id']);
        }

        $con->autocommit(FALSE);

        $stmt = $con->prepare("
            INSERT INTO `webxl_expense`
            (`phead_id`, `head_id`, `office`, `amount`, `detail`, `cheque_id`, `bill_image`, `voucher_number`, `create_date`, `created_by`)
            VALUES (?, ?, ?, ?, ?, ?, NULL, ?, ?, ?)
        ");

        if (!$stmt) {
            throw new Exception('Prepare failed: ' . $con->error);
        }

        $stmt->bind_param(
            "sssdssssi",
            $expense_phead_id,
            $expense_head_id,
            $add_expense_head_office,
            $expense_amount,
            $expense_detail,
            $add_exp_phead_cheque,
            $expense_voucher_number,
            $create_date,
            $created_by
        );

        if (!$stmt->execute()) {
            throw new Exception('Failed to save expense: ' . $stmt->error);
        }

        $expense_id = $con->insert_id;
        $stmt->close();

        if (isset($_FILES['bill_invoice']) && is_array($_FILES['bill_invoice']['name']) && !empty($_FILES['bill_invoice']['name'][0])) {
