            if (!$upload_results['success']) {
                throw new Exception($upload_results['message']);
            }
        }

        $con->commit();

        $response = [
            'success' => true,
            'message' => 'Expense added successfully with Voucher #' . $expense_voucher_number,
            'expense_id' => $expense_id
        ];
    } catch (Exception $e) {
        if (isset($con)) {
            $con->rollback();
        }
        $response['success'] = false;
        $response['message'] = $e->getMessage();
    }

    if (isset($con)) {
        $con->autocommit(TRUE);
    }
    header('Content-Type: application/json');
    echo json_encode($response);
    exit;
}

function handleMultipleFileUploads($files, $expense_id, $created_by, $con)
{
    error_log("=== UPLOAD START ===");
    error_log("Expense ID: $expense_id");
    error_log("Created By: $created_by");
    error_log("Files received: " . print_r($files, true));

    $upload_dir = "../assets/images/expense_bill/";
    if (!is_dir($upload_dir)) {
        mkdir($upload_dir, 0777, true);
    }

    $allowed_ext = ['jpg', 'jpeg', 'png', 'gif', 'bmp', 'webp', 'pdf', 'xls', 'xlsx'];
    $uploaded_count = 0;

    if (!is_array($files['name'])) {
        error_log("❌ Not an array");
        return ['success' => false, 'message' => 'Invalid file upload format'];
    }

    foreach ($files['name'] as $key => $filename) {
        error_log("Processing file $key: $filename");

        if (empty($filename)) {
            error_log("Empty filename, skipping");
            continue;
        }

        if ($files['error'][$key] !== UPLOAD_ERR_OK) {
            error_log("❌ Upload error code: " . $files['error'][$key]);
            return ['success' => false, 'message' => "Upload error for file: $filename (Error code: " . $files['error'][$key] . ")"];
        }

        $tmp_name = $files['tmp_name'][$key];
        error_log("Temp file: $tmp_name");

        if (!file_exists($tmp_name)) {
            error_log("❌ Temp file doesn't exist!");
            return ['success' => false, 'message' => "Temp file not found: $filename"];
        }

        $ext = strtolower(pathinfo($filename, PATHINFO_EXTENSION));
        error_log("Extension: $ext");

        if (!in_array($ext, $allowed_ext)) {
            error_log("❌ Invalid extension");
            return ['success' => false, 'message' => "Invalid file type: $ext"];
        }

        $new_name = 'EXP_' . $expense_id . '_' . time() . '_' . $key . '.' . $ext;
        $target_path = $upload_dir . $new_name;

        error_log("Target path: $target_path");
        error_log("Upload dir exists: " . (is_dir($upload_dir) ? 'YES' : 'NO'));
        error_log("Upload dir writable: " . (is_writable($upload_dir) ? 'YES' : 'NO'));

        if (!move_uploaded_file($tmp_name, $target_path)) {
            error_log("❌ Move file failed!");
            return ['success' => false, 'message' => "Failed to upload: $filename. Check directory permissions."];
        }

        error_log("✅ File moved successfully");

        $expense_id_int = (int) $expense_id;
        $created_by_int = (int) $created_by;

        error_log("Inserting - expense_id: $expense_id_int, image: $new_name, created_by: $created_by_int");

        $img_stmt = $con->prepare("
            INSERT INTO `webxl_expense_images` (`expense_id`, `images`, `created_by`)
            VALUES (?, ?, ?)
        ");

        if (!$img_stmt) {
            error_log("❌ Prepare failed: " . $con->error);
            return ['success' => false, 'message' => 'Prepare failed: ' . $con->error];
        }

        $img_stmt->bind_param("isi", $expense_id_int, $new_name, $created_by_int);

        if (!$img_stmt->execute()) {
            $error = $img_stmt->error;
            $errno = $img_stmt->errno;
            error_log("❌ Execute failed: $error (Code: $errno)");

            $img_stmt->close();

            if (file_exists($target_path)) {
                unlink($target_path);
                error_log("Deleted uploaded file due to DB error");
            }

            return ['success' => false, 'message' => "DB error: $error (Code: $errno) - File: $filename"];
        }

        $img_stmt->close();
        $uploaded_count++;
        error_log("✅ Image $uploaded_count inserted successfully");
    }

    error_log("=== UPLOAD COMPLETE: $uploaded_count files ===");
    return ['success' => true, 'uploaded_count' => $uploaded_count];
}



// Helper function for file upload handling - UPDATED to use voucher number
function handleFileUpload($file, $voucher_number)
{
    $result = array('success' => false, 'message' => '', 'filename' => '');

    if ($file['error'] !== UPLOAD_ERR_OK) {
        $result['message'] = 'File upload failed.';
        return $result;
    }

    $allowed_types = array('jpg', 'jpeg', 'png', 'pdf', 'doc', 'docx');
    $file_extension = strtolower(pathinfo($file['name'], PATHINFO_EXTENSION));

    if (!in_array($file_extension, $allowed_types)) {
        $result['message'] = 'Invalid file type. Allowed: ' . implode(', ', $allowed_types);
        return $result;
    }

    if ($file['size'] > 10 * 1024 * 1024) {
        $result['message'] = 'File size too large. Maximum 10MB allowed.';
        return $result;
    }


    $filename = 'bill_voucher_' . $voucher_number . '_' . time() . '.' . $file_extension;
    $upload_path = "../assets/images/expense_bill/" . $filename;

    $upload_dir = dirname($upload_path);
    if (!is_dir($upload_dir)) {
        mkdir($upload_dir, 0755, true);
    }

    if (move_uploaded_file($file['tmp_name'], $upload_path)) {
        $result['success'] = true;
        $result['filename'] = $filename;
        $result['message'] = 'File uploaded successfully.';
    } else {
        $result['message'] = 'Failed to move uploaded file.';
    }

    return $result;
}

// Optional: Function to get user info from cookie for display purposes
function getUserFromCookie()
{
    $user_id = 1; // Default
    $user_name = 'Unknown'; // Default

    if (isset($_COOKIE['id']) && !empty($_COOKIE['id'])) {
        $user_id = intval($_COOKIE['id']);
    }

    return array('id' => $user_id, 'name' => $user_name);
}

/**
 * Get expense head name by ID
 */
function getExpenseHeadName($head_id)
{
    global $con;

    $stmt = $con->prepare("SELECT expenName FROM webxl_expenses_head WHERE head_id = ?");
    $stmt->bind_param("i", $head_id);
    $stmt->execute();
    $result = $stmt->get_result();

    if ($row = $result->fetch_assoc()) {
        return $row['expenName'];
    }

    return 'Unknown';
}

/**
 * Validate expense data
 */
function validateExpenseData($data)
{
    $errors = array();

    if (empty($data['phead_id'])) {
        $errors[] = 'Expense head is required.';
    }

    if (empty($data['branch'])) {
        $errors[] = 'Office selection is required.';
    }

    if (empty($data['amount']) || !is_numeric($data['amount']) || floatval($data['amount']) <= 0) {
        $errors[] = 'Valid amount is required.';
    }

    if (empty($data['voucher_number']) || !is_numeric($data['voucher_number']) || intval($data['voucher_number']) <= 0) {
        $errors[] = 'Valid voucher number is required.';
    }

    return $errors;
}

/**
 * NEW: Function to validate and process cheque for expense
 */
function validateChequeForExpense($con, $cheque_id, $expense_amount)
{
    $result = array('success' => false, 'message' => '', 'cheque_data' => null);

    try {
        // Get cheque details
        $stmt = $con->prepare("SELECT cheque_id, cheque_type, cheque_status, remain_amount, cheque_number 
                              FROM webxl_cheque_system 
                              WHERE cheque_id = ?");
        $stmt->bind_param("i", $cheque_id);
        $stmt->execute();
        $cheque_result = $stmt->get_result();

        if ($cheque_result->num_rows == 0) {
            throw new Exception('Cheque not found.');
        }

        $cheque_data = $cheque_result->fetch_assoc();
        $stmt->close();

        // Validate cheque type
        if ($cheque_data['cheque_type'] !== 'For Expense') {
            throw new Exception('Cheque is not designated for expenses.');
        }

        // Validate cheque status
        if ($cheque_data['cheque_status'] !== 'un-used') {
            throw new Exception('Cheque is not available for use.');
        }

        // Validate amount
        if ($cheque_data['remain_amount'] < $expense_amount) {
            throw new Exception('Insufficient cheque balance.');
        }

        $result['success'] = true;
        $result['cheque_data'] = $cheque_data;
    } catch (Exception $e) {
        $result['message'] = $e->getMessage();
    }

    return $result;
}

/**
 * NEW: Function to check if voucher number is unique
 */
function isVoucherNumberUnique($con, $voucher_number, $phead_id, $office)
{
    $stmt = $con->prepare("SELECT id FROM webxl_expense WHERE voucher_number = ? AND phead_id = ? AND office = ?");
    $stmt->bind_param("iss", $voucher_number, $phead_id, $office);
    $stmt->execute();
    $result = $stmt->get_result();
    $exists = $result->num_rows > 0;
    $stmt->close();

    return !$exists; // Return true if unique (doesn't exist)
}

/**
 * NEW: Function to generate next available voucher number
 */
function getNextVoucherNumber($con, $phead_id, $office)
{
    $stmt = $con->prepare("SELECT MAX(voucher_number) as max_voucher FROM webxl_expense WHERE phead_id = ? AND office = ?");
    $stmt->bind_param("ss", $phead_id, $office);
    $stmt->execute();
    $result = $stmt->get_result();
    $row = $result->fetch_assoc();
    $stmt->close();

    $max_voucher = $row['max_voucher'] ? intval($row['max_voucher']) : 0;
    return $max_voucher + 1;
}

