// Updated getchildHeads function to handle multiple parent IDs
if (isset($_POST['action']) && $_POST['action'] === 'getchildHeads') {
    $parentIds = isset($_POST['parentId']) ? $_POST['parentId'] : [];

    if (!is_array($parentIds)) {
        $parentIds = [$parentIds];
    }

    $parentIds = array_filter(array_map('intval', $parentIds));

    $options = '<option value="All">All</option>';

    if (!empty($parentIds)) {
        $placeholders = implode(',', array_fill(0, count($parentIds), '?'));

        $query = "SELECT id, head_name, account_code 
                  FROM webxl_coa_transactional_heads 
                  WHERE child_id IN ($placeholders) AND is_active = 1 
                  ORDER BY head_name ASC";

        $stmt = $con->prepare($query);
        $types = str_repeat('i', count($parentIds));
        $stmt->bind_param($types, ...$parentIds);
        $stmt->execute();
        $result = $stmt->get_result();

        if ($result->num_rows > 0) {
            while ($row = $result->fetch_assoc()) {
                $options .= '<option value="' . $row['id'] . '">' .
                    htmlspecialchars($row['account_code'] . ' - ' . $row['head_name']) .
                    '</option>';
            }
        } else {
            $options .= '<option disabled>No Child Heads Found</option>';
        }

        $stmt->close();
    } else {
        $options .= '<option disabled>No Parent Head Selected</option>';
    }

    echo $options;
    exit;
}

// Updated getTransactionalHeads function to handle multiple child IDs
if (isset($_POST['action']) && $_POST['action'] === 'getTransactionalHeads') {
    $childIds = isset($_POST['parentId']) ? $_POST['parentId'] : [];

    if (!is_array($childIds)) {
        $childIds = [$childIds];
    }

    $childIds = array_filter(array_map('intval', $childIds));

    $options = '<option value="All">All</option>';

    if (!empty($childIds)) {
        $placeholders = implode(',', array_fill(0, count($childIds), '?'));

        $query = "SELECT st.id, st.head_name, st.account_code
                  FROM webxl_coa_transactional_heads t
                  INNER JOIN webxl_coa_sub_transactional_heads st ON st.transactional_id = t.id
                  WHERE t.id IN ($placeholders) AND st.is_active = 1
                  ORDER BY st.head_name ASC";

        $stmt = $con->prepare($query);
        $types = str_repeat('i', count($childIds));
        $stmt->bind_param($types, ...$childIds);
        $stmt->execute();
        $result = $stmt->get_result();

        if ($result->num_rows > 0) {
            while ($row = $result->fetch_assoc()) {
                $options .= '<option value="' . $row['id'] . '">' .
                    htmlspecialchars($row['account_code'] . ' - ' . $row['head_name']) .
                    '</option>';
            }
        } else {
            $options .= '<option disabled>No Transactional Heads Found</option>';
        }

        $stmt->close();
    } else {
        $options .= '<option disabled>No Child Head Selected</option>';
    }

    echo $options;
    exit;
}
if (isset($_POST['action']) && $_POST['action'] === 'checkVoucherNumber') {
    $voucherNumber = isset($_POST['voucher_number']) ? trim($_POST['voucher_number']) : '';

    $response = array('exists' => false);

    if (!empty($voucherNumber)) {
        $query = "SELECT COUNT(*) as count FROM webxl_expense WHERE voucher_number = ?";
        $stmt = $con->prepare($query);

        if ($stmt) {
            $stmt->bind_param('s', $voucherNumber);
            $stmt->execute();
            $result = $stmt->get_result();
            $row = $result->fetch_assoc();

            if ($row['count'] > 0) {
                $response['exists'] = true;
            }

            $stmt->close();
        }
    }

    echo json_encode($response);
    exit;
}




