function DrmLoginTimeAccDate($userID, $loginDate)
{
    global $con;
    $query = "SELECT * FROM `webxl_log_history` WHERE `user_id` = '$userID' AND DATE(`log_date`)='$loginDate'";
    $runu = mysqli_query($con, $query);
    $cot0 = mysqli_num_rows($runu);
    if ($cot0 > 0) {
        $rowu = mysqli_fetch_assoc($runu);
        $drmTime = date('h:i A', strtotime($rowu['log_date']));
        return $drmTime;
    }
}
