        function formatMinutesToHoursMinutes($totalMinutes)
        {
            if ($totalMinutes <= 0)
                return '0 minutes';

            $hours = floor($totalMinutes / 60);
            $minutes = $totalMinutes % 60;

            if ($hours > 0 && $minutes > 0) {
                return $hours . ' hours ' . $minutes . ' minutes';
            } elseif ($hours > 0) {
                return $hours . ' hours';
            } else {
                return $minutes . ' minutes';
            }
        }
