function userMonthlyAchiveTarget50Kor100Kor150K2($user_id, $start, $end)
{
    global $con;
    $query = "SELECT webxl_payments.com_id,webxl_payments.amount,webxl_payments.create_date, SUM(webxl_payments.amount) AS TotalMonthVas FROM webxl_payments LEFT JOIN webxl_company ON webxl_payments.com_id=webxl_company.id WHERE webxl_company.assignId = '$user_id' AND webxl_payments.create_date BETWEEN '$start' AND '$end'";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);
    $cotu = mysqli_num_rows($runu);
    $TotalMonthVas = $rowu['TotalMonthVas'];
    return $TotalMonthVas;
}
function AllPayComissionMonthly($start, $end)
{
    global $con;
    $qury1 = "SELECT * FROM webxl_user GROUP BY user_id";
