function AllMonthlyRevenueData($start, $end)
{
    global $con;

    try {
        if (empty($start) || empty($end)) {
            throw new Exception("Start date and end date are required");
        }

        $conditions = [];
        $params = [];
        $types = '';

        $conditions[] = "DATE(e.create_date) BETWEEN ? AND ?";
        $params[] = $start;
        $params[] = $end;
        $types .= 'ss';

        $conditions[] = "p.id = ?";
        $params[] = 9;
        $types .= 'i';

        $whereClause = implode(' AND ', $conditions);

        $query = "
            SELECT 
                p.id as parent_id,
                p.account_code as parent_code,
                p.head_name as parent_head,
                c.id as child_id,
                c.account_code as child_code,
                c.head_name as child_head,
                t.id as trans_id,
                t.head_name as trans_head,
                SUM(e.amount) as total_amount,
                COUNT(e.id) as transaction_count
            FROM 
                webxl_expense e
            LEFT JOIN 
                webxl_coa_sub_transactional_heads st ON e.phead_id = st.id
            LEFT JOIN 
                webxl_coa_transactional_heads t ON st.transactional_id = t.id
            LEFT JOIN 
                webxl_coa_child_heads c ON t.child_id = c.id
            LEFT JOIN 
                webxl_coa_parent_heads p ON t.parent_id = p.id
            WHERE 
                $whereClause
            GROUP BY 
                p.id, p.account_code, p.head_name,
                c.id, c.account_code, c.head_name,
                t.id, t.head_name
            ORDER BY 
                p.account_code ASC, 
                c.account_code ASC
        ";

        $stmt = $con->prepare($query);
        if (!$stmt) {
            throw new Exception("Query preparation failed: " . $con->error);
        }

        $stmt->bind_param($types, ...$params);
        $stmt->execute();
        $result = $stmt->get_result();

        $hierarchicalData = [];
        $grandTotal = 0;
        $totalTransactions = 0;

        while ($row = mysqli_fetch_assoc($result)) {
            $amount = floatval($row['total_amount']);
            $grandTotal += $amount;
            $totalTransactions += intval($row['transaction_count']);

            $parentKey = $row['parent_id'];
            $childKey = $row['child_id'];

            if (!isset($hierarchicalData[$parentKey])) {
                $hierarchicalData[$parentKey] = [
                    'parent_id' => $row['parent_id'],
                    'parent_code' => $row['parent_code'],
                    'parent_head' => $row['parent_head'],
                    'parent_total' => 0,
                    'parent_transactions' => 0,
                    'children' => []
                ];
            }

            if (!isset($hierarchicalData[$parentKey]['children'][$childKey])) {
                $hierarchicalData[$parentKey]['children'][$childKey] = [
                    'child_id' => $row['child_id'],
                    'child_code' => $row['child_code'],
                    'child_head' => $row['child_head'],
                    'child_total' => 0,
                    'child_transactions' => 0,
                    'transactions' => []
                ];
            }

            $hierarchicalData[$parentKey]['children'][$childKey]['transactions'][] = [
                'trans_id' => $row['trans_id'],
                'trans_head' => $row['trans_head'],
                'total_amount' => $amount,
                'transaction_count' => intval($row['transaction_count'])
            ];

            $hierarchicalData[$parentKey]['parent_total'] += $amount;
            $hierarchicalData[$parentKey]['parent_transactions'] += intval($row['transaction_count']);
            $hierarchicalData[$parentKey]['children'][$childKey]['child_total'] += $amount;
            $hierarchicalData[$parentKey]['children'][$childKey]['child_transactions'] += intval($row['transaction_count']);
        }

        $stmt->close();

        return [
            'success' => true,
            'hierarchical' => array_values($hierarchicalData),
            'summary' => [
                'grand_total' => $grandTotal,
                'total_transactions' => $totalTransactions
            ]
        ];
    } catch (Exception $e) {
        return [
            'success' => false,
            'hierarchical' => [],
            'summary' => [
                'grand_total' => 0,
                'total_transactions' => 0
            ]
        ];
    }
}

