function months_between_dates($start_date, $end_date)
{
    $start = new DateTime($start_date);
    $end = new DateTime($end_date);

    $months = array();

    while ($start < $end) {
        $months[] = $start->format('Y-m');
        $start->modify('+1 month');
    }

    return $months;
}
