    // Department totals array
    $deptTotals = [];   // [dep_name => amount_sum]
    $deptGrand = 0;

    // 1) Dedup payments by (com_id, amount) within date range
    // 2) Map invoice -> department (one dep per invoice using MIN(dep_id))
    $sql = "
        SELECT
            p.id,
            p.com_id,
            p.amount,
            p.method,
            p.create_date,
            COALESCE(d.name, 'Unknown') AS dep_name
        FROM webxl_payments p

        JOIN (
            SELECT com_id, amount, MIN(id) AS keep_id
            FROM webxl_payments
            WHERE DATE(create_date) BETWEEN ? AND ?
            GROUP BY com_id, amount
        ) k ON k.keep_id = p.id

        LEFT JOIN (
            SELECT
                ii.invoice_id,
                MIN(qs.dep_id) AS dep_id
            FROM webxl_invoice_item ii
            JOIN webxl_quotation_services qs ON qs.name = ii.item
            GROUP BY ii.invoice_id
        ) inv_dep ON inv_dep.invoice_id = p.invoice_id

        LEFT JOIN webxl_department d ON d.id = inv_dep.dep_id

        ORDER BY p.id DESC
    ";

    $stmt = mysqli_prepare($con, $sql);
    mysqli_stmt_bind_param($stmt, "ss", $startDate, $endDate);
    mysqli_stmt_execute($stmt);
    $result = mysqli_stmt_get_result($stmt);

