    $package = $_POST['package'];
    $hostingServer = $_POST['hostingServer'];
    $sdate = $_POST['adate'];
    $activeD = $_POST['activeD'];
    $domainName = mysqli_real_escape_string($con, $_POST['domainName']);
    $username = mysqli_real_escape_string($con, $_POST['username']);
    $password = mysqli_real_escape_string($con, $_POST['password']);

    $query = "INSERT INTO `webxl_sell` (`com_id`, `domain_name`, `username`, `passowrd`, `reg_date`) VALUES ('$com_id', '$domainName', '$username', '$password', '$fdate')";
    $retval = mysqli_query($con, $query);

    if (!$retval) {
        die("Error in webxl_sell: " . mysqli_error($con));
    }

    $last_id = mysqli_insert_id($con);

    if ($last_id == 0) {
        die("Failed to get last insert ID");
    }

    $newEndingDate = date("Y-m-d", strtotime($sdate . " + " . $activeD . " year"));

    $query = "INSERT INTO `webxl_sell_products` (`sell_id`, `pro_type`, `key_id`, `start_date`, `end_date`, `last_expire`, `deactive_reason`) VALUES ('$last_id', 'domain', '$registry', '$sdate', '$newEndingDate', '0000-00-00', NULL)";
    $retval = mysqli_query($con, $query);

    if (!$retval) {
        die("Error in domain insert: " . mysqli_error($con));
    }

    if ($ssl == 1) {
        $query = "INSERT INTO `webxl_sell_products` (`sell_id`, `pro_type`, `key_id`, `start_date`, `end_date`, `last_expire`, `deactive_reason`) VALUES ('$last_id', 'ssl', '1', '$sdate', '$newEndingDate', '0000-00-00', NULL)";
        $retval = mysqli_query($con, $query);

        if (!$retval) {
            die("Error in ssl insert: " . mysqli_error($con));
        }
    }

    if ($hostingServer != 0) {
        $query = "INSERT INTO `webxl_sell_products` (`sell_id`, `pro_type`, `key_id`, `server_type`, `start_date`, `end_date`, `last_expire`, `deactive_reason`) VALUES ('$last_id', 'hosting', '$package', '$hostingServer', '$sdate', '$newEndingDate', '0000-00-00', NULL)";
        $retval = mysqli_query($con, $query);

        if (!$retval) {
            die("Error in hosting insert: " . mysqli_error($con));
        }
    } else {
        $query = "INSERT INTO `webxl_sell_products` (`sell_id`, `pro_type`, `key_id`, `start_date`, `end_date`, `last_expire`, `deactive_reason`) VALUES ('$last_id', 'hosting', '0', '$sdate', '$newEndingDate', '0000-00-00', NULL)";
        $retval = mysqli_query($con, $query);

        if (!$retval) {
            die("Error in hosting insert: " . mysqli_error($con));
        }
    }

    echo "Success: All data inserted";
}
