if (isset($_POST['usernameTempSalary'])) {
    $u_id = $_POST['usernameTempSalary'];

    // Define datetime
    $datetime = date("Y-m-d H:i:s");

    // Handle empty → 0 for integers
    $grossSalary = (isset($_POST['grossSalary']) && $_POST['grossSalary'] !== '') ? (int) $_POST['grossSalary'] : 0;
    $present = (isset($_POST['present']) && $_POST['present'] !== '') ? (int) $_POST['present'] : 0;
    $leave = (isset($_POST['leave']) && $_POST['leave'] !== '') ? (int) $_POST['leave'] : 0;
    $cuttingMin = (isset($_POST['cuttingMin']) && $_POST['cuttingMin'] !== '') ? (int) $_POST['cuttingMin'] : 0;
    $pendingleavesrupes = (isset($_POST['pendingleavesrupes']) && $_POST['pendingleavesrupes'] !== '')
        ? (int) $_POST['pendingleavesrupes']
        : 0;

    $penalty = (isset($_POST['penalty']) && $_POST['penalty'] !== '') ? (int) $_POST['penalty'] : 0;
    $vas = (isset($_POST['vas']) && $_POST['vas'] !== '') ? (int) $_POST['vas'] : 0;
    $commission3 = $_POST['commission3'] !== '' ? $_POST['commission3'] : 0;
    $alibaba = $_POST['alibaba'] !== '' ? $_POST['alibaba'] : 0;
    $projectCommission = $_POST['projectCommission'] !== '' ? $_POST['projectCommission'] : 0;
    $pppcommission = $_POST['pppcommission'] !== '' ? $_POST['pppcommission'] : 0;
    $postingCommission = $_POST['postingCommission'] !== '' ? $_POST['postingCommission'] : 0;
    $overtimemin = $_POST['overtimemin'] ?: 0;
    $overtimers = $_POST['overtimers'] ?: 0;
    $reward = $_POST['reward'] ?: 0;
    $basicCutting = $_POST['basicCutting'] ?: 0;
    $totalcutting = $_POST['tcutting'] ?: 0;
    $totalSalary = $_POST['totalSalary'] ?: 0;
    $cus_paid_leave = $_POST['cus_paid_leave'] ?: 0;
    $cus_unpaid_leave = $_POST['cus_unpaid_leave'] ?: 0;
    $advanceSalary = $_POST['advanceSalary'] ?: 0;
    $pendingLeave = (isset($_POST['pendingLeave']) && $_POST['pendingLeave'] !== '') ? (int) $_POST['pendingLeave'] : 0;
    // Pending leave calculation
    if ($leave > 1 && $pendingLeave >= 12) {
        $totalPendingLeave = $pendingLeave - ($leave - 1);
    } else {
        $totalPendingLeave = $pendingLeave;
    }

    // Insert salary
    $query = "INSERT INTO `webxl_tem_salary_ship`
    (`user_id`, `grossSalary`, `present`, `leave`, `cuttingMin`, `pendingLeave`,
    `pendingleavesrupes`, `vas`, `commission3`, `alibaba`, `projectCommission`,
    `pppcommission`, `postingCommission`, `overtimemin`, `overtimers`, `reward`,
    `basicCutting`, `tcutting`, `penalty`, `totalSalary`, `create_date`,
    `cus_paid_leave`, `cus_unpaid_leave`)
    VALUES
    ('$u_id','$grossSalary','$present','$leave','$cuttingMin','$totalPendingLeave',
    '$pendingleavesrupes','$vas','$commission3','$alibaba','$projectCommission',
    '$pppcommission','$postingCommission','$overtimemin','$overtimers','$reward',
    '$basicCutting','$totalcutting','$penalty','$totalSalary','$datetime',
    '$cus_paid_leave','$cus_unpaid_leave')";
    if (mysqli_query($con, $query)) {
        echo "✅ Salary inserted successfully.<br>";
    } else {
        echo "❌ Salary Insert Error: " . mysqli_error($con) . "<br>";
    }

    // Update advance salary instalments
    $quryu = "SELECT * FROM webxl_addvance_salary WHERE `status` ='Pending' AND `user_id` = '$u_id'";
    $runu = mysqli_query($con, $quryu);
    while ($rowu = mysqli_fetch_assoc($runu)) {
        if ($rowu['instalment'] != '') {
            $instalment = $rowu['instalment'];
            $remaning = $rowu['remaning'];
            $id = $rowu['id'];
            if ($remaning >= $instalment) {
                $totalRemainig = $remaning - $instalment;
                $query = "UPDATE `webxl_addvance_salary` 
                          SET `remaning`='$totalRemainig' 
                          WHERE `user_id` = '$u_id' AND `id`='$id'";
                if (mysqli_query($con, $query)) {
                    echo "✅ Advance salary updated for ID: $id<br>";
                } else {
                    echo "❌ Advance Update Error: " . mysqli_error($con) . "<br>";
                }
            }
        }
    }

    // Insert loan payment
    $query = "INSERT INTO `webxl_pay_loan` (`user_id`, `pay`, `pay_date`)
              VALUES ('$u_id','$advanceSalary','$datetime')";
    if (mysqli_query($con, $query)) {
        echo "✅ Loan payment inserted successfully.<br>";
    } else {
        echo "❌ Loan Insert Error: " . mysqli_error($con) . "<br>";
    }
}


