    $query = "UPDATE `webxl_task_assign` SET `timespent` = '$currentTime'  WHERE `user_id` = '$user_id' AND id = '$taskID' AND `stauts` = 'Working'";
    $retval = mysqli_query($con, $query);

    $query = "SELECT * FROM `webxl_task_assign` WHERE `id` = '$taskID'";
    $retval = mysqli_query($con, $query);
    $row = mysqli_fetch_assoc($retval);
    $time = $row['timespent'];
    $taskHours = $row['hours'];
    $taskMin = $row['min'];

    $timesp = explode(":", $time);

    $totaltime = $row['totalTimespent'];
    $ttimeSp = explode(":", $totaltime);

    $newHour = (int) $timesp[0] + (int) $ttimeSp[0];
    $newMin = (int) $timesp[1] + (int) $ttimeSp[1];
    $newSec = (int) $timesp[2];

    if ($newMin > 60) {
        $hours = floor($newMin / 60);
        $min = $newMin - ($hours * 60);
        $newHour = $newHour + $hours;
        $newTime = $newHour . ":" . $min . ":" . $newSec;
    } else {
        $newTime = $newHour . ":" . $newMin . ":" . $newSec;
    }

    if ($newHour >= $taskHours) {
        $newTime = $taskHours . ":" . $taskMin . ":" . $newSec;
    }


    $query = "UPDATE `webxl_task_assign` SET `stauts` = 'Stop' , `totalTimespent` = '$newTime', `last_update` = '$datetime'  WHERE `id` = '$taskID'";
    $retval = mysqli_query($con, $query);
}
