function DailyTaskLogHistory($taskID, $user_id, $startDate, $endDate)
{
    global $con;
    $query = "SELECT webxl_task_log_history.user_id,webxl_task_log_history.task_id,webxl_task_log_history.status,webxl_task_log_history.time FROM `webxl_task_log_history`
    WHERE webxl_task_log_history.task_id='$taskID' AND webxl_task_log_history.user_id='$user_id' AND DATE(webxl_task_log_history.create_at) >='$startDate' AND DATE(webxl_task_log_history.create_at) <='$endDate'";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    return json_encode($rowu);
}
function LogHistoryHourMinutesSeconds($taskID, $user_id, $startDate, $endDate)
{
    $events = json_decode(DailyTaskLogHistory($taskID, $user_id, $startDate, $endDate), true);
    // Initialize variables
    $totalSeconds = 0;
    $lastDatetime = null;

    // Process each event
    foreach ($events as $event) {
        $currentDatetime = new DateTime($event['time']);
        $currentStatus = $event['status'];

        if ($lastDatetime !== null && $currentStatus === 'stop') {
            // Calculate the time difference between start and stop events
            $interval = $lastDatetime->diff($currentDatetime);
            $totalSeconds += $interval->s + $interval->i * 60 + $interval->h * 3600;
        }
        if ($currentStatus === 'start') {
            $lastDatetime = $currentDatetime;
        }
    }

    // Format and display the total time in hours, minutes, and seconds
    $hours = floor($totalSeconds / 3600);
    $minutes = floor(($totalSeconds % 3600) / 60);
    $seconds = $totalSeconds % 60;
    return "$hours:$minutes:$seconds";
}
