        $quo_query = mysqli_query($con, "SELECT com_id, user_id, create_date FROM webxl_quotations WHERE quo_id = '$quo_id'");
        if ($quo_data = mysqli_fetch_assoc($quo_query)) {
            $com_id = $quo_data['com_id'];
            $user_id = $quo_data['user_id'];
            $create_date = $quo_data['create_date'];

            // Fetch items for this quotation
            $items_query = mysqli_query($con, "SELECT item FROM webxl_quotation_items WHERE quo_id = '$quo_id'");
            while ($item_row = mysqli_fetch_assoc($items_query)) {
                $item_name = mysqli_real_escape_string($con, $item_row['item']);
                // Get service_id
                $service_query = mysqli_query($con, "SELECT id FROM webxl_quotation_services WHERE name = '$item_name'");
                if ($service_row = mysqli_fetch_assoc($service_query)) {
                    $service_id = $service_row['id'];
                    // Insert into tracker
                    mysqli_query($con, "INSERT INTO webxl_quotation_tracker (quo_id, com_id, user_id, service_id, create_date, is_expire) VALUES ('$quo_id', '$com_id', '$user_id', '$service_id', '$create_date', 0)");
                }
            }
        }
    } else {
        // If status changed to something else or deleted, mark as expired
        mysqli_query($con, "UPDATE webxl_quotation_tracker SET is_expire = 1 WHERE quo_id = '$quo_id'");
    }
}
