/// Add the gm payment in webxl_verify_gm Table

function hasExistingGmForPackage($con, $comid, $packageType)
{
    $comid = mysqli_real_escape_string($con, $comid);
    $packageType = mysqli_real_escape_string($con, $packageType);

    $sql = "SELECT id 
            FROM `webxl_verify_gm` 
            WHERE `com_id` = '$comid' 
              AND `package` = '$packageType'
              AND `status` != 'Rejected'
              AND `status` != 'deleted'
            LIMIT 1";

    $run = mysqli_query($con, $sql);

    if ($run === false) {
        return [
            'status' => false,
            'message' => mysqli_error($con)
        ];
    }

    return [
        'status' => true,
        'exists' => mysqli_num_rows($run) > 0
    ];
}
function createProductListingInvoice($con, $comid, $user, $datetime)
{
    $companySql = "SELECT * FROM `webxl_company` WHERE `id` = '$comid' LIMIT 1";
    $companyRun = mysqli_query($con, $companySql);

    if ($companyRun === false) {
        return [
            'status' => false,
            'message' => mysqli_error($con)
        ];
    }

    $companyRow = mysqli_fetch_assoc($companyRun);

    if (!$companyRow) {
        return [
            'status' => false,
            'message' => 'Company not found'
        ];
    }

    $detailSql = "SELECT * FROM `webxl_com_detail` WHERE `com_id` = '$comid' LIMIT 1";
    $detailRun = mysqli_query($con, $detailSql);

    if ($detailRun === false) {
        return [
            'status' => false,
            'message' => mysqli_error($con)
        ];
    }

    $detailRow = mysqli_fetch_assoc($detailRun);

    $companyName = $companyRow['cname'];
    $companyAddress = $companyRow['address'];
    $companyPhone = isset($detailRow['phone']) ? $detailRow['phone'] : '';
    $companyEmail = isset($detailRow['email']) ? $detailRow['email'] : '';
    $holderName = isset($detailRow['name']) ? trim($detailRow['name']) : '';

    $invoicePayload = [
        'orderDate' => date('m-d-Y'),
        'holdername' => $holderName,
        'invoice_dep' => 'Posting',

        'invoicecotName' => $companyName,
        'cotid' => $comid,
        'clientemail' => $companyEmail,
        'coContact' => $companyPhone,
        'userid' => $user,
        'clienaddres' => $companyAddress,

        'services' => 280,
        'productName' => [57],
        'detail' => ['One Listing page'],
        'rate' => [62],
        'rateValue' => [62],
        'quantity' => [1],
        'totalValue' => [17360],
        'discounts' => [17360.00],
        'discountValue' => [0],

        'subTotal' => 17360.00,
        'subTotalValue' => 17360.00,
        'gstn' => 0,
        'vatValue' => 0.00,

        'totalAmount' => 17360.00,
        'totalAmountValue' => 17360.00,

        'rew_newal_domain' => 0,
        'discount' => 17360,
        'grandTotal' => 0.00,
        'grandTotalValue' => 0.00,
        'pkr' => 0.00
    ];

    return createInvoiceFromPayload($con, $invoicePayload, $datetime);
}
