    $picName = null;

    if (isset($_FILES['online_payment_screen_short']) && $_FILES['online_payment_screen_short']['error'] === UPLOAD_ERR_OK) {
        $pic = $_FILES['online_payment_screen_short']['name'];
        $ex = pathinfo($pic, PATHINFO_EXTENSION);
        $picName = 'pay_' . $comid . '_' . $shorttime . "." . $ex;

        if (!move_uploaded_file($_FILES['online_payment_screen_short']['tmp_name'], "../assets/images/gm_payment_screen_short/$picName")) {
            echo json_encode(['type' => 'error', 'message' => 'Failed to upload file']);
            exit;
        }
    }

    try {
        mysqli_begin_transaction($con);

        $quryu01 = "SELECT * FROM webxl_tem_gm WHERE `com_id` ='$comid' AND (status != 'deleted' AND status != 'clear')";
        $runu01 = mysqli_query($con, $quryu01);

        if (!$runu01) {
            throw new Exception("Database query failed: " . mysqli_error($con));
        }

        $cot01 = mysqli_num_rows($runu01);

        if ($cot01 > 0) {
            mysqli_rollback($con);
            echo json_encode(['type' => 'error', 'message' => 'This gm already rejected']);
            exit;
        }


        $gmCheckBeforeInsert = hasExistingGmForPackage($con, $comid, $package_type);

        if (!$gmCheckBeforeInsert['status']) {
            throw new Exception("GM pre-check failed: " . $gmCheckBeforeInsert['message']);
        }

        $allowInvoiceCreation = !$gmCheckBeforeInsert['exists'];

        $ceo_disc_status = ($extra_dollar_discount > 0) ? 'Pending' : 'Approved';

        $query = "INSERT INTO `webxl_verify_gm` (
            `package`, `price`, `amount`, `dollar_rate`, `discount`, `extra_discount`, `com_id`, `used_quo_id`,
            `user_id`, `add_by`, `member_id`, `order_id`, `status`, `coments`, `create_request`, `renwal`,
            `extension`, `droupout`, `acc_disc_status`, `ceo_disc_status`, `alibaba`, `webxl_pay_status`,
            `webxl_behalf`, `customer_dollars`, `package_price`, `extra_pkr_discount`, `screen_shot`, `expire_date`
        ) VALUES (
            '$package_type', '$payment', '$pkr_amount', '$dollar_rate', '$dollar_discount', '$extra_dollar_discount',
            '$comid', '$used_quo_id', '$user', '$user_id', '$member_id', '$order_id', '$acc_status', '$note', '$datetime', '$newGm',
            '$extension', '$droupout', 'Pending', '$ceo_disc_status', 'Pending', 'Pending', '$delay_amount',
            '$customer_dollars', '$package_price', '$extra_pkr_discount', " . ($picName ? "'$picName'" : "NULL") . ", " . ($expire_date ? "'$expire_date'" : "NULL") . "
        )";

        $retval = mysqli_query($con, $query);

        if (!$retval) {
            throw new Exception("Failed to insert GM: " . mysqli_error($con));
        }

        $last_id = mysqli_insert_id($con);

        if ($used_quo_id > 0) {
            mysqli_query($con, "UPDATE webxl_quotations SET is_used = 1 WHERE quo_id = '$used_quo_id'");
        }

        if ($last_id == 0) {
            throw new Exception("Failed to get inserted GM ID");
        }

        $qcheck = "SELECT * FROM webxl_gmaccount WHERE `com_id` = '$comid'";
        $rcheck = mysqli_query($con, $qcheck);

        if (!$rcheck) {
            throw new Exception("Database query failed: " . mysqli_error($con));
        }

        $countnum = mysqli_num_rows($rcheck);

        if ($countnum > 0) {
            $account_query = "UPDATE `webxl_gmaccount` 
                              SET `user_id` = '$user', `renwal` = '$newGm', `date_btn` = 'enable' 
                              WHERE `com_id` = '$comid'";
        } else {
            $account_query = "INSERT INTO `webxl_gmaccount` 
                              (`com_id`, `user_id`, `startData`, `renwal`, `date_btn`, `create_data`)
                              VALUES 
                              ('$comid', '$user', '0000-00-00', '$newGm', 'enable', '$datetime')";
        }

        $retval = mysqli_query($con, $account_query);

        if (!$retval) {
            throw new Exception("Failed to update GM account: " . mysqli_error($con));
        }

        if (function_exists('ProjectOverviewTokenNo')) {
            $ProjectOverviewTokenNo = ProjectOverviewTokenNo($comid);
            if ($ProjectOverviewTokenNo) {
                $qury = "UPDATE `webxl_dep_project_comm`
                         SET `ab_type` = '$newGm', `ab_package` = '$package_type', `ab_dollars` = '$payment', `ab_cash_status` = '$acc_status'
                         WHERE token = '$ProjectOverviewTokenNo'";
                $run = mysqli_query($con, $qury);

                if (!$run) {
                    throw new Exception("Failed to update project overview: " . mysqli_error($con));
                }
            }
        }

        if ($delay_amount == 'Delay' || $delay_amount == 'Installment') {
            if (isset($_POST['group-a']) && is_array($_POST['group-a'])) {
                $formData = $_POST['group-a'];
                $count_formData = count($formData);

                for ($i = 0; $i < $count_formData; $i++) {
                    $delay_dollars = mysqli_real_escape_string($con, $formData[$i]['delay_dollars']);
                    $delay_pkr_amount = mysqli_real_escape_string($con, $formData[$i]['delay_pkr_amount']);
                    $cheque_no = mysqli_real_escape_string($con, $formData[$i]['cheque_no']);
                    $delay_pay_Data_show = mysqli_real_escape_string($con, $formData[$i]['delay_pay_Data_show']);

                    $delay_query = "INSERT INTO `webxl_verify_gm_delay_amount` (
                        `com_id`, `gmid`, `delay_dollars`, `delay_pkr`, `delay_dollar_status`,
                        `user_id`, `cheque_no`, `pay_date`, `acc_status`, `alibaba`
                    ) VALUES (
                        '$comid', '$last_id', '$delay_dollars', '$delay_pkr_amount', '$delay_amount',
                        '$user', '$cheque_no', '$delay_pay_Data_show', 'Pending', 'Pending'
                    )";

                    $retval = mysqli_query($con, $delay_query);

                    if (!$retval) {
                        throw new Exception("Failed to insert delay amount: " . mysqli_error($con));
                    }
                }
            }
        }

        if (function_exists('webxl_gmaccount_history')) {
            $history_result = webxl_gmaccount_history($comid, 'Gm Created', $user);
            if (!$history_result) {
                error_log("Warning: Failed to add GM history for comid: $comid");
            }
        }

        if (function_exists('send_customer_data_to_api')) {
            $api_response = send_customer_data_to_api($comid, $user_id);
            if (!$api_response) {
                error_log("Warning: Failed to send customer data to API for comid: $comid");
            }
        }

        error_log('DB check start');

        // =========================
        // Auto Invoice Create From GM
        // Only when same package GM does not already exist
        // =========================
        $blockedPackages = ['Kwa', 'Cat', 'Ai', 'Psa', 'SA', 'KAP', 'KWA-KAP', 'China Trip', 'Kwa-Pro', 'Resubmission of BV'];

        if ($allowInvoiceCreation && !in_array($package_type, $blockedPackages)) {

            // 1) Posting Department Invoice
            // $postingInvoice = createPostingDepartmentInvoice($con, $comid, $user, $datetime);

            // if (!isset($postingInvoice['status']) || !$postingInvoice['status']) {
            //     throw new Exception("Posting invoice failed");
            // }

            // 2) Development Department Invoice
            $ddInvoice = createDevelopmentDepartmentInvoice($con, $comid, $user, $datetime);

            if (!isset($ddInvoice['status']) || !$ddInvoice['status']) {
                throw new Exception("Development invoice failed: " . (isset($ddInvoice['message']) ? $ddInvoice['message'] : 'Unknown error'));
            }

            // 3) Product Listing Invoice
            $productListingInvoice = createProductListingInvoice($con, $comid, $user, $datetime);

            if (!isset($productListingInvoice['status']) || !$productListingInvoice['status']) {
                throw new Exception("Product listing invoice failed: " . (isset($productListingInvoice['message']) ? $productListingInvoice['message'] : 'Unknown error'));
            }
        }

        mysqli_commit($con);

        echo json_encode([
            'type' => 'success',
            'message' => 'GM created successfully'
        ]);
    } catch (Exception $e) {
        mysqli_rollback($con);
        error_log("GM Creation Error: " . $e->getMessage());
        echo json_encode([
            'type' => 'error',
            'message' => $e->getMessage()
        ]);
    }
}

