        $query .= ", `package` = '$package_type'";
    }

    $query .= " WHERE `com_id` = '$comidU' AND `id` = '$id_id'";

    $run = mysqli_query($con, $query);

    if ($run) {
        echo "Record updated successfully.";
    } else {
        echo "Error: " . mysqli_error($con);
    }
