function SalaryMakeFunPPppComm2($links, $user_id0)
{
    global $con;

    // 🔥 SECTION 1: Special Users Groups Definition (Lines 5-11)
    // ========================================================
    $vas_commTeam = 0;

    // Special users groups with different conditions
    $specialUsers2600 = [73, 53335, 54188, 54258, 54190, 54209]; // Group 1: 2600+ links
    $specialUsers2080 = [54322, 54357, 54368, 54330, 54170];                   // Group 2: 2080+ links, 7000 reward
    $specialUsers1300 = [54414, 54402, 54367, 54383, 54412];           // Group 3: 1300+ links, 5000 reward  
    $specialUsers1040 = [54424];                                        // Group 4: 1040+ links, 3500 reward

    // Check which group user belongs to
    $isSpecialUser2600 = in_array($user_id0, $specialUsers2600);
    $isSpecialUser2080 = in_array($user_id0, $specialUsers2080);
    $isSpecialUser1300 = in_array($user_id0, $specialUsers1300);
    $isSpecialUser1040 = in_array($user_id0, $specialUsers1040);
    $isAnySpecialUser = ($isSpecialUser2600 || $isSpecialUser2080 || $isSpecialUser1300 || $isSpecialUser1040);

    // Database query section (unchanged)
    $query = "SELECT ws.user_id, ws.terget_cat, ws.terget_id, wt.conversion, wt.price, wt.max_amount, wt.reward, wt.type, wt.target_number
    FROM webxl_setterget AS ws
    INNER JOIN webxl_terget AS wt ON ws.terget_id = wt.terget_id
    WHERE wt.type = 'new' AND ws.user_id = '$user_id0' AND ws.terget_cat = 7
    AND ws.terget_id IN (SELECT terget_id FROM webxl_setterget WHERE user_id = '$user_id0')
    ORDER BY (CASE WHEN wt.price <= '$links' AND wt.max_amount >= '$links' THEN 1 ELSE 2 END), ws.id DESC
    LIMIT 1;";

    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);

    // 🔥 SECTION 2: Main Logic Implementation (Lines 35-58)
    // ====================================================
    if ($rowu) {
        $target_numberPrice = $rowu['price'];
        $reward = $rowu['reward'];
        $max_amount = $rowu['max_amount'];

        // Special users conditions - ONLY special conditions, NO normal calculation
        if ($isAnySpecialUser) {
            // 🎯 GROUP 1: Original special users (2600+ links)
            if ($isSpecialUser2600 && $links >= 2600) {
                $vas_commTeam = $reward; // Database se reward amount
                // 🎯 GROUP 2: New users (2080+ links, Fixed 7000 reward)
            } else if ($isSpecialUser2080 && $links >= 2080) {
                $vas_commTeam = 7000; // Fixed reward
                // 🎯 GROUP 3: New users (1300+ links, Fixed 5000 reward)
            } else if ($isSpecialUser1300 && $links >= 1300) {
                $vas_commTeam = 5000; // Fixed reward
                // 🎯 GROUP 4: New user (1040+ links, Fixed 3500 reward)
            } else if ($isSpecialUser1040 && $links >= 1040) {
                $vas_commTeam = 3500; // Fixed reward
            } else {
                $vas_commTeam = 0; // Special user but didn't meet their condition
            }
        } else {
            // Normal users: standard range-based calculation
            if ($links >= $target_numberPrice && $links <= $max_amount) {
                $vas_commTeam = $reward;
            } else {
                $vas_commTeam = 0;
            }
        }

        // Debug information
        $userType = 'Normal';
        if ($isSpecialUser2600)
            $userType = 'Special2600';
        else if ($isSpecialUser2080)
            $userType = 'Special2080';
        else if ($isSpecialUser1300)
            $userType = 'Special1300';
        else if ($isSpecialUser1040)
            $userType = 'Special1040';

        error_log("DEBUG - User: $user_id0, Links: $links, Type: $userType" .
            ", Target: $target_numberPrice-$max_amount, DB_Reward: $reward, Final Commission: $vas_commTeam");

        // 🔥 SECTION 3: Fallback for Users without DB Record (Lines 72-82)
        // ================================================================
    } else {
        error_log("DEBUG - No matching record found for user: $user_id0");

        // Even without DB record, check special users with fixed rewards
        if ($isSpecialUser2080 && $links >= 2080) {
            $vas_commTeam = 7000;        // GROUP 2
        } else if ($isSpecialUser1300 && $links >= 1300) {
            $vas_commTeam = 5000;        // GROUP 3  
        } else if ($isSpecialUser1040 && $links >= 1040) {
            $vas_commTeam = 3500;        // GROUP 4
        }
        // Note: Special2600 users need DB record for reward amount
    }

    return $vas_commTeam;
}
