        'Q2' => ['start' => '-07-01', 'end' => '-09-30', 'months' => ['Jul', 'Aug', 'Sep']],
        'Q3' => ['start' => '-10-01', 'end' => '-12-31', 'months' => ['Oct', 'Nov', 'Dec']],
        'Q4' => ['start' => '-01-01', 'end' => '-03-31', 'months' => ['Jan', 'Feb', 'Mar']]
    ];

    $result = [];
    $start_year = date('Y', strtotime($start_date));
    $end_year = date('Y', strtotime($end_date));

    for ($year = $start_year; $year <= $end_year; $year++) {
        foreach ($quarters as $quarter_name => $quarter) {
            $quarter_start = ($quarter_name == 'Q4' && $year == $start_year) ? $start_year . $quarter['start'] : $year . $quarter['start'];
            $quarter_end = ($quarter_name == 'Q4' && $year == $start_year) ? $start_year . $quarter['end'] : $year . $quarter['end'];

            if (
                ($quarter_start >= $start_date && $quarter_start <= $end_date) ||
                ($quarter_end >= $start_date && $quarter_end <= $end_date) ||
                ($start_date >= $quarter_start && $end_date <= $quarter_end)
            ) {

                $result[] = [
                    'year' => $year,
                    'quarter' => $quarter_name,
                    'months' => $quarter['months'],
                    'start_date' => $quarter_start,
                    'end_date' => $quarter_end
                ];
            }
        }
    }

    return $result;
}

