// Add KWA into webxl advance kwa table  
function userABtargetAchiveCountNum($user_id, $sDate, $eDate)
{
    global $con;
    $query = "SELECT webxl_gmaccount.user_id,webxl_gmaccount.com_id,webxl_gmaccount.startData,webxl_gmaccount.id, COUNT(webxl_gmaccount.id) AS TotalCountId,webxl_verify_gm.renwal FROM webxl_gmaccount
    LEFT JOIN webxl_verify_gm ON webxl_gmaccount.com_id=webxl_verify_gm.com_id WHERE webxl_verify_gm.renwal=1 AND webxl_gmaccount.user_id='$user_id' AND DATE(webxl_gmaccount.startData) >= '$sDate' AND DATE(webxl_gmaccount.startData) <= '$eDate'";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);
    $TotalCountId = $rowu['TotalCountId'];
    return $TotalCountId;
}
function userABtargetAchiveCountNumPay($user_id, $sDate, $eDate)
{
    global $con;
    $query = "SELECT webxl_gmaccount.user_id,webxl_gmaccount.com_id,webxl_gmaccount.startData,webxl_gmaccount.id, COUNT(webxl_gmaccount.id) AS TotalCountId,webxl_verify_gm.renwal,webxl_verify_gm.pay_date,webxl_verify_gm.create_date FROM webxl_gmaccount
    LEFT JOIN webxl_verify_gm ON webxl_gmaccount.com_id=webxl_verify_gm.com_id WHERE webxl_verify_gm.renwal=1 AND webxl_gmaccount.user_id='$user_id' AND DATE(webxl_verify_gm.create_date)  >=  '$sDate' AND DATE(webxl_verify_gm.create_date) <= '$eDate'";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);
    $TotalCountId = $rowu['TotalCountId'];
    return $TotalCountId;
}
function userABtargetAchiveCountNumTotalPayDate($sDate, $eDate)
{
    global $con;
    $query = "SELECT webxl_verify_gm.id, COUNT(webxl_verify_gm.id) AS TotalCountId,webxl_verify_gm.renwal,webxl_verify_gm.pay_date FROM webxl_verify_gm
     WHERE webxl_verify_gm.renwal=1 AND DATE(webxl_verify_gm.create_date) >= '$sDate' AND DATE(webxl_verify_gm.create_date) <= '$eDate'";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);
    $TotalCountId = $rowu['TotalCountId'];
    return $TotalCountId;
}
function userABtargetAchiveCountNumTotal($sDate, $eDate)
{
    global $con;
    $query = "SELECT webxl_gmaccount.user_id,webxl_gmaccount.com_id,webxl_gmaccount.startData,webxl_gmaccount.id, COUNT(webxl_gmaccount.id) AS TotalCountId,webxl_verify_gm.renwal FROM webxl_gmaccount
    LEFT JOIN webxl_verify_gm ON webxl_gmaccount.com_id=webxl_verify_gm.com_id WHERE webxl_verify_gm.renwal=1 AND DATE(webxl_gmaccount.startData) BETWEEN '$sDate' AND '$eDate'";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);
    $TotalCountId = $rowu['TotalCountId'];
    return $TotalCountId;
}
function DropoutTiltle($idNum)
{
    global $con;

    if ($idNum == 1) {
        $dropoutName = 'Basic Drop';
    } elseif ($idNum == 2) {
        $dropoutName = 'Basic Plus Drop';
    } elseif ($idNum == 3) {
        $dropoutName = 'Basic P/D';
    } elseif ($idNum == 4) {
        $dropoutName = 'Basic Plus P/D';
    } elseif ($idNum == 5) {
        $dropoutName = 'Pkg Update';
    } else {
        $dropoutName = 'None';
    }
    return $dropoutName;
}
