if (isset($_POST['files']) && isset($_POST['categoryHead'])) {
    $response = array('success' => false, 'error' => '', 'downloadUrl' => '');
    $files = $_POST['files'];
    $categoryHead = $_POST['categoryHead'];
    $error = ""; // error holder

    if (count($files) > 0) {
        $file_folder = "assets/posting_data/"; // folder to load files
        if (extension_loaded('zip')) {
            // Checking ZIP extension is available
            $zip = new ZipArchive(); // Load zip library
            $zip_name = $categoryHead . ".zip"; // Zip name
            $zip_path = $file_folder . $zip_name;

            if ($zip->open($zip_path, ZIPARCHIVE::CREATE) !== TRUE) {
                // Opening zip file to load files
                $error .= "* Sorry ZIP creation failed at this time";
            } else {
                foreach ($files as $file) {
                    $filePath = $file_folder . $file;
                    if (file_exists($filePath)) {
                        $zip->addFile($filePath, basename($file)); // Adding files into zip
                    } else {
                        $error .= "* File " . $file . " does not exist. ";
                    }
                }
                $zip->close();
                if (file_exists($zip_path)) {
                    $response['success'] = true;
                    $response['downloadUrl'] = $zip_path;
                } else {
                    $error .= "* ZIP file does not exist after creation";
                }
            }
        } else {
            $error .= "* You don't have ZIP extension";
        }
    } else {
        $error .= "* Please select files to zip";
    }

    if ($error != "") {
        $response['error'] = $error;
    }
    echo json_encode($response);
}


function TotaltaskTime($startData, $endData, $user_monthly, $get)
{
    global $con;
    $total_task_time_spent = 0;
    $TotalFreeTime = 0;
    $query = "SELECT * FROM webxl_task_assign WHERE DATE(assign_date) BETWEEN '$startData' AND '$endData' AND `user_id` = '$user_monthly'";
    $retval = mysqli_query($con, $query);
    while ($row = mysqli_fetch_assoc($retval)) {
        $pro_id = $row['pro_id'];
        $task_id = $row['id'];
        $hours = $row['hours'];
        $min = $row['min'];
        $totalTimespent = $row['totalTimespent'];
        $minutes = ($hours * 60 + ($min));
        $total_task_time = $total_task_time + $minutes;
        $hoursT = floor($total_task_time / 60);
        $minT = $total_task_time - ($hoursT * 60);
        $to_time = strtotime($hours . ':' . $min);
        $minutes = ($hours * 60 + ($min));
        $ttimeSp = explode(":", $totalTimespent);
        $newHour = (int) $ttimeSp[0];
        $newMins = (int) $ttimeSp[1];
        $spentTmins = ($newHour * 60 + ($newMins));
        if ((int) $ttimeSp[1] == 60) {
            $newHour = (int) 1 + (int) $ttimeSp[0];
            $newMins = 0;
        }
        $from_time = strtotime($newHour . ':' . $newMins);
        $free2 = round(abs($to_time - $from_time) / 60, 0);
        $total_task_time_spent = $total_task_time_spent + $spentTmins;
        $hoursTS = floor($total_task_time_spent / 60);
        $minTS = $total_task_time_spent - ($hoursTS * 60);
        $TotalFreeTime = $TotalFreeTime + $free2;
        $hoursTSF = floor($TotalFreeTime / 60);
        $minTSF = $TotalFreeTime - ($hoursTSF * 60);
    }

    if ($get == 'taskTime') {
        return $hoursT . ":" . $minT;
    }
    if ($get == 'spentTime') {
        return $hoursTS . ":" . $minTS;
    }
    if ($get == 'freeTime') {
        return $hoursTSF . ":" . $minTSF;
    }
}
function TotaltaskTimePosting($startData, $endData, $user_monthly, $get)
{
    global $con;
    $total_task_time_spent = 0;
    $TotalFreeTime = 0;
    $query = "SELECT * FROM webxl_task_assign WHERE DATE(last_update) BETWEEN '$startData' AND '$endData' AND `user_id` = '$user_monthly'";
    $retval = mysqli_query($con, $query);
    while ($row = mysqli_fetch_assoc($retval)) {
        $pro_id = $row['pro_id'];
        $task_id = $row['id'];
        $hours = $row['hours'];
        $min = $row['min'];
        $totalTimespent = $row['totalTimespent'];
        $minutes = ($hours * 60 + ($min));
        $total_task_time = $total_task_time + $minutes;
        $hoursT = floor($total_task_time / 60);
        $minT = $total_task_time - ($hoursT * 60);
        $to_time = strtotime($hours . ':' . $min);
        $minutes = ($hours * 60 + ($min));
        $ttimeSp = explode(":", $totalTimespent);
        $newHour = (int) $ttimeSp[0];
        $newMins = (int) $ttimeSp[1];
        $spentTmins = ($newHour * 60 + ($newMins));
        if ((int) $ttimeSp[1] == 60) {
            $newHour = (int) 1 + (int) $ttimeSp[0];
            $newMins = 0;
        }
        $from_time = strtotime($newHour . ':' . $newMins);
        $free2 = round(abs($to_time - $from_time) / 60, 0);
        $total_task_time_spent = $total_task_time_spent + $spentTmins;
        $hoursTS = floor($total_task_time_spent / 60);
        $minTS = $total_task_time_spent - ($hoursTS * 60);
        $TotalFreeTime = $TotalFreeTime + $free2;
        $hoursTSF = floor($TotalFreeTime / 60);
        $minTSF = $TotalFreeTime - ($hoursTSF * 60);
    }

    if ($get == 'taskTime') {
        return $hoursT . ":" . $minT;
    }
    if ($get == 'spentTime') {
        return $hoursTS . ":" . $minTS;
    }
    if ($get == 'freeTime') {
        return $hoursTSF . ":" . $minTSF;
    }
}
