////////////////////////  Update Attendance Monthly   //////////////////////////
if (isset($_POST['cuttingUseridNoDaily'])) {

    $cuttingUseridNoDaily = mysqli_real_escape_string($con, $_POST['cuttingUseridNoDaily']);
    $cuttingUseridDaily = mysqli_real_escape_string($con, $_POST['cuttingUseridDaily']);
    $timeInDaily = mysqli_real_escape_string($con, $_POST['timeInDaily']);
    $timeOutDaily = mysqli_real_escape_string($con, $_POST['timeOutDaily']);
    $lateAbsentDaily = mysqli_real_escape_string($con, $_POST['lateAbsentDaily']);

    mysqli_begin_transaction($con);

    try {

        // 1️⃣ Update main user daily attendance
        $updateMain = "
            UPDATE webxl_attendance
            SET timeIn='$timeInDaily',
                timeOut='$timeOutDaily',
                late_absent='$lateAbsentDaily'
            WHERE id='$cuttingUseridNoDaily'
              AND user_id='$cuttingUseridDaily'
        ";

        if (!mysqli_query($con, $updateMain)) {
            throw new Exception("Main update failed: " . mysqli_error($con));
        }

        // 2️⃣ Get date + branch of this record
        $metaQuery = "
            SELECT date, branch
            FROM webxl_attendance
            WHERE id='$cuttingUseridNoDaily'
        ";

        $metaRes = mysqli_query($con, $metaQuery);
        $meta = mysqli_fetch_assoc($metaRes);

        $attendance_date = $meta['date'];
        $branch = mysqli_real_escape_string($con, $meta['branch']);

        $month = (int) date('n', strtotime($attendance_date));
        $year = (int) date('Y', strtotime($attendance_date));

        // 3️⃣ Collect users (main + salary_distribution)
        $usersToUpdate = [$cuttingUseridDaily];

        $salaryQuery = "
            SELECT salary_distribution
            FROM webxl_user
            WHERE user_id='$cuttingUseridDaily'
        ";

        $salaryRes = mysqli_query($con, $salaryQuery);

        if ($salaryRes && mysqli_num_rows($salaryRes) > 0) {
            $salaryData = mysqli_fetch_assoc($salaryRes);
            $salary_distribution = $salaryData['salary_distribution'];

            if (!empty($salary_distribution)) {
                $ids = array_map('trim', explode(",", $salary_distribution));
                foreach ($ids as $uid) {
                    if ($uid !== '' && !in_array($uid, $usersToUpdate)) {
                        $usersToUpdate[] = $uid;
                    }
                }
            }
        }

        // 4️⃣ Update daily attendance for distribution users
        foreach ($usersToUpdate as $uid) {

            if ($uid != $cuttingUseridDaily) {

                $updateDist = "
                    UPDATE webxl_attendance
                    SET timeIn='$timeInDaily',
                        timeOut='$timeOutDaily',
                        late_absent='$lateAbsentDaily'
                    WHERE user_id='$uid'
                      AND date='$attendance_date'
                ";

                if (!mysqli_query($con, $updateDist)) {
                    throw new Exception("Distribution update failed ($uid): " . mysqli_error($con));
                }
            }
        }

        // 5️⃣ Recalculate monthly totals for each user
        foreach ($usersToUpdate as $uid) {

            $aggregate = "
                SELECT
                  SUM(CASE WHEN late_absent='True' THEN 1 ELSE 0 END) AS totalLeaves,
                  SUM(
                    CASE
                      WHEN late_absent <> 'True'
                       AND late_absent REGEXP '^[0-9]+:[0-9]+$'
                      THEN
                        (CAST(SUBSTRING_INDEX(late_absent, ':', 1) AS UNSIGNED) * 60)
                        + CAST(SUBSTRING_INDEX(late_absent, ':', -1) AS UNSIGNED)
                      ELSE 0
                    END
                  ) AS totalLateMinutes
                FROM webxl_attendance
                WHERE user_id='$uid'
                  AND MONTH(date)=$month
                  AND YEAR(date)=$year
            ";

            $aggRes = mysqli_query($con, $aggregate);
            $row = mysqli_fetch_assoc($aggRes);

            $totalLeaves = (int) $row['totalLeaves'];
            $totalLateMinutes = (int) $row['totalLateMinutes'];

            $lateHour = intdiv($totalLateMinutes, 60);
            $lateMin = $totalLateMinutes % 60;

            // 6️⃣ UPSERT monthly table
            $upsert = "
                INSERT INTO webxl_attendance_month
                (user_id, lateHour, lateMin, halfLeave, leaves, branch, month, year)
                VALUES
                ('$uid', '$lateHour', '$lateMin', NULL, '$totalLeaves', '$branch', '$month', '$year')
                ON DUPLICATE KEY UPDATE
                    lateHour = VALUES(lateHour),
                    lateMin  = VALUES(lateMin),
                    halfLeave = NULL,
                    leaves   = VALUES(leaves)
            ";

            if (!mysqli_query($con, $upsert)) {
                throw new Exception("Monthly upsert failed ($uid): " . mysqli_error($con));
            }

            // 7️⃣ Insert history snapshot
            $history = "
                INSERT INTO webxl_attendance_month_history
                (user_id, lateHour, lateMin, halfLeave, leaves, branch, month, year, updated_by, last_update)
                VALUES
                ('$uid', '$lateHour', '$lateMin', NULL, '$totalLeaves', '$branch', '$month', '$year', NULL, NOW())
                ON DUPLICATE KEY UPDATE
                    lateHour = VALUES(lateHour),
                    lateMin = VALUES(lateMin),
                    halfLeave = NULL,
                    leaves = VALUES(leaves),
                    updated_by = VALUES(updated_by),
                    last_update = VALUES(last_update)
            ";


            if (!mysqli_query($con, $history)) {
                throw new Exception("History insert failed ($uid): " . mysqli_error($con));
            }
        }

        mysqli_commit($con);

        echo "Attendance updated and monthly recalculated successfully.";
    } catch (Exception $e) {

        mysqli_rollback($con);
        echo "Error: " . $e->getMessage();
    }
}

