if (isset($_POST['delete_complaint']) && isset($_POST['com_plain_id'])) {
    // Set proper content type for JSON response
    header('Content-Type: application/json');

    $com_plain_id = mysqli_real_escape_string($con, $_POST['com_plain_id']);

    // Debug output (remove in production)
    error_log("Delete complaint called with ID: " . $com_plain_id);

    // Get current datetime for deleted_at
    $deleted_at = date('Y-m-d H:i:s');

    try {
        // Check if record exists and is not already deleted
        $check_query = "SELECT id, is_deleted FROM `webxl_complaints` WHERE `id`='$com_plain_id'";
        $check_result = mysqli_query($con, $check_query);

        if (!$check_result) {
            echo json_encode([
                'status' => 'error',
                'message' => 'Database query failed: ' . mysqli_error($con)
            ]);
            exit();
        }

        if (mysqli_num_rows($check_result) == 0) {
            echo json_encode([
                'status' => 'error',
                'message' => 'Complaint not found with ID: ' . $com_plain_id
            ]);
            exit();
        }

        $record = mysqli_fetch_assoc($check_result);
        if ($record['is_deleted'] == '1') {
            echo json_encode([
                'status' => 'error',
                'message' => 'Complaint is already deleted'
            ]);
            exit();
        }

        // Soft Delete - Update is_deleted to 1 and set deleted_at timestamp
        $qury = "UPDATE `webxl_complaints` SET `is_deleted`='1', `deleted_at`='$deleted_at' WHERE `id`='$com_plain_id' AND `is_deleted`='0'";
        $run = mysqli_query($con, $qury);

        // Debug (remove this in production)
        error_log("Delete Query: " . $qury);
        error_log("Query Result: " . ($run ? 'Success' : 'Failed'));
        error_log("Affected Rows: " . mysqli_affected_rows($con));

        if ($run) {
            $affected_rows = mysqli_affected_rows($con);
            if ($affected_rows > 0) {
                echo json_encode([
                    'status' => 'success',
                    'message' => 'Complaint deleted successfully',
                    'deleted_at' => $deleted_at,
                    'affected_rows' => $affected_rows
                ]);
            } else {
                echo json_encode([
                    'status' => 'error',
                    'message' => 'No rows affected. Record may not exist or already deleted',
                    'query' => $qury
                ]);
            }
        } else {
            echo json_encode([
                'status' => 'error',
                'message' => 'Failed to delete complaint: ' . mysqli_error($con),
                'query' => $qury
            ]);
        }
    } catch (Exception $e) {
        echo json_encode([
            'status' => 'error',
            'message' => 'Database error: ' . $e->getMessage()
        ]);
    }
    exit();
}


