/************ Salary Make Function  ****************/
function SalaryMakeFunTeamVas($user_id)
{
    global $con;
    $query = "SELECT webxl_user.user_id,webxl_user.name,webxl_user.underWork,webxl_invoice.invoice_id,webxl_invoice.com_id,webxl_payments.com_id,webxl_payments.amount,SUM(webxl_payments.amount) AS total_amount,webxl_payments.create_date FROM webxl_user
     LEFT JOIN webxl_invoice ON webxl_user.user_id=webxl_invoice.user_id
     LEFT JOIN webxl_payments ON (webxl_invoice.invoice_id=webxl_payments.invoice_id AND webxl_invoice.com_id=webxl_payments.com_id)
     WHERE MONTH(webxl_payments.create_date) = MONTH(CURRENT_DATE - INTERVAL 1 MONTH) AND YEAR(webxl_payments.create_date) = YEAR(now()) AND webxl_user.underWork='$user_id' GROUP BY webxl_user.user_id";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    return json_encode($rowu);
}
function SalaryMakeFunPersonalVas($user_id)
{
    global $con;
    $query = "SELECT webxl_invoice.user_id,webxl_invoice.com_id,webxl_payments.com_id,webxl_payments.amount,SUM(webxl_payments.amount) AS total_amount,webxl_payments.create_date FROM webxl_invoice
     LEFT JOIN webxl_payments ON (webxl_invoice.invoice_id=webxl_payments.invoice_id AND webxl_invoice.com_id=webxl_payments.com_id)
     WHERE MONTH(webxl_payments.create_date) = MONTH(CURRENT_DATE - INTERVAL 1 MONTH) AND YEAR(webxl_payments.create_date) = YEAR(now()) AND webxl_invoice.user_id='$user_id'";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);
    $total_amount = $rowu['total_amount'];
    if ($user_id == 43) {
        return SalaryMakeFunPersonalVasIT($user_id);
    } else {
        return $total_amount;
    }
}
function SalaryMakeFunPersonalVasIT($user_id)
{
    global $con;
    $query = "SELECT webxl_invoice.user_id,webxl_invoice.com_id,webxl_payments.com_id,webxl_payments.amount,SUM(webxl_payments.amount) AS total_amount,webxl_payments.create_date,webxl_invoice.domain_renewal FROM webxl_invoice
     LEFT JOIN webxl_payments ON (webxl_invoice.invoice_id=webxl_payments.invoice_id AND webxl_invoice.com_id=webxl_payments.com_id)
     WHERE MONTH(webxl_payments.create_date) = MONTH(CURRENT_DATE - INTERVAL 1 MONTH) AND YEAR(webxl_payments.create_date) = YEAR(now()) AND webxl_invoice.user_id='$user_id' AND webxl_invoice.domain_renewal=0";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);
    $total_amount = $rowu['total_amount'];
    return $total_amount;
}
function SalaryMakeFunTeamVasComm($amount, $user_id)
{
    global $con;
    $vas_commTeam = 0;
    $query = "SELECT webxl_setterget.user_id,webxl_setterget.terget_cat,webxl_setterget.terget_id,
    webxl_terget.conversion,webxl_terget.price,webxl_terget.max_amount,webxl_terget.type FROM webxl_setterget
    LEFT JOIN webxl_terget ON webxl_setterget.terget_id=webxl_terget.terget_id
     WHERE webxl_terget.type='new' AND webxl_setterget.user_id='$user_id' AND webxl_setterget.terget_cat=5 AND (webxl_terget.price <= $amount AND webxl_terget.max_amount >= $amount)";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);
    $conversion = $rowu['conversion'];
    $vas_commTeam = round($amount * $conversion / 100, 0);
    return $vas_commTeam;
    mysqli_close($con);
}
function SalaryMakeFunPersonalVasComm($amount, $user_id)
{
    global $con;
    $vas_commTeam = 0;
    $query = "SELECT webxl_setterget.user_id,webxl_setterget.terget_cat,webxl_setterget.terget_id,
    webxl_terget.conversion,webxl_terget.price,webxl_terget.max_amount,webxl_terget.reward,webxl_terget.type FROM webxl_setterget
    LEFT JOIN webxl_terget ON webxl_setterget.terget_id=webxl_terget.terget_id
