function SalaryMakeFunDDProjectComm($amount, $user_id)
{
    global $con;
    $vas_commTeam = 0;
    $query = "SELECT webxl_setterget.user_id,webxl_setterget.terget_cat,webxl_setterget.terget_id,
    webxl_terget.conversion,webxl_terget.price,webxl_terget.max_amount,webxl_terget.reward,webxl_terget.type FROM webxl_setterget
    LEFT JOIN webxl_terget ON webxl_setterget.terget_id=webxl_terget.terget_id
     WHERE webxl_terget.type='new' AND webxl_setterget.user_id='$user_id' AND webxl_setterget.terget_cat=6 AND (webxl_terget.price <= $amount AND webxl_terget.max_amount >= $amount)";
