    $rowu = mysqli_fetch_assoc($runu);
    $conversion = $rowu['conversion'];
    $reward = $rowu['reward'];
    $vas_commTeam = round($amount * $conversion / 100, 0) + $reward;
    return $vas_commTeam;
}
