function AttMonthlyPenalty($user_id, $month, $year)
{
    global $con;
    $total_amount = 0;
    $query = "SELECT webxl_penalty.id,COUNT(webxl_penalty.id) AS total_penalty,webxl_penalty.amount,SUM(webxl_penalty.amount) AS total_amount,webxl_penalty.head,webxl_penalty.user_id,webxl_penalty.date  FROM webxl_penalty
     WHERE webxl_penalty.user_id='$user_id' AND MONTH(webxl_penalty.date) = '$month' AND YEAR(webxl_penalty.date) = '$year'";
    $runu = mysqli_query($con, $query);
    $cot = mysqli_num_rows($runu);
    if ($cot > 0) {
        $rowu = mysqli_fetch_assoc($runu);
        $total_penalty = $rowu['total_penalty'];
        $total_amount = $rowu['total_amount'];
    }

    return $total_amount;
    mysqli_close($con);
}
