function AttMonthlyoverTime($user_id, $month, $year)
{  // Over Time 
    global $con;
    $time = 0;
    $quryu = "SELECT * FROM webxl_overtime WHERE `user_id` = '$user_id' AND `dep` = 'Complete' AND MONTH(create_date) = '$month' AND YEAR(create_date) = '$year'";
