if (isset($_POST['user_id_loanVerify'])) {

    $u_id = (int) $_POST['user_id_loanVerify'];
    $pay_loan_role = $_POST['pay_loan_role'];
    $comm = mysqli_real_escape_string($con, $_POST['comm']);
    $status = $_POST['status'];
    $tid = (int) $_POST['tid'];
    $date = date('Y-m-d');

    // Get original loan record
    $loanQ = mysqli_query($con, "SELECT * FROM webxl_addvance_salary WHERE id = $tid LIMIT 1");
    $loanRow = mysqli_fetch_assoc($loanQ);

    if (!$loanRow)
        exit;

    $totalLoan = (float) $loanRow['salary'];
    $totalInstalment = (float) $loanRow['instalment'];

    // Get distribution users
    $distUsers = getUserDistribution($con, $u_id);

    $totalMembers = 1 + count($distUsers);

    // Divide equally
    $dividedLoan = $totalMembers > 0 ? round($totalLoan / $totalMembers, 0) : $totalLoan;
    $dividedInstalment = $totalMembers > 0 ? round($totalInstalment / $totalMembers, 0) : $totalInstalment;

    if ($pay_loan_role == 48) {

        // 1️⃣ Update MAIN user record
        $updateMain = "
            UPDATE webxl_addvance_salary 
            SET salary = '$dividedLoan',
                instalment = '$dividedInstalment',
                remaning = '$dividedLoan',
                hod = '$status',
                hod_comm = '$comm',
                hod_update = '$date'
            WHERE id = '$tid'
        ";
        mysqli_query($con, $updateMain);

        // 2️⃣ Insert records for distribution users
        foreach ($distUsers as $distUserId) {

            $insertDist = "
                INSERT INTO webxl_addvance_salary 
                (user_id, salary, instalment, remaning, status, detail, manager, hod, hod_comm, create_date)
                VALUES 
                (
                    '$distUserId', 
                    '$dividedLoan', 
                    '$dividedInstalment', 
                    '$dividedLoan',
                    'Pending',
                    'Distribution Loan from User $u_id',
                    'Approved',
                    '$status',
                    'Distribution Loan from User $u_id Approved By HOD',
                    '$date'
                )
            ";

            if (!mysqli_query($con, $insertDist)) {
                die("Insert Error: " . mysqli_error($con));
            }
        }
    } else {

        // Manager update only
        $query = "
            UPDATE webxl_addvance_salary 
            SET manager='$status', 
                mng_comm='$comm', 
                mng_update='$date' 
            WHERE user_id = '$u_id' 
            AND id='$tid'
        ";

        mysqli_query($con, $query);
    }
    if (!mysqli_query($con, $updateMain)) {
        die("Update Error: " . mysqli_error($con));
    }
}


