        $querySalary = "INSERT INTO `webxl_tem_salary_ship`
            (`user_id`, `grossSalary`, `present`, `leave`, `cuttingMin`, `pendingLeave`, `pendingleavesrupes`,
             `vas`, `commission3`, `alibaba`, `projectCommission`, `pppcommission`, `postingCommission`,
