function getUserDistribution($con, $user_id)
{
    $user_id = (int) $user_id;

    $sql = "SELECT salary_distribution FROM webxl_user WHERE user_id = $user_id LIMIT 1";
    $res = mysqli_query($con, $sql);
    if (!$res)
        return [];

    $row = mysqli_fetch_assoc($res);
    if (!$row || empty($row['salary_distribution']))
        return [];

    $parts = explode(',', $row['salary_distribution']);
    $ids = [];

    foreach ($parts as $p) {
        $p = trim($p);
        if ($p !== '' && ctype_digit($p)) {
            $ids[] = (int) $p;
        }
    }

    // unique + clean return
    return array_values(array_unique($ids));
}
