    function postInt($key, $u_id, $default = 0)
    {
        if (isset($_POST[$key . $u_id]) && $_POST[$key . $u_id] !== '' && is_numeric($_POST[$key . $u_id])) {
            return (int) $_POST[$key . $u_id];
        }
        return $default;
    }

    function postStr($key, $u_id, $default = '')
    {
        return isset($_POST[$key . $u_id]) ? mysqli_real_escape_string($GLOBALS['con'], $_POST[$key . $u_id]) : $default;
    }

    foreach ($_POST['usernameTempSalaryAllSalaryOnly'] as $i => $u_id) {
        $datetime = date("Y-m-d H:i:s");

        // Integers
        $grossSalary = postInt('grossSalary', $u_id);
        $present = postInt('present', $u_id);
        $leave = postInt('leave', $u_id);
        $cuttingMin = postInt('cuttingMin', $u_id);
        $pendingLeave = postInt('pendingLeave', $u_id);
        $pendingleavesrupes = postInt('pendingleavesrupes', $u_id);
        $penalty = postInt('penalty_a', $u_id);
        $overtimemin = postInt('overtimemin', $u_id);
        $overtimers = postInt('overtimers', $u_id);
        $basicCutting = postInt('basicCutting', $u_id);
        $totalcutting = postInt('tcutting', $u_id);
        $totalSalary = postInt('totalSalary', $u_id);
        $cus_paid_leave = postInt('cus_paid_leave', $u_id);
        $cus_unpaid_leave = postInt('cus_unpaid_leave', $u_id);
        $advanceSalary = postInt('advanceSalary', $u_id);

        // Pending leave calculation
        if ($leave > 1 && $pendingLeave >= 12) {
            $totalPendingLeave = $pendingLeave - ($leave - 1);
        } else {
            $totalPendingLeave = $pendingLeave;
        }

        // Insert salary
        $query = "INSERT INTO `webxl_tem_salary_ship` 
            (`user_id`, `grossSalary`, `present`, `leave`, `cuttingMin`, `pendingLeave`,
            `pendingleavesrupes`, `overtimemin`, `overtimers`, `basicCutting`, `tcutting`, 
            `penalty`, `totalSalary`, `create_date`, `cus_paid_leave`, `cus_unpaid_leave`) 
            VALUES 
            ('$u_id', '$grossSalary', '$present', '$leave', '$cuttingMin', '$totalPendingLeave',
            '$pendingleavesrupes', '$overtimemin', '$overtimers', '$basicCutting', '$totalcutting', 
            '$penalty', '$totalSalary', '$datetime', '$cus_paid_leave', '$cus_unpaid_leave')";
        mysqli_query($con, $query) or die("Insert Error: " . mysqli_error($con));

        // Advance salary update
        $quryu = "SELECT * FROM webxl_addvance_salary WHERE `status` ='Pending' AND `user_id` = '$u_id'";
        $runu = mysqli_query($con, $quryu);
        while ($rowu = mysqli_fetch_assoc($runu)) {
            if ($rowu['instalment'] !== '') {
                $instalment = (int) $rowu['instalment'];
                $remaning = (int) $rowu['remaning'];
                $id = $rowu['id'];

                if ($remaning >= $instalment) {
                    $totalRemainig = $remaning - $instalment;
                    if ($totalRemainig == 0) {
                        $query = "UPDATE `webxl_addvance_salary` 
                                SET `remaning`='$totalRemainig',`status`='Complete' 
                                WHERE `user_id` = '$u_id' AND `id`='$id'";
                    } else {
                        $query = "UPDATE `webxl_addvance_salary` 
                                SET `remaning`='$totalRemainig' 
                                WHERE `user_id` = '$u_id' AND `id`='$id'";
                    }
                    mysqli_query($con, $query) or die("Advance Update Error: " . mysqli_error($con));
                }
            }
        }

        // Pay loan
        $query = "INSERT INTO `webxl_pay_loan` (`user_id`, `pay`, `pay_date`) 
                VALUES ('$u_id','$advanceSalary','$datetime')";
        mysqli_query($con, $query) or die("Loan Insert Error: " . mysqli_error($con));
    }
}

