function SalaryHeadAndBranch($branch)
{
    global $con;
    $query = "SELECT webxl_tem_salary_ship.id,webxl_tem_salary_ship.user_id,webxl_tem_salary_ship.totalSalary,webxl_tem_salary_ship.create_date,SUM(webxl_tem_salary_ship.totalSalary) AS AlltotalSalary,webxl_user.branch FROM webxl_tem_salary_ship
    LEFT JOIN webxl_user ON (webxl_tem_salary_ship.user_id=webxl_user.user_id)
    WHERE webxl_user.branch='$branch' AND MONTH(webxl_tem_salary_ship.create_date) = MONTH(now()) AND YEAR(webxl_tem_salary_ship.create_date) = YEAR(now())";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);
    $AlltotalSalary = $rowu['AlltotalSalary'];
    return $AlltotalSalary;
}
