    $cot = mysqli_num_rows($retval);
    if ($cot > 0) {
        $row = mysqli_fetch_assoc($retval);
        do {

            $getUserData = getUserData($row['user_id']);
            $userRoleDep00 = userRoleDep($getUserData['roleId']);
            if ($userRoleDep == $userRoleDep00) {
                $i++;
            }
        } while ($row = mysqli_fetch_assoc($retval));
    }
    return $i;
}
