function DailyTalkTime($user_id)
{
    global $con;
    $qury_tm = "SELECT SUM(talk_time) AS Totaltalk_mint FROM `webxl_follow_up_services` WHERE `added_by` ='$user_id' AND DATE(created_at) = CURDATE()";
    $retval_tm = mysqli_query($con, $qury_tm);
    $row_tm = mysqli_fetch_assoc($retval_tm);
    $Totaltalk_mint = $row_tm['Totaltalk_mint'];
    return $Totaltalk_mint;
}
function DailyTalkTimeuser($user_id)
{
    global $con;

    $sql = "SELECT IFNULL(SUM(talk_time),0) AS Totaltalk_mint
            FROM webxl_follow_up_services
            WHERE added_by = '$user_id'
              AND DATE(create_date) = CURDATE()";

    $res = mysqli_query($con, $sql);
