    return (int) ($row['Totaltalk_mint'] ?? 0);
}
function TalkStatsByMethod($user_id, $interval = '1 DAY', $role_id = null)
{
    global $con;

    $allowed = ['1 DAY', '1 WEEK', '1 MONTH', '3 MONTH'];
    if (!in_array($interval, $allowed))
        $interval = '1 DAY';

    if ($role_id == 25) {
        $date_col = 'created_at';
        $method_col = 'method';
        $time_col = 'talk_time';
        $user_col = 'added_by';
        $table = 'webxl_follow_up_services';
    } else {
        $date_col = 'create_date';
        $method_col = 'cm';
        $time_col = 'tk_mint';
        $user_col = 'uid';
        $table = 'webxl_followup';
    }

    if ($interval === '1 DAY') {
        $where = "DATE($date_col) = CURDATE()";
    } else {
        $where = "$date_col >= DATE_SUB(NOW(), INTERVAL $interval)";
    }

    $sql = "SELECT $method_col AS method,
                   COUNT(*) AS total_calls,
                   IFNULL(SUM($time_col),0) AS total_talk_time
            FROM $table
            WHERE $user_col = '$user_id'
              AND $where
            GROUP BY $method_col";

    $res = mysqli_query($con, $sql);

    $map = [];
    while ($row = mysqli_fetch_assoc($res)) {
        $map[$row['method']] = [
            'calls' => (int) $row['total_calls'],
            'talk' => (int) $row['total_talk_time'],
        ];
    }

    return $map;
}
function userDailyTargetAdmin($method, $user_id, $start_date, $end_date)
{
    global $con;

    $method = mysqli_real_escape_string($con, $method);
    $user_id = (int) $user_id;
    $start_date = mysqli_real_escape_string($con, $start_date);
    $end_date = mysqli_real_escape_string($con, $end_date);

    $query = "SELECT IFNULL(SUM(followup), 0) AS total_followup
              FROM webxl_day_book
              WHERE method = '$method'
                AND user_id = '$user_id'
                AND DATE(date) BETWEEN '$start_date' AND '$end_date'";

    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);

    return (int) ($rowu['total_followup'] ?? 0);
}

