function TotalTalkTimeUser($user_id, $interval = '1 DAY')
{
    global $con;

    $allowed = ['1 DAY', '1 WEEK', '1 MONTH', '3 MONTH'];
    if (!in_array($interval, $allowed))
        $interval = '1 DAY';

    if ($interval === '1 DAY') {
        $where = "DATE(create_date) = CURDATE()";
    } else {
        $where = "create_date >= DATE_SUB(NOW(), INTERVAL $interval)";
    }

    $sql = "SELECT IFNULL(SUM(talk_time),0) AS total_talk
            FROM webxl_follow_up_services
            WHERE added_by = '$user_id'
              AND $where";

    $res = mysqli_query($con, $sql);
    $row = mysqli_fetch_assoc($res);

    return (int) ($row['total_talk'] ?? 0);
}


