if (isset($_POST['meeting_start_manager'])) {

    if (isset($_COOKIE['id']) && isset($_COOKIE['role_id'])) {

        $meeting_start_manager = (int) $_POST['meeting_start_manager']; // user_id (target user)
        $meeting_by = (int) $_COOKIE['id'];                  // starter
        $r_id = (int) $_COOKIE['role_id'];             // role id

        // =========================
        // 1) Meeting Type from Role
        // =========================
        if ($r_id == 14) {
            $meeting_type = 'admin';
        } elseif ($r_id == 2) {
            $meeting_type = 'salemanager';
        } elseif ($r_id == 48) {
            $meeting_type = 'hod';
        } elseif ($r_id == 27) {
            $meeting_type = 'servicemanager';
        } else {
            $meeting_type = 'user';
        }

        // =========================
        // 2) CHECK A
        // meeting_by can only have 1 active meeting per day
        // =========================
        $checkA = "
            SELECT id 
            FROM webxl_hod_meeting
            WHERE meeting_by = $meeting_by
            AND status != '1'
            AND DATE(create_date) = CURDATE()
            LIMIT 1
        ";
        $runA = mysqli_query($con, $checkA);

        if (mysqli_num_rows($runA) > 0) {
            echo 'no_active';
            exit;
        }

        // =========================
        // 3) CHECK B
        // 1 user per day only 1 meeting
        // =========================
        $checkB = "
            SELECT id
            FROM webxl_hod_meeting
            WHERE user_id = $meeting_start_manager
            AND DATE(create_date) = CURDATE()
            LIMIT 1
        ";
        $runB = mysqli_query($con, $checkB);

        if (mysqli_num_rows($runB) > 0) {
            echo 'already_done';
            exit;
        }

        // =========================
        // 4) Insert Meeting
        // =========================
        $datetime = date('Y-m-d H:i:s');

        $insert = "
            INSERT INTO webxl_hod_meeting 
            (user_id, meeting_by, meeting_type, status, create_date, start_time)
            VALUES 
            ($meeting_start_manager, $meeting_by, '$meeting_type', '0', '$datetime', '$datetime')
        ";

        $run = mysqli_query($con, $insert);

        if ($run) {
            echo 'yes';
        } else {
            echo 'db_error';
        }
    }
}
