function CommisionProjectsMnager($dep, $startData, $endData)
{
    global $con;
    $num = 0;
    $query = "SELECT * FROM webxl_dep_project_comm ORDER BY id DESC";
    $runu = mysqli_query($con, $query);
    while ($rowu = mysqli_fetch_assoc($runu)) {

        $deps = json_decode($rowu['verification']);
        $items = json_decode($rowu['items']);
        $verifyGm = verifyGm($rowu['com_id']);
        $package = $verifyGm['package'];
        if ($verifyGm['renwal'] == 1) {
            $renwal = 'New';
        }
        if ($verifyGm['renwal'] == 0) {
            $renwal = 'Rc';
        }
        if ($verifyGm['renwal'] == 2) {
            $renwal = 'Ec';
        }
        $lenthDeps = count($deps);
        $lenthItems = count($items);


        for ($i = 0; $i <= $lenthDeps; $i++) {
            foreach ($deps[$i] as $key => $item) {
                if ($key == 'pro_id') {
                    $VerfyStatus = CommisionProjectsMnagerCompleted($rowu['id'], $item);
                    $comDetailidSpe = explode("/", $VerfyStatus);
                    $status = $comDetailidSpe[0];
                    $date = $comDetailidSpe[1];
                    $comPro = comPro($item);
                    $allPmsDepProjects = json_decode(allPmsDepProjects($dep), true);
                    foreach ($allPmsDepProjects as $quot_list) {
                        $listProject = array($quot_list['name']);
                        if (in_array($comPro['project'], $listProject, TRUE)) {
                            $mo = date("Y-m-d", strtotime($startData));
                            $mo2 = date("Y-m-d", strtotime($endData));
                            if ($date >= $mo && $date <= $mo2 && $status == 'Complete') {
                                $num++;
                            }
                        }
                    }
                }
            }
        }
    }
    return $num;
}
