        $quryu = "SELECT * FROM `webxl_setterget` WHERE terget_cat='1' AND user_id = '$user_gm' AND start_date = '0000-00-00' AND end_date = '0000-00-00'";
        $runu = mysqli_query($con, $quryu);
        while ($rowu = mysqli_fetch_assoc($runu)) {
            $start_date = $rowu['start_date'];
            $end_date = $rowu['end_date'];
            $terget_id = $rowu['terget_id'];
            $terget_cat = $rowu['terget_cat'];
            $terget_user_id = $rowu['user_id'];

            $getTarget = getTarget($terget_id);
            $tpackage = $getTarget['package'];
            $ttarget_number = $rowu['target_num'];
