                $howeverManyMonths = 1;
            }
            if ($howeverManyMonths == 1) {
                $ttarget_number = $rowu['target_num'] / 3;
            }
            $query = "SELECT * FROM webxl_verify_gm Where `user_id`= '$user_gm' And package = '$tpackage' ORDER BY `id` DESC";
