function AllSalaryBalanceReport($start, $end)
{
    global $con;
    $query = "SELECT webxl_tem_salary_ship.id,webxl_tem_salary_ship.user_id,webxl_tem_salary_ship.totalSalary,webxl_tem_salary_ship.create_date,SUM(webxl_tem_salary_ship.totalSalary) AS AlltotalSalary,webxl_user.branch,webxl_user.gender FROM webxl_tem_salary_ship
    LEFT JOIN webxl_user ON (webxl_tem_salary_ship.user_id=webxl_user.user_id)
    WHERE DATE(webxl_tem_salary_ship.create_date) BETWEEN '$start' AND '$end'";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);
    $AlltotalSalary = $rowu['AlltotalSalary'];
    return $AlltotalSalary;
}
function userloanreportfunction($start, $end)
{
    global $con;

    $query = "SELECT SUM(pay) AS totalPay 
              FROM webxl_pay_loan 
              WHERE DATE(pay_date) BETWEEN '$start' AND '$end'";

    $run = mysqli_query($con, $query);
    $row = mysqli_fetch_assoc($run);

    return $row['totalPay'] ?? 0;
}
function customer_received_loan_report_function($start, $end)
{
    global $con;

    $query = "
        SELECT 
            SUM(delay_pkr) AS TotalLoanAmount,
            SUM(current_pkr) AS TotalReceivedAmount
        FROM webxl_verify_gm_delay_amount
        WHERE delay_dollar_status = 'Delay'
          AND DATE(create_at) BETWEEN '$start' AND '$end'
    ";

    $run = mysqli_query($con, $query);
    $row = mysqli_fetch_assoc($run);

    return [
        'TotalLoanAmount' => $row['TotalLoanAmount'] ?? 0,
        'TotalReceivedAmount' => $row['TotalReceivedAmount'] ?? 0
    ];
}



