// Handle Bank Balance Update
if (isset($_POST['action']) && $_POST['action'] === 'updateBankBalance') {
    header('Content-Type: application/json');



    try {
        global $con; // Access global connection

        if (!$con) {
            throw new Exception("Database connection not available");
        }

        $id = isset($_POST['id']) ? intval($_POST['id']) : 0;
        $create_at = isset($_POST['create_at']) ? $_POST['create_at'] : '';
        $amount = isset($_POST['amount']) ? floatval($_POST['amount']) : 0;
        $detail = isset($_POST['detail']) ? $_POST['detail'] : '';

        if (empty($id) || empty($create_at) || $amount <= 0) {
            throw new Exception("ID, Date and Amount are required. ID: $id, Date: $create_at, Amount: $amount");
        }

        // Escape values
        $create_at = mysqli_real_escape_string($con, $create_at);
        $detail = mysqli_real_escape_string($con, $detail);

        $updateQuery = "UPDATE webxl_bank_balance 
                        SET create_at = '$create_at', 
                            amount = $amount, 
                            detail = '$detail' 
                        WHERE id = $id";

        $result = mysqli_query($con, $updateQuery);

        if ($result) {
            $affected = mysqli_affected_rows($con);
            echo json_encode([
                'success' => true,
                'message' => 'Bank balance updated successfully',
                'affected_rows' => $affected
            ]);
        } else {
            throw new Exception("Query failed: " . mysqli_error($con));
        }
    } catch (Exception $e) {
        echo json_encode([
            'success' => false,
            'message' => $e->getMessage()
        ]);
    }

    exit;
}
