                'Gold Hosting Plan' => true,
                'Diamond Hosting Plan' => true,
            ];

            $groups = [];
            $nonBundle = [];

            foreach ($records as $r) {
                $item = trim((string) $r->item);

                if (!isset($bundle[$item])) {
                    $nonBundle[] = $r;
                    continue;
                }

                $comId = (string) $r->com_id;

                // normalize amount (avoid "7,500" vs "7500")
                $amt = (string) $r->amount;
                $amt = str_replace([',', ' '], '', $amt);

                // ✅ merge only if company + amount same
                $key = $comId . '|' . $amt;

                if (!isset($groups[$key])) {
                    $groups[$key] = [
                        'rows' => [],
                        'seenServices' => [],
                    ];
                }

                $groups[$key]['rows'][] = $r;
                $groups[$key]['seenServices'][$item] = true;
            }

            $result = $nonBundle;

            foreach ($groups as $g) {

                $hasDomain = isset($g['seenServices']['Domain Registration']);
                $hasHosting = isset($g['seenServices']['Hosting Plan']);
                $hasSSL = isset($g['seenServices']['SSL Certificate']);

                // ✅ merge rule:
                // merge if (Domain + Hosting) exists
                // optionally include SSL if present
                if ($hasDomain && $hasHosting) {

                    // pick latest invoice row for link/date/user
                    usort($g['rows'], function ($a, $b) {
                        return strtotime($b->create_date) <=> strtotime($a->create_date);
                    });
                    $base = $g['rows'][0];

                    $services = ['Domain Registration', 'Hosting Plan'];
                    if ($hasSSL)
                        $services[] = 'SSL Certificate';

                    $base->item = implode(' + ', $services);

                    $result[] = $base;
                } else {
                    // not enough to merge -> keep as-is
                    foreach ($g['rows'] as $r) {
                        $result[] = $r;
                    }
                }
            }

            usort($result, function ($a, $b) {
                return strtotime($b->create_date) <=> strtotime($a->create_date);
            });

            return $result;
        }

