                }
                $Totalalibaba_conversion_per = round($Totaltconversion + $Totaltreward);
            }
            if ($userABtargetAchiveCountNumPay < $ttarget_number) {
                $Totalalibaba_conversion_per = $Totalalibaba_conversion_per + $Totaltconversion;
            }

            if ($Totaltconversion != 0) {
                $allFinalCommission = $allFinalCommission + $Totaltconversion;
                $nT++;
                $output .= '<tr>
                 		<td>' . $nT . '</td>
                 		<td>' . $name . '</td>
                 		<td>' . $Totaltconversion . '</td>
             		</tr>';
            }
        }





        $output .= '<tr>
                 <td><b>................</b></td>
                 <td><b>Total</b></td>
                 <td><b>' . $allFinalCommission . '</b></td>
                 </tr>';
    }
    $output .= '</tbody>
