function AllDepInviceItemsAmount($dep_id, $start, $end)
{
    global $con;

    $query = "
        WITH inv_dep AS (
            SELECT ii.invoice_id, MIN(qs.dep_id) AS dep_id
            FROM webxl_invoice_item ii
            JOIN webxl_quotation_services qs ON qs.name = ii.item
            GROUP BY ii.invoice_id
        ),
        base AS (
            SELECT p.*
            FROM webxl_payments p
            WHERE DATE(p.create_date) BETWEEN '$start' AND '$end'
        )
        SELECT
            base.invoice_id,
            base.com_id,
            base.amount,
            base.method,
            base.create_date,

            -- optional: show items (only for display)
            GROUP_CONCAT(DISTINCT ii.item SEPARATOR ' + ') AS item,
            MAX(ii.detail) AS detail,

            inv.user_id AS invoice_user_id,
            u.name AS invoice_user_name

        FROM base
        JOIN inv_dep idmap ON idmap.invoice_id = base.invoice_id
        LEFT JOIN webxl_invoice_item ii ON ii.invoice_id = base.invoice_id
        LEFT JOIN webxl_invoice inv ON inv.invoice_id = base.invoice_id
        LEFT JOIN webxl_user u ON u.user_id = inv.user_id

        WHERE idmap.dep_id = '$dep_id'
        GROUP BY
            base.id, base.invoice_id, base.com_id, base.amount, base.method, base.create_date,
            inv.user_id, u.name
        ORDER BY base.create_date DESC
    ";

    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    mysqli_free_result($runu);

    return json_encode($rowu);
}



function AllDepInviceItemsOnlyAmountAmount($dep_id, $start, $end)
{
    global $con;
    $query = "SELECT webxl_quotation_services.name,webxl_quotation_services.dep_id,webxl_create_project.project,webxl_create_project.com_id,
    webxl_create_project.pro_id,webxl_create_project.create_data,webxl_invoice.com_id,SUM(webxl_invoice_item.pkr) AS totalPkr,webxl_invoice.invoice_id,webxl_invoice_item.item FROM webxl_quotation_services 
    LEFT JOIN webxl_create_project ON webxl_quotation_services.name=webxl_create_project.project
    LEFT JOIN webxl_invoice ON webxl_create_project.com_id=webxl_invoice.com_id
    LEFT JOIN webxl_invoice_item ON webxl_invoice.invoice_id=webxl_invoice_item.invoice_id
    WHERE webxl_quotation_services.dep_id='$dep_id' AND DATE(webxl_create_project.create_data) BETWEEN '$start' AND '$end' GROUP BY webxl_invoice.com_id ORDER BY webxl_invoice.invoice_id DESC";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);
    return $rowu['totalPkr'];
}

function AllDepInviceItemsOnlyAmountAmountTeast($dep_id, $start, $end)
{
    global $con;

    $dep_id = (string) $dep_id;

    $query = "
        WITH inv_dep AS (
            SELECT
                ii.invoice_id,
                MIN(qs.dep_id) AS dep_id
            FROM webxl_invoice_item ii
            JOIN webxl_quotation_services qs
                ON qs.name = ii.item
            GROUP BY ii.invoice_id
        ),
        base AS (
            SELECT
                p.id,
                p.invoice_id,
                p.com_id,
                p.amount,
                p.create_date
            FROM webxl_payments p
            WHERE DATE(p.create_date) BETWEEN '$start' AND '$end'
        )
        SELECT
            COALESCE(SUM(d.amount),0) AS total
        FROM base d
        JOIN inv_dep idmap
            ON idmap.invoice_id = d.invoice_id
        WHERE idmap.dep_id = '$dep_id'
    ";

    $run = mysqli_query($con, $query);
    $row = mysqli_fetch_assoc($run);
    mysqli_free_result($run);

    return (float) ($row['total'] ?? 0);
}

