 	LEFT JOIN webxl_user ON webxl_verify_gm.user_id=webxl_user.user_id
 	WHERE `renwal`= '$type' AND webxl_verify_gm.package = '$package' AND DATE(webxl_verify_gm.create_date) >= '$start' AND DATE(webxl_verify_gm.create_date) <= '$end'";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);
    $total_rc = $rowu['total_rc'];
    return $total_rc;
}
function AdminPackageSaleOnUsed($type, $start, $end)
{
    global $con;
    $query = "SELECT COUNT(webxl_kwa.id) AS total_rc, SUM(webxl_kwa.kwa) AS totalPrice,webxl_user.underWork,webxl_user.branch FROM `webxl_kwa`
    LEFT JOIN webxl_user ON webxl_kwa.user_id=webxl_user.user_id
    WHERE  webxl_kwa.type='$type' AND webxl_kwa.create_at BETWEEN '$start' AND '$end'";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);
    $total_rc = $rowu['total_rc'];
    return $total_rc;
}


