function buyer_reference_name($id)
{  // get user name
    global $con;
    $quryu = "SELECT * FROM webxl_dollar_buyer WHERE id = '$id'";
    $runu = mysqli_query($con, $quryu);
    $rowu = mysqli_fetch_assoc($runu);
    $buyer_from = $rowu['buyer_from'];
    return $buyer_from;
}
function buyer_total_dollar($start, $end)
{  // get user name
    global $con;
    $quryu = "SELECT SUM(dollars) AS total_dollar FROM webxl_dollar_buyer_dollars WHERE buy_date >= '$start' AND buy_date <= '$end' AND show_ab='Show'";
    $runu = mysqli_query($con, $quryu);
    $rowu = mysqli_fetch_assoc($runu);
    $total_dollar = $rowu['total_dollar'];
    return $total_dollar;
}
function webxl_recover_dollars()
{  // get user name
    global $con;
    $quryu = "SELECT SUM(delay_dollars) AS total_dollar FROM webxl_verify_gm_delay_amount 
	LEFT JOIN webxl_verify_gm 
	ON webxl_verify_gm_delay_amount.gmid = webxl_verify_gm.id
	WHERE delay_dollar_status = 'Delay' 
  AND acc_status = 'Pending' 
  AND webxl_verify_gm.acc_disc_status = 'Approved' 
  AND webxl_verify_gm.ceo_disc_status = 'Approved'
";
    $runu = mysqli_query($con, $quryu);
    $rowu = mysqli_fetch_assoc($runu);
    $total_dollar = $rowu['total_dollar'];
    return $total_dollar;
}
function webxl_recover_dollars_pkr()
{  // get user name
    global $con;
    $quryu = "SELECT SUM(delay_pkr) AS total_pkr FROM webxl_verify_gm_delay_amount 
    LEFT JOIN webxl_verify_gm 
	ON webxl_verify_gm_delay_amount.gmid = webxl_verify_gm.id
	WHERE delay_dollar_status = 'Delay' 
  AND acc_status = 'Pending' 
  AND webxl_verify_gm.acc_disc_status = 'Approved' 
  AND webxl_verify_gm.ceo_disc_status = 'Approved'
    ";
    $runu = mysqli_query($con, $quryu);
    $rowu = mysqli_fetch_assoc($runu);
    $total_pkr = $rowu['total_pkr'];
    return $total_pkr;
}
function webxl_recover_dollars_pkr_by_date($startDate, $endDate)
{  // get user name
    global $con;
    $quryu = "SELECT SUM(webxl_verify_gm_delay_amount.delay_pkr) AS total_pkr FROM webxl_verify_gm_delay_amount 
    LEFT JOIN webxl_verify_gm 
	ON webxl_verify_gm_delay_amount.gmid = webxl_verify_gm.id
	WHERE webxl_verify_gm_delay_amount.delay_dollar_status = 'Delay' 
    AND (acc_status IS NULL OR acc_status = '' OR acc_status != 'Paid')
   AND (cash_status IS NULL OR cash_status = '' OR cash_status != 'Extra Discount Paid')
  AND webxl_verify_gm.acc_disc_status = 'Approved' 
  AND webxl_verify_gm.ceo_disc_status = 'Approved'
  AND DATE(webxl_verify_gm.create_date) >= '$startDate' AND DATE(webxl_verify_gm.create_date) <= '$endDate'";
    $runu = mysqli_query($con, $quryu);
    $rowu = mysqli_fetch_assoc($runu);
    $total_pkr = $rowu['total_pkr'];
    return $total_pkr;
}
function webxl_recover_dollars_pkr_by_date_recovered($type, $startDate, $endDate)
{  // get user name
    global $con;
    $quryu = "SELECT SUM(webxl_verify_gm_delay_amount.current_pkr) AS total_pkr FROM webxl_verify_gm_delay_amount 
    LEFT JOIN webxl_verify_gm 
	ON webxl_verify_gm_delay_amount.gmid = webxl_verify_gm.id
	WHERE webxl_verify_gm_delay_amount.delay_dollar_status = 'Delay' AND recovery_type = '$type'
    AND acc_status = 'Recoverd' AND cash_status != 'Extra Discount Paid'
  	AND webxl_verify_gm.acc_disc_status = 'Approved' 
  	AND webxl_verify_gm.ceo_disc_status = 'Approved'
  	AND DATE(webxl_verify_gm_delay_amount.current_pay_date) >= '$startDate' AND DATE(webxl_verify_gm_delay_amount.current_pay_date) <= '$endDate'";
