 FROM webxl_dollar_buyer_dollars LEFT JOIN webxl_dollar_buyer ON webxl_dollar_buyer_dollars.buyer_main=webxl_dollar_buyer.user_id
 LEFT JOIN webxl_user ON webxl_dollar_buyer_dollars.buyer_main=webxl_user.user_id
