        webxl_verify_gm.dollar_rate as customer_dollar_rate,
        webxl_verify_gm.ceo_disc_status,
        webxl_verify_gm.discount,
        webxl_verify_gm.extra_discount,
        webxl_verify_gm.droupout,
        webxl_verify_gm.extension,
        webxl_verify_gm.webxl_pay_status,
        webxl_verify_gm.acc_disc_status,

        webxl_company.id,
        webxl_company.com_id,
        webxl_company.cname,

        webxl_user.name,
        webxl_gmaccount.id as gmbvid,
        webxl_gmaccount.bvDate as gm_bvDate,
        webxl_gmaccount.user_bv_date as userbvdate

    FROM webxl_dollar_pay
    LEFT JOIN webxl_verify_gm
        ON (webxl_dollar_pay.com_id = webxl_verify_gm.com_id
            AND webxl_dollar_pay.gmid = webxl_verify_gm.id)
    LEFT JOIN webxl_company
        ON webxl_dollar_pay.com_id = webxl_company.id
    LEFT JOIN webxl_user
        ON webxl_dollar_pay.user_id = webxl_user.user_id
    LEFT JOIN webxl_gmaccount
        ON webxl_company.id = webxl_gmaccount.com_id
    $where
    ORDER BY webxl_verify_gm.id DESC
    LIMIT $offset, $limit";

    $result = $con->query($sql);

    $data = array();
    $data['records'] = array();

    while ($row = $result->fetch_assoc()) {
        $data['records'][] = $row;
    }

    $countSql = "SELECT COUNT(*) as total
    FROM webxl_dollar_pay
    LEFT JOIN webxl_verify_gm
        ON (webxl_dollar_pay.com_id = webxl_verify_gm.com_id
            AND webxl_dollar_pay.gmid = webxl_verify_gm.id)
    LEFT JOIN webxl_company
        ON webxl_dollar_pay.com_id = webxl_company.id
    $where";

    $totalRecords = $con->query($countSql)->fetch_assoc()['total'];
    $totalPages = ceil($totalRecords / $limit);

    $grandTotalSql = "SELECT 
    COALESCE(SUM(webxl_dollar_pay.dollars), 0) AS total_dollar,
    COALESCE(SUM(webxl_dollar_pay.pkr_amount), 0) AS total_pkr
FROM webxl_dollar_pay
LEFT JOIN webxl_verify_gm
    ON (webxl_dollar_pay.com_id = webxl_verify_gm.com_id
        AND webxl_dollar_pay.gmid = webxl_verify_gm.id)
LEFT JOIN webxl_company
    ON webxl_dollar_pay.com_id = webxl_company.id
$where";

    $grandTotalResult = $con->query($grandTotalSql);
    $grandTotals = $grandTotalResult->fetch_assoc();

    $data['totalPages'] = $totalPages;
    $data['totalRecords'] = $totalRecords;
    $data['grandTotals'] = [
        'total_dollar' => round((float) ($grandTotals['total_dollar'] ?? 0), 2),
        'total_pkr' => round((float) ($grandTotals['total_pkr'] ?? 0), 2)
    ];

    $con->close();

    header('Content-Type: application/json');
    echo json_encode($data);
}


