////////////////////////add promotion banner
if (isset($_POST['group-a'][0]['promotion_title'])) {
    $formData = $_POST['group-a'];
    $count_formData = count($formData);

    for ($i = 0; $i < $count_formData; $i++) {
        $promotion_title = $formData[$i]['promotion_title'];
        $package_type = $formData[$i]['package_type'];
        $discount = $formData[$i]['discount'];
        $startDate = $formData[$i]['startDate'];
        $endDate = $formData[$i]['endDate'];
        $detail = $formData[$i]['detail'];
        $baner = $_FILES['group-a']['name'][$i]['baner'];
        $tmp_name = $_FILES['group-a']['tmp_name'][$i]['baner'];
        $error = $_FILES['group-a']['error'][$i]['baner'];
        $ex = pathinfo($baner, PATHINFO_EXTENSION);
        $picName = $promotion_title . "_" . time() . "." . $ex;
        $dest_dir = realpath(__DIR__ . "/../assets/images/promotions");
        if (!$dest_dir) {
            echo json_encode(["status" => "error", "msg" => "Destination directory does not exist or is inaccessible."]);
            exit;
        }
        $dest = $dest_dir . "/" . $picName;

        if ($error === UPLOAD_ERR_OK) {
            if (!is_uploaded_file($tmp_name)) {
                echo json_encode(["status" => "error", "msg" => "File $tmp_name is not a valid uploaded file according to PHP."]);
                exit;
            }
            if (!is_writable($dest_dir)) {
                echo json_encode(["status" => "error", "msg" => "Destination directory $dest_dir is not writable."]);
                exit;
            }
            if (move_uploaded_file($tmp_name, $dest)) {
                $qury = "INSERT INTO `webxl_promotions`(`package`, `title`, `img`, `discount`, `start_date`, `end_date`, `detail`, `active`)
                 VALUES ('$package_type','$promotion_title','$picName','$discount','$startDate','$endDate','$detail','active')";
                $run = mysqli_query($con, $qury);
            } else {
                echo json_encode(["status" => "error", "msg" => "Failed to move uploaded file from $tmp_name to $dest"]);
                exit;
            }
        } else {
            echo json_encode(["status" => "error", "msg" => "Upload failed for $baner with error code: $error"]);
            exit;
        }
    }
    echo json_encode(["status" => "success", "msg" => "Promotion successfully added!"]);
    exit;
}
function promotionsDetail()
{
    global $con;
    $query = "SELECT * FROM webxl_promotions ORDER BY rank ASC";
    $runu = mysqli_query($con, $query);
    $row = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    mysqli_free_result($runu);
    return json_encode($row);
}
function promotionsBnnerActive()
{
    global $con;
    $query = "SELECT * FROM webxl_promotions WHERE `active`='active' ORDER BY id ASC";
