function webxl_behalf_gm_list($type)
{
    global $con;
    $query = "SELECT webxl_verify_gm.id,webxl_verify_gm.com_id,webxl_verify_gm.webxl_behalf,webxl_verify_gm_delay_amount.acc_status FROM webxl_verify_gm
    LEFT JOIN webxl_verify_gm_delay_amount ON ( webxl_verify_gm.id=webxl_verify_gm_delay_amount.gmid AND webxl_verify_gm.com_id=webxl_verify_gm_delay_amount.com_id )
    WHERE  webxl_verify_gm.webxl_behalf = '$type' AND  webxl_verify_gm_delay_amount.acc_status='Pending' ORDER BY webxl_verify_gm_delay_amount.id DESC";
    $runu = mysqli_query($con, $query);
    $row = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    mysqli_free_result($runu);
    return json_encode($row);
}
