function buyer_dollar_pay_date_cus_profit($startData, $endData)
{
    global $con;
    $total_dollar = 0;
    $query = "SELECT webxl_dollar_pay.com_id,webxl_dollar_pay.gmid,webxl_dollar_pay.cus_profit FROM webxl_dollar_pay
    LEFT JOIN webxl_verify_gm ON (webxl_dollar_pay.com_id=webxl_verify_gm.com_id AND webxl_dollar_pay.gmid=webxl_verify_gm.id)
    WHERE webxl_dollar_pay.pay_date >= '$startData' AND webxl_dollar_pay.pay_date <= '$endData' AND webxl_dollar_pay.pay_status='paid'";
    $runu = mysqli_query($con, $query);
    while ($rowu = mysqli_fetch_assoc($runu)) {
        if ($rowu['cus_profit'] > 0) {
            $total_dollar = $total_dollar + $rowu['cus_profit'];
        }
    }
    return $total_dollar;
}
function buyer_dollar_pay_date_cus_loss($startData, $endData)
{
    global $con;
    $total_dollar = 0;
    $query = "SELECT webxl_dollar_pay.com_id,webxl_dollar_pay.gmid,webxl_dollar_pay.cus_profit FROM webxl_dollar_pay
    LEFT JOIN webxl_verify_gm ON (webxl_dollar_pay.com_id=webxl_verify_gm.com_id AND webxl_dollar_pay.gmid=webxl_verify_gm.id)
    WHERE webxl_dollar_pay.pay_date >= '$startData' AND webxl_dollar_pay.pay_date <= '$endData' AND webxl_dollar_pay.pay_status='paid'";
    $runu = mysqli_query($con, $query);
    while ($rowu = mysqli_fetch_assoc($runu)) {
        if ($rowu['cus_profit'] < 0) {
            $total_dollar = $total_dollar + $rowu['cus_profit'];
        }
    }
    return $total_dollar;
}
