if (isset($_POST['export_dollar_gm5_partial'])) {
    $search = isset($_POST['search']) ? $_POST['search'] : '';
    $fromDate5 = isset($_POST['fromDate5']) ? $_POST['fromDate5'] : '';
    $toDate5 = isset($_POST['toDate5']) ? $_POST['toDate5'] : '';

    $dateFilter = "";
    if (!empty($fromDate5) && !empty($toDate5)) {
        $dateFilter .= " AND DATE(webxl_verify_gm.create_date) BETWEEN '$fromDate5' AND '$toDate5' ";
    } elseif (!empty($fromDate5)) {
        $dateFilter .= " AND DATE(webxl_verify_gm.create_date) >= '$fromDate5' ";
    } elseif (!empty($toDate5)) {
        $dateFilter .= " AND DATE(webxl_verify_gm.create_date) <= '$toDate5' ";
    }

    $sql = "SELECT 
        webxl_verify_gm.id as gmId,
        webxl_verify_gm.com_id as vfy_gm_com_id,
        webxl_verify_gm.package,
        webxl_verify_gm.price,
        webxl_verify_gm.amount,
        webxl_verify_gm.user_id as gmuId,
        webxl_verify_gm.status,
        webxl_verify_gm.coments,
        webxl_verify_gm.create_date,
        webxl_verify_gm.renwal,
        webxl_verify_gm.pay_date,
        webxl_verify_gm.acc_disc_status,
        webxl_verify_gm.ceo_disc_status,
        webxl_verify_gm.webxl_pay_status,
        webxl_verify_gm.discount,
        webxl_verify_gm.member_id,
        webxl_verify_gm.order_id,
        webxl_verify_gm.droupout,
        webxl_verify_gm.dollar_rate,
        webxl_verify_gm.extension,
        webxl_verify_gm.acc_pay_status,
        webxl_verify_gm.extra_discount,
        webxl_verify_gm.extra_pkr_discount,
        webxl_company.id,
        webxl_company.com_id,
        webxl_company.cname,
        webxl_user.name,
        webxl_gmaccount.bvDate as gm_bvDate

    FROM webxl_verify_gm
    LEFT JOIN webxl_company ON webxl_verify_gm.com_id = webxl_company.id
    LEFT JOIN webxl_user ON webxl_verify_gm.user_id = webxl_user.user_id
    LEFT JOIN webxl_gmaccount ON webxl_verify_gm.com_id = webxl_gmaccount.com_id

    WHERE 
        (webxl_company.cname LIKE '%$search%' OR webxl_company.com_id LIKE '%$search%')
        AND webxl_verify_gm.alibaba='Pending' 
        AND webxl_verify_gm.webxl_behalf='Installment' 
        AND webxl_verify_gm.ceo_disc_status != 'Rejected'
        AND (
            SELECT COUNT(*) FROM webxl_verify_gm_delay_amount WHERE webxl_verify_gm_delay_amount.com_id = webxl_verify_gm.com_id AND webxl_verify_gm_delay_amount.gmid = webxl_verify_gm.id AND webxl_verify_gm_delay_amount.delay_dollar_status = 'Installment' AND webxl_verify_gm_delay_amount.acc_status = 'Paid'
        ) != (
            SELECT COUNT(*) FROM webxl_verify_gm_delay_amount WHERE webxl_verify_gm_delay_amount.com_id = webxl_verify_gm.com_id AND webxl_verify_gm_delay_amount.gmid = webxl_verify_gm.id AND webxl_verify_gm_delay_amount.delay_dollar_status = 'Installment'
        )
        $dateFilter
    ORDER BY webxl_verify_gm.id DESC";

    $result = $con->query($sql);

    $data = array();
    while ($row = $result->fetch_assoc()) {
        $data['records'][] = $row;
    }

    header('Content-Type: application/json');
    echo json_encode($data);
    exit;
}
