function partial_count_all_cash_receive_but_not_full()
{
    global $con;

    $query = "
        SELECT 
    gmid, 
    SUM(current_dollar_pay) AS total_paid
FROM 
    webxl_verify_gm_delay_amount
LEFT JOIN 
    webxl_verify_gm 
ON 
    webxl_verify_gm_delay_amount.gmid = webxl_verify_gm.id 
WHERE 
    webxl_verify_gm_delay_amount.acc_status = 'Paid' 
    AND webxl_verify_gm_delay_amount.alibaba = 'Pending' 
    AND (webxl_verify_gm_delay_amount.cash_status = 'Online Paid' OR webxl_verify_gm_delay_amount.cash_status = 'Cash Received') 
    AND webxl_verify_gm_delay_amount.delay_dollar_status = 'Installment'
    AND webxl_verify_gm.acc_disc_status = 'Pending'
GROUP BY 
    webxl_verify_gm_delay_amount.gmid
HAVING 
    total_paid < (
        SELECT SUM(delay_dollars) 
        FROM webxl_verify_gm_delay_amount AS sub 
        WHERE sub.gmid = webxl_verify_gm_delay_amount.gmid
    );

    ";

    $result = mysqli_query($con, $query);

    if (!$result) {
        die("Query Failed: " . mysqli_error($con));
    }

    $total_sum = 0;

    while ($row = mysqli_fetch_assoc($result)) {
        $total_sum += $row['total_paid'];
    }

    return round($total_sum, 0);
}

