function buyer_dollar_ab_show_acc_not_pay($buyer_reference = 0)
{
    global $con;

    $buyer_reference = (int) $buyer_reference;
    $filterSql = "";

    if ($buyer_reference > 0) {
        $filterSql = " AND wdrh.buyer_reference = $buyer_reference ";
    }

    $query = "SELECT 
                wdrh.id,
                wdrh.buyer_main,
                wdrh.buyer_reference,
                wdrh.buyer_reference_paypal_email,
                wdrh.buy_date,
                wdrh.pkr_amount,
                wdrh.dollar_rate,
                wdrh.dollars,
                wdrh.show_ab,
                wdrh.acc_pay_status,
                wdrh.cheque_id,
                IFNULL(wdrh.acc_pay_pkr,0) AS acc_pay_pkr,
                (CAST(wdrh.pkr_amount AS UNSIGNED) - CAST(IFNULL(wdrh.acc_pay_pkr,0) AS UNSIGNED)) AS remaining_amount,
                wu.name AS buyer_main_name,
                wdb.buyer_from AS buyer_reference_name
            FROM webxl_dollars_received_history wdrh
            LEFT JOIN webxl_user wu ON wu.user_id = wdrh.buyer_main
            LEFT JOIN webxl_dollar_buyer wdb ON wdb.id = wdrh.buyer_reference
            WHERE wdrh.show_ab NOT IN ('Refund','delete')
              AND CAST(IFNULL(wdrh.acc_pay_pkr,0) AS UNSIGNED) < CAST(wdrh.pkr_amount AS UNSIGNED)
              AND (
                    wdrh.acc_pay_status = 'Installment'
                    OR wdrh.acc_pay_pkr IS NULL
                  )
              $filterSql
            ORDER BY wdrh.id DESC";

    $runu = mysqli_query($con, $query);

    if (!$runu) {
        die(mysqli_error($con));
    }

    $row = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    mysqli_free_result($runu);

    return $row;
}
function buyer_dollar_ab_show_acc_not_pay_count($buyer_reference = 0)
{
    global $con;

    $buyer_reference = (int) $buyer_reference;
    $filterSql = "";

    if ($buyer_reference > 0) {
        $filterSql = " AND wdrh.buyer_reference = $buyer_reference ";
    }

    $query = "SELECT COUNT(*) AS total
              FROM webxl_dollars_received_history wdrh
              WHERE wdrh.show_ab NOT IN ('Refund','delete')
                AND CAST(IFNULL(wdrh.acc_pay_pkr,0) AS UNSIGNED) < CAST(wdrh.pkr_amount AS UNSIGNED)
                AND (
                      wdrh.acc_pay_status = 'Installment'
                      OR wdrh.acc_pay_pkr IS NULL
                    )
                $filterSql";

    $run = mysqli_query($con, $query);

    if (!$run) {
        die(mysqli_error($con));
    }

    $row = mysqli_fetch_assoc($run);

    return (int) $row['total'];
}

