function get_buyer_reference_filter_list()
{
    global $con;

    $query = "SELECT DISTINCT 
                wdrh.buyer_reference,
                wdb.buyer_from AS buyer_reference_name
              FROM webxl_dollars_received_history wdrh
              LEFT JOIN webxl_dollar_buyer wdb ON wdb.id = wdrh.buyer_reference
              WHERE wdrh.show_ab NOT IN ('Refund','delete')
                AND wdrh.buyer_reference IS NOT NULL
                AND wdrh.buyer_reference != ''
              ORDER BY wdb.buyer_from ASC";

    $run = mysqli_query($con, $query);
    if (!$run) {
        die(mysqli_error($con));
    }

    $rows = mysqli_fetch_all($run, MYSQLI_ASSOC);
    mysqli_free_result($run);

    return $rows;
}
function get_installment_total_paid($history_id)
{
    global $con;
    $history_id = (int) $history_id;

    $q = "SELECT IFNULL(SUM(installment_amount_pkr),0) AS total_paid
          FROM webxl_dollars_received_history_installment
          WHERE history_id = '$history_id'";
    $r = mysqli_query($con, $q);
    $row = mysqli_fetch_assoc($r);
    return (float) $row['total_paid'];
}

function get_history_total_pkr($history_id)
{
    global $con;
    $history_id = (int) $history_id;

    $q = "SELECT pkr_amount FROM webxl_dollars_received_history WHERE id='$history_id' LIMIT 1";
    $r = mysqli_query($con, $q);
    $row = mysqli_fetch_assoc($r);
    return isset($row['pkr_amount']) ? (float) $row['pkr_amount'] : 0;
}

if (isset($_POST['dollar_buy_id_not_show_account_pay'])) {

    global $con;

    $history_id = (int) $_POST['dollar_buy_id_not_show_account_pay'];
    $paypal_email = mysqli_real_escape_string($con, $_POST['not_show_paypal_id']);
    $user = (int) $_POST['user'];
    $status = mysqli_real_escape_string($con, $_POST['ab_payment_status_show']);
    $amount = (float) $_POST['not_show_amount'];
    $pay_date = mysqli_real_escape_string($con, $_POST['startData_show']);
    $cheque_id = isset($_POST['cheque_id']) ? mysqli_real_escape_string($con, $_POST['cheque_id']) : '';
    $note = isset($_POST['installment_note']) ? mysqli_real_escape_string($con, trim($_POST['installment_note'])) : '';

    if ($history_id <= 0) {
        echo "invalid_history";
        exit;
    }

    if ($amount <= 0) {
        echo "invalid_amount";
        exit;
    }

    if (empty($pay_date)) {
        echo "invalid_date";
        exit;
    }

    $total_pkr = round((float) get_history_total_pkr($history_id), 0);
    $already_paid = round((float) get_installment_total_paid($history_id), 0);
    $amount = round((float) $_POST['not_show_amount'], 0);

    $remaining = $total_pkr - $already_paid;

    if ($amount > $remaining) {
        echo json_encode([
            "ok" => false,
            "error" => "exceed_remaining",
            "total_pkr" => $total_pkr,
            "already_paid" => $already_paid,
            "remaining" => $remaining,
            "amount" => $amount
        ]);
        exit;
    }

    $image_name = '';

    if (isset($_FILES['installment_image']) && !empty($_FILES['installment_image']['name'])) {

        $upload_dir = __DIR__ . "/uploads/payment_screenshots/";

        if (!is_dir($upload_dir)) {
            mkdir($upload_dir, 0777, true);
        }

        $tmp_name = $_FILES['installment_image']['tmp_name'];
        $original_name = $_FILES['installment_image']['name'];
        $file_size = $_FILES['installment_image']['size'];
        $file_error = $_FILES['installment_image']['error'];

        if ($file_error !== 0) {
            echo "image_upload_error_" . $file_error;
            exit;
        }

        if (!file_exists($tmp_name)) {
            echo "tmp_file_missing";
            exit;
        }

        if ($file_size > (5 * 1024 * 1024)) {
            echo "image_too_large";
            exit;
        }

        $extension = strtolower(pathinfo($original_name, PATHINFO_EXTENSION));
        $allowed_extensions = ['jpg', 'jpeg', 'png', 'webp'];

        if (!in_array($extension, $allowed_extensions)) {
            echo "invalid_image_type";
            exit;
        }

        $image_name = 'installment_' . $history_id . '_' . time() . '_' . mt_rand(1000, 9999) . '.' . $extension;
        $target_path = $upload_dir . $image_name;

        if (!move_uploaded_file($tmp_name, $target_path)) {
            echo "image_move_failed: " . $target_path;
            exit;
        }
    }

    mysqli_begin_transaction($con);

    try {
        $ins = "INSERT INTO webxl_dollars_received_history_installment
                (history_id, buyer_reference_paypal_email, installment_amount_pkr, installment_status, installment_date, note, image, created_by)
                VALUES
                ('$history_id', '$paypal_email', '$amount', '$status', '$pay_date', '$note', '$image_name', '$user')";

        if (!mysqli_query($con, $ins)) {
            throw new Exception("installment_insert_failed");
        }

        $new_paid = get_installment_total_paid($history_id);
        $new_remaining = $total_pkr - $new_paid;

        $final_status = $status;

        if ($new_remaining <= 0.00001) {
            $final_status = "Paid";
        } else {
            if ($status === "Paid") {
                $final_status = "Installment";
            }
        }

        $upd = "UPDATE webxl_dollars_received_history
                SET acc_pay_pkr = '$new_paid',
                    acc_pay_status = '$final_status',
                    acc_pay_date = '$pay_date',
                    acc_user_pay_by = '$user'
                WHERE id = '$history_id'
                  AND buyer_reference_paypal_email = '$paypal_email'";

        if (!mysqli_query($con, $upd)) {
            throw new Exception("main_update_failed");
        }

        mysqli_commit($con);

        echo json_encode([
            "ok" => true,
            "total_pkr" => $total_pkr,
            "paid" => $new_paid,
            "remaining" => $new_remaining,
            "final_status" => $final_status,
            "image" => $image_name,
            "note" => $note
        ]);
        exit;
    } catch (Exception $e) {
        mysqli_rollback($con);

        if (!empty($image_name)) {
            $uploaded_file = "../uploads/installments/" . $image_name;
            if (file_exists($uploaded_file)) {
                unlink($uploaded_file);
            }
        }

        echo $e->getMessage();
        exit;
    }
}
