function gm_approval_pending_from_hod_accounts()
{
    global $con;

    $query = "SELECT * FROM webxl_verify_gm 
              WHERE ceo_disc_status != 'Rejected'
              AND (acc_disc_status = 'Pending' OR ceo_disc_status = 'Pending')
              AND (webxl_behalf = '' OR webxl_behalf IS NULL)
              ORDER BY `id` DESC";

    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    mysqli_free_result($runu);
    return json_encode($rowu);
}


