// Delete expense and move to history
if (isset($_POST['delete_expense'])) {
    $expense_id = mysqli_real_escape_string($con, $_POST['expense_id']);
    $deleted_by = mysqli_real_escape_string($con, $_POST['deleted_by']);
    $deletion_reason = isset($_POST['deletion_reason']) ? mysqli_real_escape_string($con, $_POST['deletion_reason']) : NULL;

    mysqli_begin_transaction($con);

    try {
        $fetch_query = "SELECT * FROM `webxl_expense` WHERE id = '$expense_id'";
        $fetch_result = mysqli_query($con, $fetch_query);

        if (!$fetch_result || mysqli_num_rows($fetch_result) == 0) {
            throw new Exception("Expense not found");
        }

        $expense_data = mysqli_fetch_assoc($fetch_result);

        $insert_history = "INSERT INTO `webxl_expense_history` 
                          (`expense_id`, `phead_id`, `head_id`, `office`, `amount`, `detail`, 
                           `voucher_number`, `cheque_id`, `bill_image`, `create_date`, 
                           `created_by`, `original_created_at`, `deleted_by`, `deletion_reason`) 
                          VALUES 
                          ('{$expense_data['id']}', 
                           '{$expense_data['phead_id']}', 
                           " . (isset($expense_data['head_id']) ? "'{$expense_data['head_id']}'" : "NULL") . ", 
                           '{$expense_data['office']}', 
                           '{$expense_data['amount']}', 
                           '{$expense_data['detail']}', 
                           '{$expense_data['voucher_number']}', 
                           " . (!empty($expense_data['cheque_id']) ? "'{$expense_data['cheque_id']}'" : "NULL") . ", 
                           " . (isset($expense_data['bill_image']) ? "'{$expense_data['bill_image']}'" : "NULL") . ", 
                           '{$expense_data['create_date']}', 
                           " . (isset($expense_data['created_by']) ? "'{$expense_data['created_by']}'" : "NULL") . ", 
                           " . (isset($expense_data['created_at']) ? "'{$expense_data['created_at']}'" : "NOW()") . ", 
                           '$deleted_by', 
                           " . ($deletion_reason ? "'$deletion_reason'" : "NULL") . ")";

        if (!mysqli_query($con, $insert_history)) {
            throw new Exception("Failed to insert into history: " . mysqli_error($con));
        }

        $history_id = mysqli_insert_id($con);

        $fetch_images = "SELECT * FROM `webxl_expense_images` WHERE expense_id = '$expense_id'";
        $images_result = mysqli_query($con, $fetch_images);

        if ($images_result && mysqli_num_rows($images_result) > 0) {
            while ($image_row = mysqli_fetch_assoc($images_result)) {
                $insert_image_history = "INSERT INTO `webxl_expense_images_history` 
                                       (`history_id`, `expense_id`, `image_id`, `images`, `created_by`) 
                                       VALUES 
                                       ('$history_id', 
                                        '$expense_id', 
                                        '{$image_row['id']}', 
                                        '{$image_row['images']}', 
                                        " . (isset($image_row['created_by']) ? "'{$image_row['created_by']}'" : "NULL") . ")";

                if (!mysqli_query($con, $insert_image_history)) {
                    throw new Exception("Failed to copy images to history: " . mysqli_error($con));
                }
            }

            $delete_images = "DELETE FROM `webxl_expense_images` WHERE expense_id = '$expense_id'";
            if (!mysqli_query($con, $delete_images)) {
                throw new Exception("Failed to delete expense images: " . mysqli_error($con));
            }
        }

        $delete_expense = "DELETE FROM `webxl_expense` WHERE id = '$expense_id'";
        if (!mysqli_query($con, $delete_expense)) {
            throw new Exception("Failed to delete expense: " . mysqli_error($con));
        }

        mysqli_commit($con);

        echo json_encode([
            'success' => true,
            'message' => 'Expense deleted successfully and moved to history'
        ]);
    } catch (Exception $e) {
        mysqli_rollback($con);

        echo json_encode([
            'success' => false,
            'message' => $e->getMessage()
        ]);
    }

    exit;
}

