function getDollarPayByStatusStartEndExtra_Discount($startData, $endData)
{
    global $con;
    $query = "SELECT webxl_dollar_pay.com_id,webxl_dollar_pay.gmid,SUM(webxl_verify_gm.extra_discount) AS total_dollar,webxl_verify_gm.webxl_behalf FROM webxl_dollar_pay
    LEFT JOIN webxl_verify_gm ON (webxl_dollar_pay.com_id=webxl_verify_gm.com_id AND webxl_dollar_pay.gmid=webxl_verify_gm.id)
    WHERE webxl_dollar_pay.pay_date >= '$startData' AND webxl_dollar_pay.pay_date <= '$endData' ";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);
    $total_dollar = $rowu['total_dollar'];
    return round($total_dollar, 2);
}
function getDollarPayByStatusStartEndIn_Processing($startData, $endData, $status)
{
    global $con;
    $query = "SELECT webxl_dollar_pay.com_id,webxl_dollar_pay.gmid,SUM(webxl_dollar_pay.dollars) AS total_dollar,webxl_verify_gm.webxl_behalf FROM webxl_dollar_pay
    LEFT JOIN webxl_verify_gm ON (webxl_dollar_pay.com_id=webxl_verify_gm.com_id AND webxl_dollar_pay.gmid=webxl_verify_gm.id)
    WHERE webxl_dollar_pay.pay_date >= '$startData' AND webxl_dollar_pay.pay_date <= '$endData' AND webxl_dollar_pay.pay_status='$status'";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);
    $total_dollar = $rowu['total_dollar'];
    return round($total_dollar, 2);
}
function limitTextWithLineBreaks($text, $limit)
{
    // Check if the length of the text is greater than the limit
    if (strlen($text) > $limit) {
        // Find the last space within the limit
        $lastSpace = strrpos(substr($text, 0, $limit), ' ');

        // Extract text within the limit and append a line break
        $limitedText = substr($text, 0, $lastSpace) . "\n" . substr($text, $lastSpace + 1);

        return $limitedText;
    } else {
        // If the text length is within the limit, return the original text
        return $text;
    }
}
