function AllUserYearPerformanceEvaluationLeaves($uid, $startMonth, $endMonth, $StartYear, $EndYear)
{
    global $con;
    $LastMonthYear = $StartYear . '-' . $startMonth;
    $CurrentMonthYear = $EndYear . '-' . $endMonth;
    $finalLeaves = 0;
    // $query = "SELECT Sum(leaves) As totalLeaves,month,year,user_id FROM `webxl_attendance_month` WHERE user_id='$uid' AND CONCAT(`year`, '-', `month`) BETWEEN '$LastMonthYear' AND '$CurrentMonthYear' GROUP BY user_id";
    $query = "
    SELECT 
        LEAST(SUM(CASE 
        			 WHEN year = '2023' AND leaves >= 1 THEN 1 
                     WHEN year != '2023' AND leaves >= 2 THEN 2 
                     WHEN year != '2023' AND leaves = 1 THEN 1
                     ELSE leaves 
                 END), 2) AS totalLeaves,
        month,
        year,
        user_id 
    FROM 
        `webxl_attendance_month` 
    WHERE 
        user_id='$uid' 
        AND STR_TO_DATE(CONCAT(`year`, '-', `month`, '-01'), '%Y-%m-%d') BETWEEN '$LastMonthYear-01' AND '$CurrentMonthYear-01' 
    GROUP BY 
        user_id, month, year
";


    // Execute the query
    $result = mysqli_query($con, $query);
    if ($result) {
        while ($row = mysqli_fetch_assoc($result)) {
            // Process each row
            $totalLeaves = $row['totalLeaves'];
            $month = $row['month'];
            $year = $row['year'];
            $finalLeaves = $finalLeaves + $totalLeaves;
        }
    }

    return $finalLeaves;
}
