function AllUserYearPerformanceEvaluationHoursNew($uid, $startMonth, $endMonth, $StartYear, $EndYear)
{
    global $con;

    // Format the start and end dates properly
    $startDate = "$StartYear-$startMonth-01";
    $endDate = "$EndYear-$endMonth-01";

    // Use a date comparison instead of CONCAT
    $query = "SELECT SUM(lateHour) AS totallateHour 
              FROM `webxl_attendance_month` 
              WHERE `user_id` = '$uid' 
              AND STR_TO_DATE(CONCAT(`year`, '-', `month`, '-01'), '%Y-%m-%d') 
              BETWEEN '$startDate' AND '$endDate'";

    $runu = mysqli_query($con, $query);

    if ($runu) {
        $rowu = mysqli_fetch_assoc($runu);
        $totallateHour = $rowu['totallateHour'] ?? 0; // Return 0 if NULL
        return $totallateHour;
    } else {
        // Log or handle query error
        echo "Error: " . mysqli_error($con);
        return 0;
    }
}
