function allUserCustomerServicePoolGMlist()
{
    global $con;
    $query = "SELECT webxl_gmaccount.com_id,webxl_gmaccount.user_id AS assignid ,webxl_gmaccount.startData,webxl_gmaccount.endData,webxl_servicepool.id,webxl_servicepool.user_id,webxl_servicepool.create_date FROM webxl_gmaccount
    INNER JOIN webxl_servicepool ON webxl_gmaccount.com_id = webxl_servicepool.com_id
    ORDER BY webxl_gmaccount.endData DESC LIMIT 500";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    mysqli_free_result($runu);
    return json_encode($rowu);
}
function allGMAccountNotInServicePool()
{
    global $con;

    $query = "
        SELECT gm.*
        FROM webxl_gmaccount gm
        WHERE 
            gm.com_id IS NOT NULL
            AND (
                (gm.startData IS NOT NULL AND gm.startData != '' AND gm.startData != '0000-00-00')
                OR
                (gm.bvDate IS NOT NULL AND gm.bvDate != '' AND gm.bvDate != '0000-00-00')
            )
            AND NOT EXISTS (
                SELECT 1
                FROM webxl_servicepool sp
                WHERE sp.com_id = gm.com_id
            )
        ORDER BY gm.id DESC
    ";

    $run = mysqli_query($con, $query);

    $data = [];
    if ($run && mysqli_num_rows($run) > 0) {
        while ($row = mysqli_fetch_assoc($run)) {
            $data[] = $row;
        }
    }

    return json_encode($data);
}


function allServicePoolDublicates()
{
    global $con;
    $query = "SELECT *
	FROM `webxl_servicepool` AS a
	JOIN (
    SELECT com_id, COUNT(*) AS duplicate_count
    FROM `webxl_servicepool` 
    GROUP BY com_id
    HAVING duplicate_count > 1
	) AS b ON a.com_id = b.com_id
	WHERE a.parent_id='' OR a.parent_id IS NULL ORDER BY a.com_id;
	";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    mysqli_free_result($runu);
    return json_encode($rowu);
}
