function allUserCustomerServicePoolDropOutInOneYera()
{
    global $con;
    $query = "SELECT webxl_servicepool.id,webxl_servicepool.com_id,webxl_servicepool.user_id,webxl_servicepool.create_date,webxl_gmaccount.com_id,
    webxl_gmaccount.user_id AS assignid ,webxl_gmaccount.startData,webxl_gmaccount.endData FROM webxl_gmaccount
    LEFT JOIN webxl_servicepool ON webxl_gmaccount.com_id=webxl_servicepool.com_id
    WHERE DATE(webxl_gmaccount.endData) BETWEEN DATE_SUB(CURDATE(), INTERVAL 1 YEAR) AND CURDATE() GROUP BY webxl_servicepool.com_id ORDER BY webxl_gmaccount.endData, webxl_servicepool.id  DESC";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    mysqli_free_result($runu);
    return json_encode($rowu);
}
