$(document).ready(function() {
    let firstChecked = null;

    // Parent checkbox change event
    $(".parent-checkbox").change(function() {
        // Get all checked checkboxes
        var checkedCheckboxes = $(".parent-checkbox:checked");

        // Remove all backgrounds initially
        $(".parent-checkbox").parent().removeClass("bg-success bg-danger");

        // If there are checked checkboxes
        if (checkedCheckboxes.length > 0) {
            // If the firstChecked is null or unchecked, find the new first checked checkbox
            if (!firstChecked || !firstChecked.is(":checked")) {
                firstChecked = checkedCheckboxes.first();
            }

            // Add green background to the first checked checkboxs parent
            firstChecked.parent().addClass("bg-success");
			$("#mainId").val(firstChecked.val());
            // Add red background to all other checked checkboxes parents
            checkedCheckboxes.not(firstChecked).parent().addClass("bg-danger");
        } else {
            // Reset the firstChecked if no checkboxes are checked
            firstChecked = null;
        }
    });
});




