function allReceptionClientsInMeetingMonthlyDateWaise($tema, $start, $end)
{
    global $con;
    if ($tema == 'No') {
        $query = "SELECT webxl_visit_meeting.id,webxl_visit_meeting.com_id,webxl_visit_meeting.user_id,webxl_visit_meeting.status,
    webxl_visit_meeting.service,webxl_visit_meeting.start_time,webxl_visit_meeting.end_time,webxl_visit_meeting.note,webxl_company.id,
    webxl_company.cname FROM webxl_visit_meeting LEFT JOIN webxl_company ON webxl_visit_meeting.com_id=webxl_company.id
    WHERE webxl_visit_meeting.status=0 AND DATE(webxl_visit_meeting.start_time) >= '$start' AND DATE(webxl_visit_meeting.start_time) <= '$end'
    ORDER BY webxl_company.id DESC";
    } else {
        $query = "SELECT webxl_visit_meeting.id,webxl_visit_meeting.com_id,webxl_visit_meeting.user_id,webxl_visit_meeting.status,
    webxl_visit_meeting.service,webxl_visit_meeting.start_time,webxl_visit_meeting.end_time,webxl_visit_meeting.note,webxl_company.id,
    webxl_company.cname FROM webxl_visit_meeting LEFT JOIN webxl_company ON webxl_visit_meeting.com_id=webxl_company.id
    WHERE webxl_visit_meeting.status=0 AND webxl_visit_meeting.user_id='$tema' AND DATE(webxl_visit_meeting.start_time) >= '$start' AND DATE(webxl_visit_meeting.start_time) <= '$end'
    ORDER BY webxl_company.id DESC";
    }
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    return json_encode($rowu);
}
function receptionCreatedGm($uid, $start, $end)
{
    global $con;
    $quryu = "SELECT webxl_visit_meeting.id,webxl_visit_meeting.com_id,webxl_visit_meeting.user_id,webxl_visit_meeting.status,
   		webxl_verify_gm.com_id,COUNT(webxl_verify_gm.id) AS total_gm FROM webxl_visit_meeting LEFT JOIN webxl_verify_gm ON webxl_visit_meeting.com_id=webxl_verify_gm.com_id
    WHERE webxl_visit_meeting.status=0 AND webxl_visit_meeting.user_id='$uid' AND DATE(webxl_visit_meeting.start_time) >= '$start' AND DATE(webxl_visit_meeting.start_time) <= '$end'
    ORDER BY webxl_company.id DESC";
    $runu = mysqli_query($con, $quryu);
    $rowu = mysqli_fetch_assoc($runu);
    mysqli_free_result($runu);
    $total_gm = $rowu['total_gm'];
    return $total_gm;
}
function totalReceptionPerPersonMeeting($start, $end)
{  // advance salary Detail
    global $con;
    $quryu = "SELECT 
    user_id, 
    COUNT(id) AS total_meetings, 
    SUM(TIMESTAMPDIFF(SECOND, start_time, end_time)) AS total_time_seconds,
    SEC_TO_TIME(SUM(TIMESTAMPDIFF(SECOND, start_time, end_time))) AS total_time_hms,
    FLOOR(SUM(TIMESTAMPDIFF(SECOND, start_time, end_time)) / 3600) AS total_hours,
    FLOOR((SUM(TIMESTAMPDIFF(SECOND, start_time, end_time)) % 3600) / 60) AS total_minutes
FROM 
    webxl_visit_meeting 
WHERE 
    status = 0 
    AND DATE(start_time) >= '$start' 
    AND DATE(start_time) <= '$end' 
GROUP BY 
    user_id 
ORDER BY 
    total_meetings DESC";
    $runu = mysqli_query($con, $quryu);
    $rowu = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    return json_encode($rowu);
}
