function cash_in_hand_gm_pkr_all_over_All_cash_in_hand($acc_pay_status, $start, $end)
{
    global $con;
    $query = "SELECT SUM(amount) AS total_pkr  FROM webxl_verify_gm WHERE acc_pay_status ='$acc_pay_status' AND acc_disc_status='Approved' AND DATE(create_date) >= '$start' AND DATE(create_date) <= '$end' AND (webxl_behalf!='Installment' AND webxl_behalf!='Delay' OR `webxl_behalf` IS NULL)";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);
    $total_pkr = $rowu['total_pkr'];
    return $total_pkr;
}
function cash_in_hand_gm_pkr_all_over_All_cash_in_hand_dollar($acc_pay_status, $start, $end)
{
    global $con;
    $query = "SELECT SUM(customer_dollars) AS total_customer_dollars  FROM webxl_verify_gm WHERE acc_pay_status ='$acc_pay_status' AND acc_disc_status='Approved' AND DATE(create_date) >= '$start' AND DATE(create_date) <= '$end' AND (webxl_behalf!='Installment' AND webxl_behalf!='Delay' OR `webxl_behalf` IS NULL)";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);
    $total_customer_dollars = $rowu['total_customer_dollars'];
    return $total_customer_dollars;
}
function partial_cash_in_hand_gm_pkr_by_date_cash_in_han($acc_pay_status, $start, $end)
{
    global $con;
    if ($acc_pay_status == 'Customer Paid') {
        $query = "SELECT SUM(b.extra_pkr_discount) AS total_pkr FROM webxl_verify_gm_delay_amount a INNER JOIN webxl_verify_gm b ON a.gmid = b.id WHERE a.delay_dollar_status='Delay' AND a.acc_status = 'Paid' AND a.cash_status ='$acc_pay_status' AND a.current_pay_date >= '$start' AND a.current_pay_date <= '$end'";
    } else {
        $query = "SELECT SUM(current_pkr) AS total_pkr  FROM webxl_verify_gm_delay_amount WHERE 
    delay_dollar_status='Delay' AND acc_status = 'Paid' AND cash_status ='$acc_pay_status' AND current_pay_date >= '$start' AND current_pay_date <= '$end'";
    }
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);
    $total_pkr = $rowu['total_pkr'];
    return $total_pkr;
}
function partial_cash_in_hand_gm_pkr_by_date_cash_in_han_dollar($acc_pay_status, $start, $end)
{
    global $con;
    if ($acc_pay_status == 'Customer Paid') {
        $query = "SELECT SUM(b.extra_discount) AS total_current_dollar_pay FROM webxl_verify_gm_delay_amount a INNER JOIN webxl_verify_gm b ON a.gmid = b.id WHERE a.delay_dollar_status='Delay' AND a.acc_status = 'Paid' AND a.cash_status ='$acc_pay_status' AND a.current_pay_date >= '$start' AND a.current_pay_date <= '$end'";
    } else {
        $query = "SELECT SUM(current_dollar_pay) AS total_current_dollar_pay FROM webxl_verify_gm_delay_amount WHERE 
    delay_dollar_status='Delay' AND acc_status = 'Paid' AND cash_status ='$acc_pay_status' AND current_pay_date >= '$start' AND current_pay_date <= '$end'";
    }
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);
    $total_current_dollar_pay = $rowu['total_current_dollar_pay'];
    return $total_current_dollar_pay;
}
