function allToDolist($userid)
{
    global $con;
    $query = "SELECT * FROM webxl_todo_list WHERE user_id='$userid' ORDER BY 
    CASE priority
    WHEN 'High' THEN 1
    WHEN 'Medium' THEN 2
    WHEN 'Low' THEN 3
    ELSE 4
    END ASC, id ASC";
    $runu = mysqli_query($con, $query);
    $row = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    mysqli_free_result($runu);
    return json_encode($row);
}
function allToDolistBothAssignAndParticipent($userid)
{
    global $con;
    $query = "(SELECT * 
 FROM webxl_todo_list 
 WHERE user_id='$userid' 
 ORDER BY 
     CASE priority
         WHEN 'High' THEN 1
         WHEN 'Medium' THEN 2
         WHEN 'Low' THEN 3
         ELSE 4
     END ASC, 
     id ASC)
UNION
(SELECT * 
 FROM webxl_todo_list 
 WHERE FIND_IN_SET('$userid', partici) > 0
 ORDER BY 
     CASE priority
         WHEN 'High' THEN 1
         WHEN 'Medium' THEN 2
         WHEN 'Low' THEN 3
         ELSE 4
     END ASC, 
     id ASC)
ORDER BY 
    CASE priority
        WHEN 'High' THEN 1
        WHEN 'Medium' THEN 2
        WHEN 'Low' THEN 3
        ELSE 4
    END ASC, 
    id ASC;";
    $runu = mysqli_query($con, $query);
    $row = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    mysqli_free_result($runu);
    return json_encode($row);
}
