function getCurrentQuarterDates($current_date)
{
    $current_year = date('Y', strtotime($current_date));

    $quarters = [
        ['start' => "$current_year-01-01", 'end' => "$current_year-03-31"],
        ['start' => "$current_year-04-01", 'end' => "$current_year-06-30"],
        ['start' => "$current_year-07-01", 'end' => "$current_year-09-30"],
        ['start' => "$current_year-10-01", 'end' => "$current_year-12-31"]
    ];

    foreach ($quarters as $quarter) {
        if ($current_date >= $quarter['start'] && $current_date <= $quarter['end']) {
            return $quarter;
        }
    }

    return null;
}
function getLastQuarterDates($current_date)
{
    var_dump($current_date);
    $current_year = date('Y', strtotime($current_date));
    $current_quarter = getCurrentQuarterDates($current_date);

    if (!$current_quarter) {
        die("Unable to determine the current quarter.");
    }

    // Determine last quarter's year and quarter
    $last_quarter_end_date = date('Y-m-d', strtotime($current_quarter['start'] . ' -1 day'));
    $last_quarter_year = date('Y', strtotime($last_quarter_end_date));

    $quarters = [
        ['start' => "$last_quarter_year-01-01", 'end' => "$last_quarter_year-03-31"],
        ['start' => "$last_quarter_year-04-01", 'end' => "$last_quarter_year-06-30"],
        ['start' => "$last_quarter_year-07-01", 'end' => "$last_quarter_year-09-30"],
        ['start' => "$last_quarter_year-10-01", 'end' => "$last_quarter_year-12-31"]
    ];

    foreach ($quarters as $quarter) {
        if ($last_quarter_end_date >= $quarter['start'] && $last_quarter_end_date <= $quarter['end']) {
            return $quarter;
        }
    }

    return null;
}
