function addSpacesBetweenDigits($number)
{
    // Convert the number to a string
    $numberStr = (string) $number;

    // Split the string into an array of characters
    $digits = str_split($numberStr);

    // Join the array of characters with a space separator
    $spacedNumber = implode('  ', $digits);

    return $spacedNumber;
}
