function webxl_ab_target($type, $start, $end)
{
    global $con;
    $totalTarget = 0;
    $query = "SELECT * FROM `webxl_ab_target` WHERE target_type='$type' AND start_date <='$start' AND end_date >='$end' ORDER BY id DESC";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);
    $totalTarget = $totalTarget + $rowu['base_target_num'];
    return $totalTarget;
}
function webxl_ab_target_renewal_per($start, $end, $per)
{
    global $con;
    $TotalNum = 0;
    $query = "SELECT * FROM `webxl_user`  ORDER BY `user_id` DESC";
    $runu = mysqli_query($con, $query);
    while ($rowu = mysqli_fetch_assoc($runu)) {
        $compines = json_decode(userTotalECMngTeamPerformaceAbTargetRenew($rowu['user_id']));
        foreach ($compines as $copmany) {
            $TotalNum = $TotalNum + COUNT(json_decode(allUserCustomerServicePoolAccordingMontQ($start, $end, $copmany->user_id)));
        }
    }
    $TotalNumPer = round((($TotalNum * webxl_ab_target('Renewal', $start, $end)) / 100), 0);
    if ($per == 'per') {
        return '(' . $TotalNum . '-' . webxl_ab_target('Renewal', $start, $end) . '%)=' . $TotalNumPer;
    } else {
        return $TotalNumPer;
    }
}
function AdminSaleReportKwa($type, $start, $end, $get)
{
    global $con;
    $query = "SELECT COUNT(id) AS total_rc, SUM(kwa) AS totalPrice FROM `webxl_kwa` WHERE type='$type' AND DATE(create_at) >= '$start' AND DATE(create_at) <= '$end'";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);
    $total_rc = $rowu['total_rc'];
    $totalPrice = $rowu['totalPrice'];
    if ($get == 'num') {
        return $total_rc;
    } else if ($get == 'both') {
        return $total_rc . '(' . $totalPrice . ')$';
    } else {
        return $totalPrice;
    }
}
