function allChequesUsedCount($type, $cheque_status, $closing_status, $start, $end)
{
    global $con;
    $startMonth = date('Y-m', strtotime($start));
    $endMonth = date('Y-m', strtotime($end));
    if ($startMonth == $endMonth && $closing_status == 'no') {
        $query = "SELECT * FROM `webxl_cheque_system` WHERE cheque_type='$type' AND  cheque_status='$cheque_status' AND DATE(cheque_date) >='$start' AND DATE(cheque_date) <='$end' AND remain_amount != 0 ORDER BY id DESC";
    } else if ($startMonth != $endMonth && $closing_status == 'quarter') {
        $query = "SELECT * FROM `webxl_cheque_system` WHERE cheque_type='$type' AND  cheque_status='$cheque_status' AND closing_status = 'quarter' AND DATE(cheque_date) >='$start' AND DATE(cheque_date) <='$end' AND remain_amount != 0 ORDER BY id DESC";
    } else if ($startMonth != $endMonth && $closing_status == 'no') {
        $query = "SELECT * FROM `webxl_cheque_system` WHERE cheque_type='$type' AND  cheque_status='$cheque_status'  AND DATE(cheque_date) >='$start' AND DATE(cheque_date) <='$end' AND remain_amount != 0 ORDER BY id DESC";
    } else {
        $query = "SELECT * FROM `webxl_cheque_system` WHERE cheque_type='$type' AND  cheque_status='$cheque_status'  AND DATE(cheque_date) >='$start' AND DATE(cheque_date) <='$end' AND remain_amount != 0 ORDER BY id DESC";
    }
    $runu = mysqli_query($con, $query);
    $cot = mysqli_num_rows($runu);
    return $cot;
}
