    $sql = "SELECT webxl_dollar_pay_temp.buyer_detail,webxl_dollar_pay_temp.dollars FROM webxl_dollar_pay_temp WHERE webxl_dollar_pay_temp.id='$id'";
    $result = $con->query($sql);
    if ($result && $result->num_rows > 0) {
        $row = $result->fetch_assoc();
        $final = $row['dollars'] - $dollarUse;
        // Step 2: Decode the JSON string into a PHP array
        $buyer_details = json_decode($row['buyer_detail'], true); // true converts it to an associative array

        // Step 3: Remove the entry with the matching buyer_dollar_short_id
        foreach ($buyer_details as $key => $detail) {
            if ($detail['buyer_dollar_short_id'] == $shor_id) {
                unset($buyer_details[$key]); // Remove the full object
                break; // Exit loop after finding and removing the entry
            }
        }

        // Step 4: Re-index the array to maintain a clean structure
        $buyer_details = array_values($buyer_details);

        // Step 5: Encode the modified array back to JSON
        $updated_buyer_details = json_encode($buyer_details);

        // Step 6: Update the database with the new JSON string
        $update_sql = "UPDATE webxl_dollar_pay_temp SET buyer_detail = '$updated_buyer_details', dollars = '$final' WHERE id='$id'"; // Replace some_condition with your actual condition
        if ($con->query($update_sql) === TRUE) {
            $qury = "UPDATE `webxl_dollar_buyer_dollars` SET use_for_tem='$use_for_tem', show_ab='$used' WHERE id='$shor_id'";
