if (isset($_GET['page_dollar_gm_suggest_short'])) {
    sleep(1);
    $limit = 100; // Number of items per page

    // Get the current page from the request
    $page = isset($_GET['page_dollar_gm_suggest_short']) ? $_GET['page_dollar_gm_suggest_short'] : 1;
    // Search term from the request
    $search = isset($_GET['search']) ? $_GET['search'] : '';
    // Calculate the offset
    $offset = ($page - 1) * $limit;

    // Query to fetch data
    $sql = "SELECT webxl_verify_gm.id as gmId,webxl_verify_gm.com_id as vfy_gm_com_id,webxl_verify_gm.package,webxl_verify_gm.price,webxl_verify_gm.amount,webxl_verify_gm.user_id as gmuId,webxl_verify_gm.status,webxl_verify_gm.coments,
webxl_verify_gm.create_date,webxl_verify_gm.renwal,webxl_verify_gm.pay_date,webxl_verify_gm.acc_disc_status,webxl_verify_gm.ceo_disc_status,webxl_verify_gm.webxl_pay_status,webxl_verify_gm.acc_pay_status,webxl_verify_gm.expire_date,
webxl_verify_gm.discount,webxl_verify_gm.member_id,webxl_verify_gm.order_id,webxl_verify_gm.droupout,webxl_verify_gm.dollar_rate,webxl_verify_gm.extension,webxl_verify_gm.webxl_behalf,webxl_verify_gm.extra_discount,webxl_verify_gm.extra_pkr_discount,webxl_company.id,webxl_company.com_id,
webxl_company.cname,webxl_user.name FROM webxl_verify_gm LEFT JOIN webxl_company ON webxl_verify_gm.com_id=webxl_company.id
LEFT JOIN webxl_user ON webxl_verify_gm.user_id=webxl_user.user_id
  WHERE (webxl_company.cname LIKE '%$search%' OR webxl_company.com_id LIKE '%$search%') AND webxl_verify_gm.webxl_pay_status ='Pending' AND webxl_verify_gm.acc_disc_status='Approved' AND webxl_verify_gm.ceo_disc_status='Approved' AND (webxl_verify_gm.webxl_behalf != 'Installment' OR webxl_verify_gm.webxl_behalf IS NULL) ORDER BY webxl_verify_gm.id DESC LIMIT $offset, $limit";
    $result = $con->query($sql);

    // Fetch data
    $data = array();
    while ($row = $result->fetch_assoc()) {
        $data['records'][] = $row;
    }

    // Calculate total pages
    $totalRecords = $con->query("SELECT COUNT(*) as total FROM webxl_verify_gm WHERE webxl_pay_status ='Pending' AND acc_disc_status='Approved' AND ceo_disc_status='Approved' AND (webxl_behalf != 'Installment' OR webxl_behalf IS NULL)")->fetch_assoc()['total'];
    $totalPages = ceil($totalRecords / $limit);

    $data['totalPages'] = $totalPages;
    $data['totalRecords'] = $totalRecords;

    // Close the MySQLi connection
    $con->close();

    // Return JSON response
    header('Content-Type: application/json');
    echo json_encode($data);
}
