function userDailyTargetTeamCurrentLost($method, $user_id, $dateFillter, $from_date = null, $to_date = null)
{
    global $con;
    if ($dateFillter == 'Curent') {
        $query = "
    SELECT webxl_day_book.method, SUM(webxl_day_book.followup) AS TotalFollowUp, 
           webxl_day_book.user_id, webxl_day_book.date  
    FROM webxl_day_book 
    WHERE webxl_day_book.method = '$method' 
      AND webxl_day_book.user_id = '$user_id' 
      AND webxl_day_book.date >= DATE_FORMAT(CURDATE(), '%Y-%m-01') 
      AND webxl_day_book.date <= LAST_DAY(CURDATE())";
    } elseif ($dateFillter == 'Last') {
        $query = "
    SELECT webxl_day_book.method, SUM(webxl_day_book.followup) AS TotalFollowUp, 
           webxl_day_book.user_id, webxl_day_book.date  
    FROM webxl_day_book 
    WHERE webxl_day_book.method = '$method' 
      AND webxl_day_book.user_id = '$user_id' 
      AND webxl_day_book.date >= DATE_FORMAT(CURDATE() - INTERVAL 1 MONTH, '%Y-%m-01') 
      AND webxl_day_book.date <= LAST_DAY(CURDATE() - INTERVAL 1 MONTH)
	";
    } else {
        $query = "SELECT webxl_day_book.method,SUM(webxl_day_book.followup) As TotalFollowUp,webxl_day_book.user_id,webxl_day_book.date  FROM webxl_day_book WHERE webxl_day_book.method='$method' AND webxl_day_book.user_id = '$user_id' AND  DATE(webxl_day_book.date) > DATE_SUB(NOW(), INTERVAL $dateFillter)";
    }

    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_assoc($runu);
