function calculateTotalTimeSpent($lastUpdate, $alreadySpentTime)
{
    $currentDateTime = new DateTime(); // Current date and time
    $lastUpdateDateTime = new DateTime($lastUpdate); // Convert last update time to DateTime

    $timeSpentInterval = $lastUpdateDateTime->diff($currentDateTime); // Calculate the time difference

    // Parse $alreadySpentTime into a DateInterval
    $alreadySpentParts = sscanf($alreadySpentTime, "%dd %02d:%02d:%02d");
    $alreadySpentInterval = new DateInterval(sprintf("P%dDT%dH%dM%dS", $alreadySpentParts[0], $alreadySpentParts[1], $alreadySpentParts[2], $alreadySpentParts[3]));

    // Add already spent time to the new interval
    $baseDate = new DateTime(); // A base date to add intervals to
    $baseDate->add($timeSpentInterval); // Add new time interval
    $baseDate->add($alreadySpentInterval); // Add already spent time

    // Calculate total time difference from the base date
    $totalInterval = (new DateTime())->diff($baseDate);

    // Format the total time as "Xd HH:MM:SS"
    $totalTimeFormatted = sprintf(
        "%dd %02d:%02d:%02d",
        $totalInterval->d,
        $totalInterval->h,
        $totalInterval->i,
        $totalInterval->s
    );

    return $totalTimeFormatted;
}

