function TodaySocialPost($user_com_id)
{
    global $con;
    $platforms = ['Facebook', 'Instagram', 'Linkedin', 'Youtube', 'Tiktok'];

    // Query to fetch the platforms for the user
    $query = "SELECT plat_form 
              FROM webxl_social_post_followup 
              WHERE user_id = '$user_com_id' 
              AND DATE(create_at) = CURDATE()";
    $runu = mysqli_query($con, $query);

    $query0 = "SELECT * FROM webxl_social_account_post WHERE DATE(create_at)= CURDATE()";
    $runu0 = mysqli_query($con, $query0);
    $cot0 = mysqli_num_rows($runu0);
    // Fetch all platforms in data array
    $data = [];
    while ($row = mysqli_fetch_assoc($runu)) {
        $data[] = $row['plat_form'];
    }

    // Check for missing platforms
    $missingPlatforms = array_diff($platforms, $data);
    if (!empty($missingPlatforms && $cot0 > 0)) {
        return 1; // Platforms are missing
    } else {
        return 0; // All platforms are present
    }
}

