    echo $output;
}
function calculateDelay($startDate, $finishDate, $deadlineOffset)
{
    if ($startDate !== 'N/A') {
        $deadlineDate = date('d-m-Y', strtotime($startDate . $deadlineOffset));
    } else {
        $deadlineDate = 'N/A';
    }

    $currentDate = date('d-m-Y'); // Get the current date in the same format
    $finishTimestamp = $finishDate !== 'N/A' ? strtotime($finishDate) : strtotime($currentDate);

    if ($deadlineDate !== 'N/A') {
        $deadlineTimestamp = strtotime($deadlineDate);

        if ($finishDate === 'N/A') {
            // If finish date is not available, calculate delay based on the current date
            if ($finishTimestamp > $deadlineTimestamp) {
                $delayDays = ceil(($finishTimestamp - $deadlineTimestamp) / (60 * 60 * 24));
                $class = 'is__delay'; // Delay class
            } else {
                $delayDays = 0;
                $class = ''; // Success class
            }
        } elseif ($finishTimestamp <= $deadlineTimestamp) {
            $delayDays = 0;
            $class = 'is__success'; // Success class
        } else {
            $delayDays = ceil(($finishTimestamp - $deadlineTimestamp) / (60 * 60 * 24));
            $class = 'is__delay'; // Delay class
        }
    } else {
        // When deadline date is not available
        if ($finishDate === 'N/A') {
            $delayDays = 'N/A';
            $class = ''; // Blank color (no class assigned)
        } else {
            $delayDays = 'N/A';
            $class = 'is__working'; // Working class
        }
    }

    return [
        'deadline' => $deadlineDate,
        'delayDays' => $delayDays,
        'class' => $class,
    ];
}
