// Add this function to handle overtime report filtering
if (isset($_POST['action']) && $_POST['action'] === 'filter_overtime_report') {
    // Initialize variables
    $user_id = $_POST['user_id'] ?? '';
    $date_from = $_POST['date_from'] ?? '';
    $date_to = $_POST['date_to'] ?? '';
    $dep_title = $_POST['dep_title'] ?? '';

    $where = [];
    $params = [];
    $types = '';

    // Show current month by default if no filters applied
    if (empty($user_id) && empty($date_from) && empty($date_to) && empty($dep_title)) {
        $where[] = "MONTH(create_date) = MONTH(CURRENT_DATE())";
        $where[] = "YEAR(create_date) = YEAR(CURRENT_DATE())";
    }

    // Filter by user
    if (!empty($user_id)) {
        $where[] = "user_id = ?";
        $params[] = $user_id;
        $types .= 's';
    }

    // Filter by date range
    if (!empty($date_from)) {
        $where[] = "DATE(create_date) >= ?";
        $params[] = $date_from;
        $types .= 's';
    }
    if (!empty($date_to)) {
        $where[] = "DATE(create_date) <= ?";
        $params[] = $date_to;
        $types .= 's';
    }

    // Filter by department - ONLY use this OR the hardcoded one below, not both
    if (!empty($dep_title)) {
        $where[] = "dep_title LIKE ?";
        $params[] = "%$dep_title%";
        $types .= 's';
    } else {
        // Default to Software Department if no department filter is selected
        $where[] = "dep_title LIKE '%Software Department%'";
    }

    // ✅ Only users from specific team (role 64 underWork 54274)
    // This ensures we only show users from the Software team
    $where[] = "user_id IN (
        SELECT user_id 
        FROM webxl_user 
        WHERE underWork = '54274'
        AND FIND_IN_SET('64', roleId)
    )";

    // Build WHERE clause
    $where_sql = $where ? 'WHERE ' . implode(' AND ', $where) : '';

    // Debug: Uncomment to see the actual query
    // error_log("Overtime Query: " . $query);
    // error_log("Where SQL: " . $where_sql);
    // error_log("Params: " . print_r($params, true));

    // Prepare and execute query
    $query = "SELECT * FROM webxl_overtime $where_sql ORDER BY create_date DESC";

    $output = '';

    if ($stmt = mysqli_prepare($con, $query)) {
        // Bind parameters if any
        if (!empty($params)) {
            mysqli_stmt_bind_param($stmt, $types, ...$params);
        }

        mysqli_stmt_execute($stmt);
        $result = mysqli_stmt_get_result($stmt);

        if ($result && mysqli_num_rows($result) > 0) {
            $count = 0;
            while ($row = mysqli_fetch_assoc($result)) {
                $count++;
                $username = htmlspecialchars(username($row['user_id']));
                $department = htmlspecialchars(trim($row['dep_title']));

                $time = htmlspecialchars($row['time'] ?? '0');



                $output .= '<tr>
                    <td>' . date('d-m-Y', strtotime($row['create_date'])) . '</td>
                    <td>' . $username . '</td>
                    <td>' . htmlspecialchars($row['purpose'] ?? '') . '</td>
                    <td>' . $time . '</td>
                    
                    <td>' . $department . '</td>
                    <td>' . htmlspecialchars($row['detail'] ?? '') . '</td>
                </tr>';
            }
        } else {
            $output = '<tr><td colspan="7" class="text-center">No overtime records found for the selected filters</td></tr>';
        }

        mysqli_stmt_close($stmt);
    } else {
        $output = '<tr><td colspan="7" class="text-center text-danger">Database error: ' . mysqli_error($con) . '</td></tr>';
    }

    echo $output;
    exit;
}







