function TotalFolloeUpLeadsByUserDateFillter_lead_dep($uid, $start, $end)
{
    global $con;
    $query = "
        SELECT 
            webxl_company.id,
            webxl_company.assignId,
            COUNT(webxl_last_followup.id) AS followup_count FROM  webxl_company
         INNER JOIN webxl_leads  ON webxl_company.id = webxl_leads.com_id 
        INNER JOIN  webxl_last_followup ON webxl_company.id = webxl_last_followup.com_id 
        WHERE webxl_last_followup.uid = '$uid' AND DATE(webxl_last_followup.create_date) >= '$start' AND DATE(webxl_last_followup.create_date) <= '$end' 
        GROUP BY webxl_company.id, webxl_company.assignId";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    mysqli_free_result($runu);
    return json_encode($rowu);
}
