function total_dely_project_by_role($role_id)
{
    global $con;
    $userRoleDep = userRoleDep($role_id);
    $DepNameId = DepName($userRoleDep);
    $excludedProjects = [
        'Domain Registration',
        '1 Year',
        'country Base Domain',
        'On Request (Custom Price)',
        'Pk Domain (2 Years)',
        'Hosting Plan',
        'Aluminum Hosting Plan',
        'Copper Hosting Plan',
        'Silver Hosting Plan',
        'Gold Hosting Plan',
        'Diamond Hosting Plan',
        'Platinum Hosting Plan',
        'SSL Certificate',
        'Cloud Vps Professional',
        'Cloud Vps Business'
    ];

    $excludedProjectsList = "'" . implode("','", $excludedProjects) . "'";
    if ($role_id == 14 || $role_id == 57 || $role_id == 58 || $role_id == 46 || $role_id == 48 || $role_id == 55 || $role_id == 59) {
        $queryCount = "SELECT COUNT(DISTINCT webxl_create_project.pro_id) as total FROM webxl_create_project
      LEFT JOIN webxl_task_assign ON webxl_create_project.pro_id = webxl_task_assign.pro_id 
       WHERE webxl_create_project.pro_id != ''
        AND webxl_create_project.project NOT IN ($excludedProjectsList) AND  DATE(webxl_create_project.create_data) > DATE_SUB(NOW(), INTERVAL 3 MONTH) 
        AND webxl_create_project.pro_id NOT IN ( SELECT DISTINCT pro_id FROM webxl_task_assign WHERE fy_status = 1)";
    } else {
        $queryCount = "SELECT COUNT(DISTINCT webxl_create_project.pro_id) as total FROM webxl_create_project
         LEFT JOIN webxl_quotation_services ON webxl_create_project.project = webxl_quotation_services.name 
            LEFT JOIN webxl_task_assign ON webxl_create_project.pro_id = webxl_task_assign.pro_id 
               WHERE webxl_create_project.pro_id != ''
               		AND webxl_create_project.project NOT IN ($excludedProjectsList) AND webxl_quotation_services.dep_id = '$DepNameId' AND DATE(webxl_create_project.create_data) > DATE_SUB(NOW(), INTERVAL 3 MONTH)
                    AND webxl_create_project.pro_id NOT IN ( SELECT DISTINCT pro_id FROM webxl_task_assign WHERE fy_status = 1)";
    }
    $resultCount = mysqli_query($con, $queryCount);
    $rowCount = mysqli_fetch_assoc($resultCount);
    $totalRows = $rowCount['total'];
    return $totalRows;
}


