</div>
<script>
$(document).ready(function () {
    function calculateTotal() {
        let total = 0;
        let total_pkr = 0;
		let order_dollar_req = $("#order_dollar_req").val();
        // Sum all dollar input values
        $("input[name=\"install_req_dollar[]\"]").each(function () { 
            let value = parseFloat($(this).val()) || 0; 
            total += value;
        });

        // Sum all PKR input values
        $("input[name=\"install_req_pkr[]\"]").each(function () { 
            let value = parseFloat($(this).val()) || 0; 
            total_pkr += value;
        });

        // Update total display
        $("#total_sum_dollar").text(total.toFixed(0));
        $("#total_sum_pkr").text(total_pkr.toFixed(0));
        
     if (parseFloat(total.toFixed(0)) != parseFloat(order_dollar_req.toFixed(0))) {
    $("#error_show").html(`<small class="text-danger">Your Order Amount ${order_dollar_req} does not match your installments Total ${total.toFixed(0)}</small>`);
    $("#hidebutn").prop("disabled", true); // Disable button if amounts do not match
	} else {
    $("#error_show").html(""); // Clear error message
    $("#hidebutn").prop("disabled", false); // Enable button if amounts match
	}

    }

    // When dollar input changes, calculate PKR and update the related input
    $(document).on("input", "input[name=\"install_req_dollar[]\"]", function () {
        let dollar_rate = parseFloat($("#dollar_rate").val()) || 0;
        let payment_req = parseFloat($(this).val()) || 0;
        let pkr_req = (dollar_rate * payment_req).toFixed(0);

        // Find the corresponding PKR input in the same row
         $(this).closest(".col-md-3").next().find("input[name=\"install_req_pkr[]\"]").val(pkr_req);
        calculateTotal(); // Recalculate totals
    });

    // When PKR input changes, recalculate total PKR
    $(document).on("input", "input[name=\"install_req_pkr[]\"]", calculateTotal);

    // Initial calculation on page load
    calculateTotal();

});

</script>
';
        echo $output;
    }
}

