if (isset($_POST['acc_head_id_code'])) {
    $acc_head_id = $_POST['acc_head_id_code'];
    $acc_head_main_cet = $_POST['acc_head_main_cet_code'];
    $acc_head_main_cet_code_type = $_POST['acc_head_main_cet_code_type'];

    $values = explode("-", $acc_head_main_cet);
    $start = (int) $values[0]; // 1100
    $end = (int) $values[1];   // 1199

    $new_code_1 = $start;

    // Check if the head code already exists
    $query0 = "SELECT * FROM `webxl_expenses_head` WHERE code='$acc_head_main_cet' AND type='account_head' AND head_id='$acc_head_id'";
    $run0 = mysqli_query($con, $query0);
    $cot0 = mysqli_num_rows($run0);

    if ($cot0 > 0) {
        echo json_encode(['status' => 'error', 'message' => 'Head Code Already Exists']);
    } else {
        // Update account head code
        $query1 = "UPDATE `webxl_expenses_head` SET `code`='$acc_head_main_cet',`head_type`='$acc_head_main_cet_code_type' WHERE type='account_head' AND head_id='$acc_head_id'";
        $run1 = mysqli_query($con, $query1);

        if ($run1) {
            // Fetch and update sub-heads
            $query2 = "SELECT * FROM `webxl_expenses_head` WHERE type='account_head_main' AND pid_head='$acc_head_id'";
            $run2 = mysqli_query($con, $query2);

            while ($row = mysqli_fetch_assoc($run2)) {
                $head_id_1 = $row['head_id'];

                // Assign new code and increment by 10 for the next main head
                if ($new_code_1 <= $end) {
                    $updateQuery1 = "UPDATE `webxl_expenses_head` SET `code`='$new_code_1',`head_type`='$acc_head_main_cet_code_type' WHERE type='account_head_main' AND head_id='$head_id_1'";
                    mysqli_query($con, $updateQuery1);
                }

                $sub_code = $new_code_1 + 1; // Sub heads start after main head
                $new_code_1 += 10; // Next main account starts after 10

                $query3 = "SELECT * FROM `webxl_expenses_head` WHERE type='account_head_main_sub' AND pid_head='$head_id_1'";
                $run3 = mysqli_query($con, $query3);

                $count = 0; // Track number of sub-entries
                while ($row3 = mysqli_fetch_assoc($run3)) {
                    if ($count < 10 && $sub_code <= $end) {
                        $head_id_2 = $row3['head_id'];
                        $updateQuery2 = "UPDATE `webxl_expenses_head` SET `code`='$sub_code',`head_type`='$acc_head_main_cet_code_type' WHERE type='account_head_main_sub' AND head_id='$head_id_2'";
                        mysqli_query($con, $updateQuery2);
                        $sub_code++;
                        $count++;
                    }
                }
            }

            echo json_encode(['status' => 'success', 'message' => 'Head Code Added Successfully!']);
        } else {
            echo json_encode(['status' => 'error', 'message' => 'Failed to update Head Code']);
        }
    }
}


