function calculateMonths($startDate)
{
    $start = new DateTime($startDate);
    $now = new DateTime(); // Current date

    $interval = $start->diff($now);
    return ($interval->y * 12) + $interval->m; // Convert years to months and add remaining months
}

function all_pms_dash_date($start, $end, $dep_id)
{
    $start = $start ? $start : date('Y-m-d');
    $end = $end ? $end : date('Y-m-d');
    global $con;
    $query = "
        SELECT 
            webxl_project_status.id,
            webxl_project_status.com_id,
            webxl_project_status.pro_id,
            webxl_project_status.product,
            webxl_project_status.status,
            webxl_project_status.pro_update,
            webxl_project_status.upload_doc,
            webxl_project_status.link,
            webxl_quotation_services.name,
            webxl_quotation_services.dep_id
        FROM webxl_project_status
        LEFT JOIN webxl_quotation_services 
            ON webxl_project_status.product = webxl_quotation_services.name
        WHERE DATE(webxl_project_status.upload_doc) >= '$start' 
          AND DATE(webxl_project_status.upload_doc) <= '$end'
          AND webxl_quotation_services.dep_id = '$dep_id'
        ORDER BY webxl_project_status.id DESC";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    return json_encode($rowu);
}
