    $end = $end ? $end : date('Y-m-d');
    global $con;
    $query = "SELECT 
    webxl_create_project.pro_id,
    webxl_create_project.project,
    webxl_create_project.create_data,
    webxl_create_project.com_id,
    webxl_create_project.user_id AS pro_create_person,
    webxl_quotation_services.min_day,
    DATE_ADD(webxl_create_project.create_data, INTERVAL webxl_quotation_services.min_day DAY) AS new_end_date
FROM webxl_create_project
LEFT JOIN webxl_quotation_services 
    ON webxl_create_project.project = webxl_quotation_services.name
LEFT JOIN webxl_task_assign 
    ON webxl_create_project.pro_id = webxl_task_assign.pro_id 
WHERE 
    (webxl_task_assign.fy_status IS NULL OR webxl_task_assign.fy_status = 0) 
    AND webxl_create_project.pro_id != ''
    AND webxl_quotation_services.dep_id = '$dep_id' 
    AND DATE_ADD(webxl_create_project.create_data, INTERVAL webxl_quotation_services.min_day DAY) >= '$start' AND DATE_ADD(webxl_create_project.create_data, INTERVAL webxl_quotation_services.min_day DAY) <= '$end'
GROUP BY webxl_create_project.pro_id 
ORDER BY webxl_create_project.pro_id DESC";
    $runu = mysqli_query($con, $query);
    $rowu = mysqli_fetch_all($runu, MYSQLI_ASSOC);
    return json_encode($rowu);
}
function all_pms_dash_log_history_date($start, $end, $dep_id)
{
    global $con;

    // Set default date if not provided
    $start = $start ?: date('Y-m-d');
    $end = $end ?: date('Y-m-d');

    // Define user lists based on dep_id
    $users_list = [];
    if ($dep_id == 10) {
        $users_list = ['61', '112'];
    } elseif ($dep_id == 9) {
        $users_list = ['52333', '68'];
    }

    // If no users match the dep_id, return an empty JSON
    if (empty($users_list)) {
        return json_encode([]);
    }

    // Sanitize input to prevent SQL injection
    $start = mysqli_real_escape_string($con, $start);
    $end = mysqli_real_escape_string($con, $end);

    // Convert users list into a safe SQL string
    $user_ids = "'" . implode("','", array_map('mysqli_real_escape_string', array_fill(0, count($users_list), $con), $users_list)) . "'";

    // SQL query to get log history for selected users
    $query = "SELECT * FROM webxl_log_history  WHERE user_id IN ($user_ids) AND DATE(`log_date`) BETWEEN '$start' AND '$end' 
              GROUP BY user_id, DATE(log_date) ORDER BY id, user_id ASC";
    $result = mysqli_query($con, $query);

    // Fetch all results into an array
    $logs = [];
    while ($row = mysqli_fetch_assoc($result)) {
        $logs[] = $row;
    }

    return json_encode($logs);
}

