// Function to get and display all data from webxl_kwa_history
function getAndDisplayAllData($con)
{
    if (!$con) {
        echo json_encode(['error' => 'Database connection failed']);
        exit;
    }
    try {
        $sql = "SELECT kh.*, u.name as user_name, u.email, c.cname as company_name, c.contact, c.comType,
                k.type as kwa_type, k.remaning as kwa_remaining,k.create_at as created_at
                FROM webxl_kwa_history kh
                LEFT JOIN webxl_user u ON kh.user_id = u.user_id
                LEFT JOIN webxl_company c ON kh.com_id = c.id
                LEFT JOIN webxl_kwa k ON kh.kwa_id = k.id
                ORDER BY kh.pay_date DESC";
        $result = mysqli_query($con, $sql);
        if (!$result) {
            throw new Exception("Query failed: " . mysqli_error($con));
        }
        $data = [];
        while ($row = mysqli_fetch_assoc($result)) {
            $data[] = $row;
        }
        echo json_encode(['success' => true, 'data' => $data]);
    } catch (Exception $e) {
        echo json_encode(['error' => $e->getMessage()]);
    }
}
//Api to send customer data to external API
function send_customer_data_to_api($comid, $userid)
{
    global $con;
    $company_query = "SELECT * FROM webxl_company WHERE id = '$comid'";
    $company_result = mysqli_query($con, $company_query);
    if (!$company_result || mysqli_num_rows($company_result) == 0) {
        return false;
    }
    $company_data = mysqli_fetch_assoc($company_result);
    $user_query = "SELECT * FROM webxl_user WHERE user_id = '$userid'";
    $user_result = mysqli_query($con, $user_query);
    if (!$user_result || mysqli_num_rows($user_result) == 0) {
        return false;
    }
    $user_data = mysqli_fetch_assoc($user_result);
    $api_data = array(
        'drm_user_id' => $userid,
        'name' => $user_data['name'],
        'email' => $company_data['company_email'],
        'cname' => $company_data['company_name'],
        'com_id' => $comid
    );
    $api_url = 'https://xlserp.com/customersupport/api/insert-new-customer';
    $ch = curl_init($api_url);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_POST, true);
    curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($api_data));
    curl_setopt($ch, CURLOPT_HTTPHEADER, array(
        'Content-Type: application/json',
        'Accept: application/json'
    ));
    $response = curl_exec($ch);
    if (curl_errno($ch)) {
        return false;
    }
    unset($ch);
    return $response;
}
// Function to register customer support data
function customer_support_register_gm()
{
    global $con;
    $query = "SELECT csa.*, 
              c.cname, 
              u.name, u.email 
              FROM webxl_customer_support_api csa
              LEFT JOIN webxl_company c ON csa.com_id = c.id
              LEFT JOIN webxl_user u ON csa.user_id = u.user_id";

    $result = mysqli_query($con, $query);
    $data = array();
    if ($result) {
        while ($row = mysqli_fetch_assoc($result)) {

            if (isset($row['api_response']) && !empty($row['api_response'])) {
                $row['api_response_decoded'] = json_decode($row['api_response'], true);
            } else {
                $row['api_response_decoded'] = [];
            }
            $row['data_send_status'] = ($row['data_send'] == 1) ? 'Sent' : 'Not Sent';

            $data[] = $row;
        }
        return $data;
    } else {
        return array('error' => 'Failed to fetch data from database: ' . mysqli_error($con));
    }
}
// Function to handle balance leave submission
function handleBalanceLeaveSubmit($con, $data)
{
    $userId = $data['user_id'] ?? null;
    $eligibleLeaves = $data['available_leaves'] ?? 0;
    $leaveReason = $data['leave_reason'] ?? '';
    $errors = [];
    if (!$userId)
        $errors[] = 'Missing user_id';
    if ($eligibleLeaves <= 0)
        $errors[] = 'available_leaves must be greater than 0';
    if (empty(trim($leaveReason)))
        $errors[] = 'leave_reason is empty';

    if (!empty($errors)) {
        return [
            'status' => 'error',
            'message' => 'Invalid input: ' . implode(', ', $errors)
        ];
    }
    $userId = mysqli_real_escape_string($con, $userId);
    $leaveReason = mysqli_real_escape_string($con, $leaveReason);
    $checkQuery = "SELECT id FROM webxl_team_balance_leaves 
                   WHERE user_id = '$userId' 
                   AND manager_approval = 'pending' 
                   AND hod_approval = 'pending' 
                   AND account_approval = 'pending' 
                   LIMIT 1";
    $checkResult = mysqli_query($con, $checkQuery);
    if ($checkResult && mysqli_num_rows($checkResult) > 0) {
        return [
            'status' => 'error',
            'message' => 'You have already submitted a leave application which is pending approval. Please wait for the current one to be processed.'
        ];
    }
    $createdAt = date('Y-m-d H:i:s');
    $insert = "INSERT INTO webxl_team_balance_leaves (user_id, available_leaves, leave_reason, created_at)
               VALUES ('$userId', '$eligibleLeaves', '$leaveReason', '$createdAt')";
    if (mysqli_query($con, $insert)) {
        return ['status' => 'success', 'message' => 'Leave application submitted.'];
    } else {
        return ['status' => 'error', 'message' => 'DB Error: ' . mysqli_error($con)];
    }
}
// Function to update leave approval status
function updateLeaveApproval()
{
    global $con;
    header('Content-Type: application/json');
    try {
        if (empty($_POST['leave_id']) || empty($_POST['approval_status'])) {
            throw new Exception('Required fields are missing');
        }
        $leave_id = (int) $_POST['leave_id'];
        $approval_status = trim($_POST['approval_status']);
        $comments = trim($_POST['comments']) ?: '';
        $allowed_statuses = ['pending', 'approved', 'rejected'];
        if (!in_array($approval_status, $allowed_statuses)) {
            throw new Exception('Invalid approval status');
        }
        if (!$con) {
            throw new Exception('Database connection error');
        }
        mysqli_autocommit($con, false);
        $update_query = "
            UPDATE webxl_team_balance_leaves 
            SET manager_approval = ?, 
                reject_reason = ?,
                updated_at = NOW()
            WHERE id = ?
        ";

        $stmt = mysqli_prepare($con, $update_query);
        if (!$stmt) {
            throw new Exception('Failed to prepare statement: ' . mysqli_error($con));
        }
        mysqli_stmt_bind_param($stmt, 'ssi', $approval_status, $comments, $leave_id);

        if (!mysqli_stmt_execute($stmt)) {
            throw new Exception('Failed to execute statement: ' . mysqli_stmt_error($stmt));
        }
        $affected_rows = mysqli_stmt_affected_rows($stmt);

        if ($affected_rows === 0) {
            throw new Exception('No record found or no changes made');
        }
        mysqli_commit($con);
        echo json_encode([
            'success' => true,
            'message' => 'Leave approval updated successfully',
            'data' => [
                'leave_id' => $leave_id,
                'status' => $approval_status,
                'comments' => $comments
            ]
        ]);
    } catch (Exception $e) {

        if (isset($con)) {
            mysqli_rollback($con);
        }

        echo json_encode([
            'success' => false,
            'message' => $e->getMessage()
        ]);
    } finally {
        if (isset($stmt)) {
            mysqli_stmt_close($stmt);
        }
        if (isset($con)) {
            mysqli_autocommit($con, true);
        }
    }
}
