// Function to calculate days since joining
function calculateDaysSinceJoining($joinDate)
{
    try {
        if (empty($joinDate) || $joinDate == '0000-00-00') {
            return 0;
        }
        $today = new DateTime();
        $join = new DateTime($joinDate);
        $interval = $today->diff($join);
        return $interval->days;
    } catch (Exception $e) {
        return 0;
    }
}

// Function to calculate current annual cycle based on join date
function calculateCurrentAnnualCycle($joinDate)
{
    try {
        if (empty($joinDate) || $joinDate == '0000-00-00') {
            return 'No Join Date';
        }
        $joinDateTime = new DateTime($joinDate);
        $currentDateTime = new DateTime();
        $joinYear = (int) $joinDateTime->format('Y');
        $joinMonth = (int) $joinDateTime->format('m');
        $joinDay = (int) $joinDateTime->format('d');
        if ($joinYear < 1950 || $joinYear > date('Y')) {
            return 'Invalid Year';
        }
        $currentYear = (int) $currentDateTime->format('Y');
        $currentMonth = (int) $currentDateTime->format('m');
        $currentDay = (int) $currentDateTime->format('d');
        $cycleStartYear = $currentYear;
        if ($currentMonth < $joinMonth || ($currentMonth == $joinMonth && $currentDay < $joinDay)) {
            $cycleStartYear = $currentYear - 1;
        }
        $cycleEndYear = $cycleStartYear + 1;
        $cycleStartDate = sprintf('%04d-%02d-%02d', $cycleStartYear, $joinMonth, $joinDay);
        $cycleEndDate = sprintf('%04d-%02d-%02d', $cycleEndYear, $joinMonth, $joinDay);
        return $cycleStartDate . ' to ' . $cycleEndDate;
    } catch (Exception $e) {
        return 'Date Error';
    }
}

// Function to calculate consumed leaves from array of leave dates
function calculateConsumedLeavesFromArray($leaveDates, $joinDate)
{
    try {
        if (empty($leaveDates) || empty($joinDate) || $joinDate == '0000-00-00') {
            return 0;
        }
        $joinDateTime = new DateTime($joinDate);
        $currentDateTime = new DateTime();
        $joinYear = (int) $joinDateTime->format('Y');
        $joinMonth = (int) $joinDateTime->format('m');
        $joinDay = (int) $joinDateTime->format('d');
        $currentYear = (int) $currentDateTime->format('Y');
        $currentMonth = (int) $currentDateTime->format('m');
        $currentDay = (int) $currentDateTime->format('d');
        $cycleStartYear = $currentYear;
        if ($currentMonth < $joinMonth || ($currentMonth == $joinMonth && $currentDay < $joinDay)) {
            $cycleStartYear = $currentYear - 1;
        }
        $cycleEndYear = $cycleStartYear + 1;
        $cycleStartDate = sprintf('%04d-%02d-%02d', $cycleStartYear, $joinMonth, $joinDay);
        $cycleEndDate = sprintf('%04d-%02d-%02d', $cycleEndYear, $joinMonth, $joinDay);
        $leavesByMonth = array();
        foreach ($leaveDates as $leaveDate) {

            if ($leaveDate >= $cycleStartDate && $leaveDate < $cycleEndDate) {
                $monthKey = date('Y-m', strtotime($leaveDate));
                if (!isset($leavesByMonth[$monthKey])) {
                    $leavesByMonth[$monthKey] = 0;
                }
                $leavesByMonth[$monthKey]++;
            }
        }
        $totalValidLeaves = 0;
        foreach ($leavesByMonth as $month => $leavesInMonth) {
            if ($leavesInMonth <= 2) {
                $totalValidLeaves += $leavesInMonth;
            } else {
                $totalValidLeaves += 2;
            }
        }
        return $totalValidLeaves;
    } catch (Exception $e) {
        return 0;
    }
}

// Function to calculate consumed leaves for current annual cycle (kept for backward compatibility)
function calculateConsumedLeaves($userId, $joinDate)
{
    global $con;
    try {
        if (empty($joinDate) || $joinDate == '0000-00-00') {
            return 0;
        }
        $joinDateTime = new DateTime($joinDate);
        $currentDateTime = new DateTime();
        $joinYear = (int) $joinDateTime->format('Y');
        $joinMonth = (int) $joinDateTime->format('m');
        $joinDay = (int) $joinDateTime->format('d');
        $currentYear = (int) $currentDateTime->format('Y');
        $currentMonth = (int) $currentDateTime->format('m');
        $currentDay = (int) $currentDateTime->format('d');
        $cycleStartYear = $currentYear;
        if ($currentMonth < $joinMonth || ($currentMonth == $joinMonth && $currentDay < $joinDay)) {
            $cycleStartYear = $currentYear - 1;
        }
        $cycleEndYear = $cycleStartYear + 1;
        $cycleStartDate = sprintf('%04d-%02d-%02d', $cycleStartYear, $joinMonth, $joinDay);
        $cycleEndDate = sprintf('%04d-%02d-%02d', $cycleEndYear, $joinMonth, $joinDay);
        $attendanceQuery = "SELECT date FROM webxl_attendance 
                           WHERE user_id = '$userId' 
                           AND late_absent = 'True' 
                           AND date >= '$cycleStartDate' 
                           AND date < '$cycleEndDate'
                           ORDER BY date";
        $attendanceResult = mysqli_query($con, $attendanceQuery);

        if (!$attendanceResult) {
            return 0;
        }
        $leavesByMonth = array();
        $totalValidLeaves = 0;
        while ($row = mysqli_fetch_assoc($attendanceResult)) {
            $leaveDate = $row['date'];
            $monthKey = date('Y-m', strtotime($leaveDate));
            if (!isset($leavesByMonth[$monthKey])) {
                $leavesByMonth[$monthKey] = 0;
            }
            $leavesByMonth[$monthKey]++;
        }
        foreach ($leavesByMonth as $month => $leavesInMonth) {
            if ($leavesInMonth <= 2) {
                $totalValidLeaves += $leavesInMonth;
            } else {
                $totalValidLeaves += 2;
            }
        }

        return $totalValidLeaves;
    } catch (Exception $e) {
        return 0;
    }
}
// Helper function to clean company names 
function cleanCompanyName($name)
{
