}

// Function to check for similar company names (optional - for advanced duplicate detection)
function findSimilarCompanies($conn, $threshold = 80)
{
    $query = "SELECT id, cname FROM webxl_company WHERE cname IS NOT NULL";
    $result = mysqli_query($conn, $query);
    $companies = array();
    while ($row = mysqli_fetch_assoc($result)) {
        $companies[] = $row;
    }
    $similar = array();
    for ($i = 0; $i < count($companies); $i++) {
        for ($j = $i + 1; $j < count($companies); $j++) {
            $similarity = similar_text(
                strtolower($companies[$i]['cname']),
                strtolower($companies[$j]['cname']),
                $percent
            );

            if ($percent >= $threshold) {
                $similar[] = array(
                    'company1' => $companies[$i],
                    'company2' => $companies[$j],
                    'similarity' => $percent
                );
            }
        }
    }

    return $similar;
}

