                    'hod_user_id' => $invoice['hod_user_id'],
                    'hod_role_id' => $invoice['hod_role_id'],
                    'hod_dep_id' => $invoice['hod_dep_id'],
                    'hod' => $invoice['hod'],
                    'hod_comm' => $invoice['hod_comm'],
                    'update_date' => $invoice['update_date'],
                    'account' => $invoice['account'],
                    'updated_by' => $invoice['updated_by'],
                    'role_id' => $invoice['role_id'],
                    'dep_id' => $invoice['dep_id'],
                    'updated_at' => $invoice['updated_at']
                ];
            }
        }

        $companies[] = $companyData;
    }

    return [
        'companies' => $companies,
        'total_duplicates' => count($companies)
    ];
}
// Function to get marketing manager leads code date 21/07/2025
function marketingmanagerleades($country, $branch, $user_id)
{
    global $con;

    // Updated query to fetch ALL leads created by the user (removed date filter)
    $query = "SELECT 
                webxl_leads.id as lead_id,
                webxl_leads.com_id,
                webxl_leads.user_id,
                webxl_leads.create_date,
                webxl_company.id as company_id,
                webxl_company.cname,
                webxl_company.assignId,
                webxl_company.created_by,
                webxl_company.country as company_country,
                webxl_company.create_date as company_created_date,
                webxl_user.branch as user_branch
              FROM webxl_leads 
              INNER JOIN webxl_company ON webxl_leads.com_id = webxl_company.id
              LEFT JOIN webxl_user ON webxl_company.created_by = webxl_user.user_id
              WHERE webxl_company.created_by = ? 
              AND webxl_company.country = ? 
              AND webxl_user.branch = ?
              ORDER BY webxl_leads.create_date DESC";

    $stmt = mysqli_prepare($con, $query);
    mysqli_stmt_bind_param($stmt, 'sss', $user_id, $country, $branch);
    mysqli_stmt_execute($stmt);
    $result = mysqli_stmt_get_result($stmt);
    $rowu = mysqli_fetch_all($result, MYSQLI_ASSOC);
    mysqli_stmt_close($stmt);


    return json_encode($rowu);
}

function getmarketingmanagerleades($country, $branch, $user_id, $role_id)
{
    global $con;

    // Base query
    $query = "SELECT 
                webxl_leads.id as lead_id,
                webxl_leads.com_id,
                webxl_leads.user_id,
                webxl_leads.create_date,
                webxl_company.id as company_id,
                webxl_company.cname,
                webxl_company.assignId,
                webxl_company.created_by,
                webxl_company.country as company_country,
                webxl_company.city as company_city,
                webxl_company.create_date as company_created_date,
                webxl_user.branch as user_branch,
                webxl_user.roleId as user_role
              FROM webxl_leads 
              INNER JOIN webxl_company ON webxl_leads.com_id = webxl_company.id
              LEFT JOIN webxl_user ON webxl_company.created_by = webxl_user.user_id
              WHERE 1=1 ";

    $params = array();
    $param_types = "";

    // Role-based filtering
    if ($role_id == 55) {
        // If role is 55, filter by country and branch
        $query .= " AND webxl_company.country = ? AND webxl_user.branch = ? ";
        $params[] = $country;
        $params[] = $branch;
        $param_types .= "ss";
    } else {
        // For other roles, filter by user_id (created by specific user)
        $query .= " AND webxl_company.created_by = ? ";
        $params[] = $user_id;
        $param_types .= "s";

        // Also add country and branch filters if provided
        if (!empty($country)) {
            $query .= " AND webxl_company.country = ? ";
            $params[] = $country;
            $param_types .= "s";
        }

        if (!empty($branch)) {
            $query .= " AND webxl_user.branch = ? ";
            $params[] = $branch;
            $param_types .= "s";
        }
    }

    $query .= " ORDER BY webxl_leads.create_date DESC";

    $stmt = mysqli_prepare($con, $query);

    if (!empty($params)) {
        mysqli_stmt_bind_param($stmt, $param_types, ...$params);
    }

    mysqli_stmt_execute($stmt);
    $result = mysqli_stmt_get_result($stmt);
    $rowu = mysqli_fetch_all($result, MYSQLI_ASSOC);
    mysqli_stmt_close($stmt);

    return json_encode($rowu);
}

// Function to get all users for transfer (shows all users in dropdown)
function getAllUsersForTransfer($current_branch = null, $current_country = null, $current_city = null)
{
    global $con;

    // Get all active users except role 54
    $query = "SELECT user_id, name, branch, country, roleId 
              FROM webxl_user 
              WHERE roleId != 54 
              ORDER BY country ASC, branch ASC, name ASC";

    $stmt = mysqli_prepare($con, $query);
    mysqli_stmt_execute($stmt);
    $result = mysqli_stmt_get_result($stmt);
    $all_users = mysqli_fetch_all($result, MYSQLI_ASSOC);
    mysqli_stmt_close($stmt);

    return $all_users;
}

// Helper function to get current user's city
function getCurrentUserCity($user_id)
{
    global $con;

    $query = "SELECT city FROM webxl_user WHERE user_id = ? AND roleId != 54";
    $stmt = mysqli_prepare($con, $query);
    mysqli_stmt_bind_param($stmt, 's', $user_id);
    mysqli_stmt_execute($stmt);
    $result = mysqli_stmt_get_result($stmt);
    $user = mysqli_fetch_assoc($result);
