    return $user ? $user['city'] : null;
}

function transferLead($lead_id, $company_id, $new_user_id, $transferred_by, $current_user_role_id, $transfer_type = '', $transfer_notes = '')
{
    global $con;

    // Validate inputs
    if (empty($lead_id) || empty($company_id) || empty($new_user_id)) {
        return array('status' => 'error', 'message' => 'Missing required parameters');
    }

    // Map transfer type to database format
    $transfer_type_db = '';
    switch ($transfer_type) {
        case 'city':
            $transfer_type_db = 'city_to_city';
            break;
        case 'country':
            $transfer_type_db = 'country_to_country';
            break;
        case 'office':
            $transfer_type_db = 'in_between_office';
            break;
        default:
            $transfer_type_db = 'general';
            break;
    }

    // Check if current user has permission to transfer this lead
    $permission_check = "SELECT wc.created_by, wc.country as company_country
                        FROM webxl_company wc
                        WHERE wc.id = ?";

    $stmt = mysqli_prepare($con, $permission_check);
    if (!$stmt) {
        return array('status' => 'error', 'message' => 'Database preparation error: ' . mysqli_error($con));
    }

    mysqli_stmt_bind_param($stmt, 's', $company_id);
    mysqli_stmt_execute($stmt);
    $result = mysqli_stmt_get_result($stmt);
    $company_data = mysqli_fetch_assoc($result);
    mysqli_stmt_close($stmt);

    if (!$company_data) {
        return array('status' => 'error', 'message' => 'Company not found');
    }

    // Get current user's details using cookie user_id
    $user_query = "SELECT user_id, roleId, country, branch, name FROM webxl_user WHERE user_id = ? AND roleId != 54";
    $stmt = mysqli_prepare($con, $user_query);
    if (!$stmt) {
        return array('status' => 'error', 'message' => 'Database preparation error: ' . mysqli_error($con));
    }

    mysqli_stmt_bind_param($stmt, 's', $transferred_by);
    mysqli_stmt_execute($stmt);
    $result = mysqli_stmt_get_result($stmt);
    $current_user = mysqli_fetch_assoc($result);
    mysqli_stmt_close($stmt);

    if (!$current_user) {
        return array('status' => 'error', 'message' => 'Current user not found or inactive');
    }

    // Permission check based on role (using cookie role_id for verification)
    $can_transfer = false;
    if ($current_user_role_id == 55 || $current_user['roleId'] == 55) {
        // Role 55 (Marketing Manager) can transfer leads
        $can_transfer = true;
    } else {
        // Other roles can only transfer their own created leads
        if ($company_data['created_by'] == $transferred_by) {
            $can_transfer = true;
        }
    }

    if (!$can_transfer) {
        return array('status' => 'error', 'message' => 'You do not have permission to transfer this lead');
    }

    // Verify the target user exists and is active (roleId != 54)
    $target_user_check = "SELECT user_id, name, country, branch FROM webxl_user WHERE user_id = ? AND roleId != 54";
    $stmt = mysqli_prepare($con, $target_user_check);
    if (!$stmt) {
        return array('status' => 'error', 'message' => 'Database preparation error: ' . mysqli_error($con));
    }

    mysqli_stmt_bind_param($stmt, 's', $new_user_id);
    mysqli_stmt_execute($stmt);
    $result = mysqli_stmt_get_result($stmt);
    $target_user = mysqli_fetch_assoc($result);
    mysqli_stmt_close($stmt);

    if (!$target_user) {
        return array('status' => 'error', 'message' => 'Target user not found or inactive');
    }

    // Start transaction
    mysqli_begin_transaction($con);

    try {
        // 1. Update webxl_company table - change assignId
        $update_company = "UPDATE webxl_company 
                          SET assignId = ? 
                          WHERE id = ?";
        $stmt1 = mysqli_prepare($con, $update_company);
        if (!$stmt1) {
            throw new Exception("Failed to prepare company update query: " . mysqli_error($con));
        }

        mysqli_stmt_bind_param($stmt1, 'ss', $new_user_id, $company_id);
        $company_updated = mysqli_stmt_execute($stmt1);
        mysqli_stmt_close($stmt1);

        if (!$company_updated) {
            throw new Exception("Failed to update company assignment");
        }

        // 2. Update webxl_leads table - change user_id and add transfer_note
        $update_lead = "UPDATE webxl_leads 
                       SET user_id = ?, transfer_note = ? 
                       WHERE id = ?";
        $stmt2 = mysqli_prepare($con, $update_lead);
        if (!$stmt2) {
            throw new Exception("Failed to prepare lead update query: " . mysqli_error($con));
        }

        mysqli_stmt_bind_param($stmt2, 'sss', $new_user_id, $transfer_notes, $lead_id);
        $lead_updated = mysqli_stmt_execute($stmt2);
        mysqli_stmt_close($stmt2);

        if (!$lead_updated) {
            throw new Exception("Failed to update lead assignment");
        }

        // 3. Insert record in webxl_com_history table
        $history_insert = "INSERT INTO webxl_com_history 
                          (com_id, addBy, tilte, detail, create_date) 
                          VALUES (?, ?, 'Company Transfer', ?, NOW())";
        $stmt3 = mysqli_prepare($con, $history_insert);
        if (!$stmt3) {
            throw new Exception("Failed to prepare history insert query: " . mysqli_error($con));
        }

        mysqli_stmt_bind_param(
            $stmt3,
            'sss',
            $company_id,
            $current_user['name'],
            $transfer_notes
        );
        $history_inserted = mysqli_stmt_execute($stmt3);
        mysqli_stmt_close($stmt3);

        if (!$history_inserted) {
            throw new Exception("Failed to insert history record");
        }

        // Commit transaction
        mysqli_commit($con);

        return array(
            'status' => 'success',
            'message' => 'Lead successfully transferred to ' . $target_user['name'] . ' via ' . $transfer_type_db,
            'target_user' => $target_user['name'],
            'transfer_type' => $transfer_type_db
        );
    } catch (Exception $e) {
        // Rollback transaction
        mysqli_rollback($con);
        return array(
            'status' => 'error',
            'message' => 'Transfer failed: ' . $e->getMessage()
        );
    }
}
function calculateCorrectFreeTime($user_id, $tasks)
{
    // Get user's login time and office hours
    $loginTime = loginTime($user_id);
    $officeStartTime = "09:00"; // 9 AM
    $officeEndTime = "18:00";   // 6 PM
    $currentTime = date('H:i');

    // Convert times to minutes
    if (!function_exists('timeToMinutes')) {
        function timeToMinutes($time)
        {
            if (empty($time) || $time == 'N/A')
                return 0;
            $parts = explode(':', $time);
            return intval($parts[0]) * 60 + intval($parts[1]);
        }
    }

    if (!function_exists('minutesToTime')) {
        function minutesToTime($minutes)
        {
            $hours = floor($minutes / 60);
            $mins = $minutes % 60;
            return sprintf("%02d:%02d", $hours, $mins);
        }
    }

    // New function to parse different time formats
    if (!function_exists('parseTimeToMinutes')) {
        function parseTimeToMinutes($timeString)
        {
            if (empty($timeString) || $timeString == '00:00' || $timeString == 'N/A') {
                return 0;
            }

            $timeString = trim($timeString);
            $totalMinutes = 0;

            // Check if format is like "0d 2:17:45" or "1d 0:30:15"
            if (strpos($timeString, 'd') !== false) {
                // Format: "0d 2:17:45"
                preg_match('/(\d+)d\s*(\d+):(\d+):?(\d+)?/', $timeString, $matches);
                if ($matches) {
                    $days = (int) $matches[1];
                    $hours = (int) $matches[2];
                    $minutes = (int) $matches[3];
                    $seconds = isset($matches[4]) ? (int) $matches[4] : 0;

                    $totalMinutes = ($days * 24 * 60) + ($hours * 60) + $minutes + ($seconds > 0 ? 1 : 0); // Round up seconds to minutes
                }
            } else {
                // Standard format: "2:17:45" or "2:17"
                $parts = explode(':', $timeString);
                if (count($parts) >= 2) {
                    $hours = (int) $parts[0];
                    $minutes = (int) $parts[1];
                    $seconds = isset($parts[2]) ? (int) $parts[2] : 0;

                    $totalMinutes = ($hours * 60) + $minutes + ($seconds > 0 ? 1 : 0); // Round up seconds to minutes
                }
            }

            return $totalMinutes;
        }
    }

    $loginMinutes = timeToMinutes($loginTime);
    $officeStartMinutes = timeToMinutes($officeStartTime);
    $officeEndMinutes = timeToMinutes($officeEndTime);
    $currentMinutes = timeToMinutes($currentTime);

    // Calculate total office time from login to current time or end of office
    $actualLoginMinutes = max($loginMinutes, $officeStartMinutes);
    $endTimeMinutes = min($currentMinutes, $officeEndMinutes);
    $totalOfficeMinutes = $endTimeMinutes - $actualLoginMinutes;

    if ($totalOfficeMinutes <= 0) {
        return "00:00";
    }

    // Calculate actual working time from timespent field using new parser
    $totalActualWorkingMinutes = 0;
    foreach ($tasks as $task) {
        if (!empty($task->timespent)) {
            $workingMinutes = parseTimeToMinutes($task->timespent);
            $totalActualWorkingMinutes += $workingMinutes;
        }
    }

    // Calculate free time (office time - actual working time)
    $freeTimeMinutes = $totalOfficeMinutes - $totalActualWorkingMinutes;
    $freeTimeMinutes = max(0, $freeTimeMinutes); // Ensure non-negative

    return minutesToTime($freeTimeMinutes);
}
function parseTimeToMinutes($timeString)
{
    if (empty($timeString) || $timeString == '00:00' || $timeString == 'N/A') {
        return 0;
    }

    $timeString = trim($timeString);
    $totalMinutes = 0;

    // Case 1: Format like "0d 1:40:4" or "2d 0:30:15"
    if (preg_match('/(\d+)d\s*(\d+):(\d+)(?::(\d+))?/', $timeString, $matches)) {
        $days = (int) $matches[1];
        $hours = (int) $matches[2];
        $minutes = (int) $matches[3];
        $seconds = isset($matches[4]) ? (int) $matches[4] : 0;

        $totalMinutes = ($days * 24 * 60) + ($hours * 60) + $minutes + ($seconds > 0 ? 1 : 0);
    }
    // Case 2: Normal "H:M:S" or "H:M"
    elseif (preg_match('/^(\d+):(\d+)(?::(\d+))?$/', $timeString, $matches)) {
        $hours = (int) $matches[1];
        $minutes = (int) $matches[2];
        $seconds = isset($matches[3]) ? (int) $matches[3] : 0;

        $totalMinutes = ($hours * 60) + $minutes + ($seconds > 0 ? 1 : 0);
    }

    return $totalMinutes;
}

















