// sale and service performance report filter
if (
    $_SERVER['REQUEST_METHOD'] === 'POST'
    && isset($_POST['action']) && $_POST['action'] === 'filter_data'
) {

    $startDate = $_POST['startDate'];
    $endDate = $_POST['endDate'];
    $department = $_POST['department'];
    $office = $_POST['office'];
    $personName = trim($_POST['personName']);
    // print_r($startDate, $endDate, $department, $office, $personName);
    $roleMap = [
        'sale_dep' => [25, 26],
        'service_dep' => [27, 28, 29]
    ];

    $rolesToProcess = [];
    if (!empty($department) && isset($roleMap[$department])) {
        $rolesToProcess = $roleMap[$department];
    } else {
        $rolesToProcess = array_merge($roleMap['sale_dep'], $roleMap['service_dep']);
    }

    if (!empty($rolesToProcess)) {
        global $con;
        $groupedResults = [];
        $start = new DateTime($startDate);
        $end = new DateTime($endDate);
        $daysTotal = $start->diff($end)->days + 1;
        $today = new DateTime();
        $daysPassed = max(1, $start->diff(min($today, $end))->days + 1);
        foreach ($rolesToProcess as $role_id) {

            $query = "
                SELECT
                    u.name        AS username,
                    u.branch      AS useroffice,
                    u.user_id     AS user_id,
                    t.method,
                    t.role,
                    t.target,

                    /* follow-ups for the same user + method with date range filter */
                    COALESCE(
                        SUM(
                            CASE 
                                WHEN b.date >= '$startDate' AND b.date <= '$endDate' 
                                THEN b.followup 
                                ELSE 0 
                            END
                        ), 0
                    ) AS followup,

                    /* Last login pulled from webxl_login */
                    (
                        SELECT MAX(l.last_login)
                        FROM   webxl_login l
                        WHERE  l.user_id = u.user_id
                    ) AS last_login
                FROM  webxl_user       u
                JOIN  webxl_day_target t ON u.roleId  = t.role
                LEFT  JOIN webxl_day_book b
                    ON b.user_id = u.user_id
                   AND b.method  = t.method
                WHERE t.role = '$role_id'
            ";
            if (!empty($personName)) {
                $query .= " AND u.name LIKE '%$personName%'";
            }
            if (!empty($office)) {
                $query .= " AND u.office = '$office'";
            }
            $query .= " GROUP BY u.user_id, t.method, t.role, t.target";

            $run = mysqli_query($con, $query);
            if ($run && mysqli_num_rows($run) > 0) {
                while ($row = mysqli_fetch_assoc($run)) {
                    $achieved = $row['target'] > 0
                        ? round(($row['followup'] / $row['target']) * 100, 2)
                        : 0;
                    $remain = max(0, $row['target'] - $row['followup']);
                    $prediction = $daysPassed > 0
                        ? round(($row['followup'] / $daysPassed) * $daysTotal)
                        : 0;
                    $username = $row['username'];
                    if (!isset($groupedResults[$username])) {
                        $groupedResults[$username] = [
                            'username' => $username,
                            'useroffice' => $row['useroffice'],
                            'last_login' => $row['last_login'],
                            'methods' => []
                        ];
                    }
                    $groupedResults[$username]['methods'][] = [
                        'method' => $row['method'],
                        'target' => $row['target'],
                        'followup' => $row['followup'],
                        'achieved' => $achieved,
                        'remain' => $remain,
                        'prediction' => $prediction
                    ];
                }
            }
        }

        /* ---------- OUTPUT TABLE ---------- */
        if (!empty($groupedResults)) {
            echo "
            <table class='table table-sm table-bordered'>
              <thead>
                <tr>
                  <th>Sr&nbsp;No</th>
                  <th>Person</th>
                  <th title='Last login pulled from webxl_login'>DRM&nbsp;ATN</th>
                  <th>Office</th>
                  <th>Method</th>
                  <th>Target</th>
                  <th>Follow-up</th>
                  <th title='(followup ÷ target) × 100'>Achieved&nbsp;(%)</th>
                  <th title='target − followup'>Remain</th>
                  <th>A-</th>
                  <th title='(followup ÷ daysPassed) × daysTotal'>Prediction</th>
                </tr>
              </thead>
              <tbody>";

            $srNo = 1;
            foreach ($groupedResults as $userGroup) {
                $lastLogin = $userGroup['last_login'] ?: '-';
                $methodCount = count($userGroup['methods']);
                $firstMethod = $userGroup['methods'][0];
                echo "
                <tr>
                  <td rowspan='$methodCount'>$srNo</td>
                  <td rowspan='$methodCount'>{$userGroup['username']}</td>
                  <td rowspan='$methodCount'>$lastLogin</td>
                  <td rowspan='$methodCount'>{$userGroup['useroffice']}</td>
                  <td>{$firstMethod['method']}</td>
                  <td>{$firstMethod['target']}</td>
                  <td>{$firstMethod['followup']}</td>
                  <td>{$firstMethod['achieved']}%</td>
                  <td>{$firstMethod['remain']}</td>
                  <td>-</td>
                  <td>{$firstMethod['prediction']}</td>
                </tr>";
                for ($i = 1; $i < $methodCount; $i++) {
                    $method = $userGroup['methods'][$i];
                    echo "
                    <tr>
                      <td>{$method['method']}</td>
                      <td>{$method['target']}</td>
                      <td>{$method['followup']}</td>
                      <td>{$method['achieved']}%</td>
                      <td>{$method['remain']}</td>
                      <td>-</td>
                      <td>{$method['prediction']}</td>
                    </tr>";
                }

                $srNo++;
            }

            echo "
              </tbody>
            </table>";

            // Summary
            echo "<div class='mt-3'>";
            echo "<small class='text-muted'>";
            echo "Total Persons: " . count($groupedResults) . " | ";
            echo "Date Range: {$startDate} to {$endDate}";
            echo "</small>";
            echo "</div>";
        } else {
            echo "No target/follow-up data found for the selected filters and date range.";
        }
    } else {
        echo "No valid department data found!";
    }
}

// Function to get all users and their roles
if ($_POST['action'] == 'get_all_users') {
    $query = "
    SELECT 
        l.user_id,
        u.name AS name,
        l.username,
        l.password,
        l.change_pass,
        l.last_login,
        GROUP_CONCAT(r.name ORDER BY r.name SEPARATOR ', ') AS roles,
        uw.name AS underWork
    FROM webxl_login l
    JOIN webxl_user u 
        ON l.user_id = u.user_id
    LEFT JOIN webxl_user uw 
        ON u.underWork = uw.user_id
    LEFT JOIN webxl_role r 
        ON FIND_IN_SET(r.id, l.role_id)
    GROUP BY l.user_id;
";


    $result = mysqli_query($con, $query);

    $users = [];

    while ($row = mysqli_fetch_assoc($result)) {
        $users[] = [
            'id' => $row['user_id'],
            'name' => $row['name'],
            'username' => $row['username'],
            'password' => $row['password'],
            'change_pass' => $row['change_pass'],
            'last_login' => $row['last_login'],
            'underWork' => $row['underWork'],
            'role' => $row['roles']
        ];
    }

    header('Content-Type: application/json');
    echo json_encode($users);
    exit;
}
