// Function to fetch users data with attendance and leaves
if (isset($_POST['action']) && $_POST['action'] == 'fetch_users_data') {
    header('Content-Type: application/json');

    try {
        $query = "SELECT 
                    u.user_id, 
                    u.name, 
                    u.joinDate, 
                    u.increment,
                    a.date as attendance_date,
                    a.late_absent
                  FROM webxl_user u
                  LEFT JOIN webxl_attendance a ON u.user_id = a.user_id AND a.late_absent = 'True'
                  ORDER BY u.user_id ASC";

        $result = mysqli_query($con, $query);

        if (!$result) {
            throw new Exception("Database query failed: " . mysqli_error($con));
        }

        $usersData = array();
        $currentUserId = null;
        $leavesByMonth = array();

        while ($row = mysqli_fetch_assoc($result)) {
            $userId = $row['user_id'];
            if ($currentUserId !== null && $currentUserId !== $userId) {
                $consumedLeaves = calculateConsumedLeavesFromArray($leavesByMonth, $usersData[$currentUserId]['joinDate']);
                $usersData[$currentUserId]['consumedLeaves'] = $consumedLeaves;
                $leavesByMonth = array();
            }
            if (!isset($usersData[$userId])) {
                $joinDate = $row['joinDate'];
                $daysSinceJoining = calculateDaysSinceJoining($joinDate);
                $currentAnnualCycle = calculateCurrentAnnualCycle($joinDate);

                $usersData[$userId] = array(
                    'user_id' => $userId,
                    'name' => htmlspecialchars($row['name']),
                    'joinDate' => date('Y-m-d', strtotime($joinDate)),
                    'currentAnnualCycle' => $currentAnnualCycle,
                    'daysSinceJoining' => $daysSinceJoining,
                    'allowedLeaves' => 24,
                    'consumedLeaves' => 0
                );
            }
            if (!empty($row['attendance_date'])) {
                $leavesByMonth[] = $row['attendance_date'];
            }

            $currentUserId = $userId;
        }
        if ($currentUserId !== null) {
            $consumedLeaves = calculateConsumedLeavesFromArray($leavesByMonth, $usersData[$currentUserId]['joinDate']);
            $usersData[$currentUserId]['consumedLeaves'] = $consumedLeaves;
        }
        $users = array_values($usersData);
        echo json_encode(array(
            'success' => true,
            'data' => $users,
            'count' => count($users)
        ));
    } catch (Exception $e) {
        echo json_encode(array(
            'success' => false,
            'message' => $e->getMessage()
        ));
    }
    mysqli_close($con);
    exit();
}

