            }
            $statsQuery = "
                SELECT 
                    COUNT(DISTINCT cname) as total_duplicate_companies,
                    SUM(cnt - 1) as total_duplicate_records,
                    MAX(cnt) as max_duplicates,
                    AVG(cnt) as avg_duplicates
                FROM (
                    SELECT cname, COUNT(*) as cnt
                    FROM webxl_company 
                    WHERE cname IS NOT NULL AND cname != '' AND cname != 'NULL'
                    GROUP BY cname 
                    HAVING COUNT(*) > 1
                ) as duplicates
            ";
            error_log("DEBUG: Stats query: $statsQuery");
            $result = mysqli_query($con, $statsQuery);
            if (!$result) {
                error_log("DEBUG: Stats query failed: " . mysqli_error($con));
                throw new Exception("Stats query failed: " . mysqli_error($con));
            }
            $stats = mysqli_fetch_assoc($result);
