        while (ob_get_level()) {
            ob_end_clean();
        }
        header('Content-Type: application/json; charset=utf-8');
        function getUserNameById($con, $userId)
        {
            $userId = mysqli_real_escape_string($con, $userId);
            $query = "SELECT name FROM webxl_user WHERE user_id = '$userId'";
            $result = mysqli_query($con, $query);
            if ($result && mysqli_num_rows($result) > 0) {
                $row = mysqli_fetch_assoc($result);
                return $row['name'];
            } else {
                return "Unknown";
            }
        }
        try {
            $companyName = isset($_POST['company_name']) ? trim($_POST['company_name']) : '';
            error_log("DEBUG: Getting company details for: $companyName");
            if (empty($companyName)) {
                throw new Exception("Company name is required");
            }
            $escapedCompanyName = mysqli_real_escape_string($con, $companyName);
            $detailsQuery = "
            SELECT id, com_id, cname, country, city, contact, address,create_date,assignId,ntn,comType,status
            FROM webxl_company 
            WHERE TRIM(cname) = '$escapedCompanyName'
            ORDER BY id ASC
        ";
            error_log("DEBUG: Details query: $detailsQuery");
            $result = mysqli_query($con, $detailsQuery);
            if (!$result) {
                throw new Exception("Details query failed: " . mysqli_error($con));
            }
            $records = array();
            while ($row = mysqli_fetch_assoc($result)) {
                $row['assignName'] = !empty($row['assignId']) ? getUserNameById($con, $row['assignId']) : 'Unassigned';
                $records[] = $row;
            }
            error_log("DEBUG: Found " . count($records) . " records for company: $companyName");

