if (isset($_GET['action']) && $_GET['action'] === 'check_quotation_for_gm') {
    header('Content-Type: application/json');
    $com_id = intval($_GET['com_id']);
    $user_id = intval($_GET['user_id']);

    if ($com_id > 0 && $user_id > 0) {
        try {
            // Get valid GM packages
            $packages_json = bServicesPackages(0);
            $packages = json_decode($packages_json, true);
            $valid_packages = [];
            foreach ($packages as $pkg) {
                if (!empty($pkg['name'])) {
                    $valid_packages[] = strtolower(trim($pkg['name']));
                }
            }

            $query = "SELECT * FROM webxl_quotations WHERE com_id = '$com_id'  AND hod_status = 'Approved' AND is_used = 0 ORDER BY quo_id DESC";
            $result = mysqli_query($con, $query);

            $valid_quote = null;
            if ($result) {
                while ($row = mysqli_fetch_assoc($result)) {
                    $quo_title = strtolower(trim($row['quo_title']));
                    $packageTitle = trim(preg_replace('/\s+(package|service)\s*$/i', '', $quo_title));

                    if (in_array($packageTitle, $valid_packages) || in_array($quo_title, $valid_packages) || strpos($quo_title, 'service') !== false) {
                        $valid_quote = $row;
                        break;
                    }
                }
            }

            if ($valid_quote) {
                $quo_id = $valid_quote['quo_id'];

                // Fetch associated items from webxl_quotation_items
                $items_query = "SELECT * FROM webxl_quotation_items WHERE quo_id = '$quo_id'";
                $items_result = mysqli_query($con, $items_query);
                $items = [];
                if ($items_result) {
                    while ($item_row = mysqli_fetch_assoc($items_result)) {
                        $items[] = $item_row;
                    }
                }
                $valid_quote['items'] = $items;

                echo json_encode([
                    'success' => true,
                    'data' => $valid_quote,
                    'message' => 'Quotation found'
                ]);
            } else {
                echo json_encode([
                    'success' => false,
                    'data' => [],
                    'message' => 'No valid GM quotation found'
                ]);
            }
        } catch (Exception $e) {
            echo json_encode([
                'success' => false,
                'data' => [],
                'message' => 'Error: ' . $e->getMessage()
            ]);
        }
    } else {
        echo json_encode([
            'success' => false,
            'data' => [],
            'message' => 'Invalid ID'
        ]);
    }
    exit;
}
