//dialy gm record
if (isset($_POST['action']) && $_POST['action'] == 'get_gm_records') {
    header('Content-Type: application/json');

    try {
        // Get and validate input
        $start_date = isset($_POST['start_date']) ? trim($_POST['start_date']) : '';
        $end_date = isset($_POST['end_date']) ? trim($_POST['end_date']) : '';

        // Validate dates
        if (empty($start_date) || empty($end_date)) {
            echo json_encode([
                'success' => false,
                'message' => 'Start date and end date are required.'
            ]);
            exit();
        }

        // Validate date format
        if (!DateTime::createFromFormat('Y-m-d', $start_date) || !DateTime::createFromFormat('Y-m-d', $end_date)) {
            echo json_encode([
                'success' => false,
                'message' => 'Invalid date format. Please use YYYY-MM-DD format.'
            ]);
            exit();
        }

        // Check if start date is not greater than end date
        if ($start_date > $end_date) {
            echo json_encode([
                'success' => false,
                'message' => 'Start date cannot be greater than end date.'
            ]);
            exit();
        }

        // Prepare SQL query with JOINs to get user name and company name
        $query = "SELECT 
                    gm.*,
                    COALESCE(u.name, 'Unknown User') as user_name,
                    COALESCE(c.cname, 'Unknown Company') as company_name
                  FROM `webxl_gmaccount` gm
                  LEFT JOIN `webxl_user` u ON gm.user_id = u.user_id
                  LEFT JOIN `webxl_company` c ON gm.com_id = c.id
                  WHERE DATE(gm.create_data) BETWEEN ? AND ? 
                  ORDER BY gm.create_data DESC";

        // Use prepared statement to prevent SQL injection
        $stmt = mysqli_prepare($con, $query);

        if (!$stmt) {
            throw new Exception('Database query preparation failed: ' . mysqli_error($con));
        }

        mysqli_stmt_bind_param($stmt, 'ss', $start_date, $end_date);
        mysqli_stmt_execute($stmt);

        $result = mysqli_stmt_get_result($stmt);

        if (!$result) {
            throw new Exception('Database query execution failed: ' . mysqli_error($con));
        }

        $records = [];
        while ($row = mysqli_fetch_assoc($result)) {
            // Format dates for display
            $row['create_data'] = !empty($row['create_data']) ? date('Y-m-d H:i:s', strtotime($row['create_data'])) : '';
            $row['user_by_date'] = !empty($row['user_by_date']) ? date('Y-m-d', strtotime($row['user_by_date'])) : '';

            // Handle BV Date with status badge
            if (empty($row['bvDate']) || $row['bvDate'] == '0000-00-00' || $row['bvDate'] == '1990-01-01') {
                $row['bvDate_formatted'] = '<span class="badge badge-danger">Missing</span>';
                $row['bvDate_status'] = 'missing';
            } else {
                $row['bvDate_formatted'] = date('Y-m-d', strtotime($row['bvDate']));
                $row['bvDate_status'] = 'valid';
            }

            $row['startData'] = !empty($row['startData']) ? date('Y-m-d', strtotime($row['startData'])) : '';
            $row['endData'] = !empty($row['endData']) ? date('Y-m-d', strtotime($row['endData'])) : '';
            $row['LastStartDate'] = !empty($row['LastStartDate']) ? date('Y-m-d', strtotime($row['LastStartDate'])) : '';
            $row['LastExpireDate'] = !empty($row['LastExpireDate']) ? date('Y-m-d', strtotime($row['LastExpireDate'])) : '';

            // Handle Renewal Status
            if ($row['renwal'] == '0') {
                $row['renwal_formatted'] = '<span class="badge badge-primary">New</span>';
                $row['renwal_status'] = 'new';
            } else if ($row['renwal'] == '1') {
                $row['renwal_formatted'] = '<span class="badge badge-success">Renew GM</span>';
                $row['renwal_status'] = 'renew';
            } else {
                $row['renwal_formatted'] = '<span class="badge badge-secondary">Unknown</span>';
                $row['renwal_status'] = 'unknown';
            }

            // Handle Date BTN Status
            if (!empty($row['date_btn'])) {
                if ($row['date_btn'] == '1') {
                    $row['date_btn_formatted'] = '<span class="badge badge-success">Active</span>';
                } else if ($row['date_btn'] == '0') {
                    $row['date_btn_formatted'] = '<span class="badge badge-secondary">Inactive</span>';
                } else {
                    $row['date_btn_formatted'] = '<span class="badge badge-info">' . htmlspecialchars($row['date_btn']) . '</span>';
                }
            } else {
                $row['date_btn_formatted'] = '<span class="badge badge-light">-</span>';
            }

            // Handle Disable Status
            if ($row['disable'] == '1') {
                $row['disable_formatted'] = '<span class="badge badge-danger">Disabled</span>';
            } else if ($row['disable'] == '0') {
                $row['disable_formatted'] = '<span class="badge badge-success">Enabled</span>';
            } else {
                $row['disable_formatted'] = '<span class="badge badge-secondary">Unknown</span>';
            }

            $records[] = $row;
        }

        mysqli_stmt_close($stmt);

        echo json_encode([
            'success' => true,
            'data' => $records,
            'count' => count($records),
            'message' => count($records) > 0 ? 'Records found successfully.' : 'No records found for the selected date range.'
        ]);
    } catch (Exception $e) {
        error_log('GM Records Error: ' . $e->getMessage());
        echo json_encode([
            'success' => false,
            'message' => 'An error occurred while fetching records. Please try again later.'
        ]);
    }

    exit();
}

