    $params = array();
    $param_types = "";
    
    $base_query = " FROM webxl_leads 
              INNER JOIN webxl_company ON webxl_leads.com_id = webxl_company.id
              LEFT JOIN webxl_user ON webxl_company.created_by = webxl_user.user_id
              WHERE 1=1 ";
              
    // We enforce branch/city filtering for all users as per the original frontend logic
    if (!empty($branch)) {
        $base_query .= " AND webxl_company.city = ? ";
        $params[] = $branch;
        $param_types .= "s";
    }
    
    // Search filter
    if (!empty($searchValue)) {
        $base_query .= " AND (webxl_company.cname LIKE ? OR webxl_company.country LIKE ? OR webxl_company.city LIKE ?) ";
        $searchParam = "%$searchValue%";
        $params[] = $searchParam;
        $params[] = $searchParam;
        $params[] = $searchParam;
        $param_types .= "sss";
    }

    // Role-based filtering
    if ($role_id == 55) {
        $base_query .= " AND webxl_company.country = ? ";
        $params[] = $country;
        $param_types .= "s";
    } else {
        $base_query .= " AND webxl_company.created_by = ? ";
        $params[] = $user_id;
        $param_types .= "s";

        if (!empty($country)) {
            $base_query .= " AND webxl_company.country = ? ";
            $params[] = $country;
            $param_types .= "s";
        }
    }
    
    // Count total without search
    $count_query_all = "SELECT COUNT(*) as total FROM webxl_leads 
              INNER JOIN webxl_company ON webxl_leads.com_id = webxl_company.id
              LEFT JOIN webxl_user ON webxl_company.created_by = webxl_user.user_id
              WHERE 1=1 ";
    $all_params = array();
    $all_param_types = "";
    if (!empty($branch)) {
        $count_query_all .= " AND webxl_company.city = ? ";
        $all_params[] = $branch;
        $all_param_types .= "s";
    }
    
    if ($role_id == 55) {
        $count_query_all .= " AND webxl_company.country = ? ";
        $all_params[] = $country;
        $all_param_types .= "s";
    } else {
        $count_query_all .= " AND webxl_company.created_by = ? ";
        $all_params[] = $user_id;
        $all_param_types .= "s";

        if (!empty($country)) {
            $count_query_all .= " AND webxl_company.country = ? ";
            $all_params[] = $country;
            $all_param_types .= "s";
        }
    }

    $stmt_all = mysqli_prepare($con, $count_query_all);
    if (!empty($all_params)) {
        mysqli_stmt_bind_param($stmt_all, $all_param_types, ...$all_params);
    }
    mysqli_stmt_execute($stmt_all);
    $result_all = mysqli_stmt_get_result($stmt_all);
    $totalRecords = mysqli_fetch_assoc($result_all)['total'] ?? 0;
    mysqli_stmt_close($stmt_all);

    // Count filtered
    $count_query_filtered = "SELECT COUNT(*) as total " . $base_query;
    $stmt_filtered = mysqli_prepare($con, $count_query_filtered);
    if (!empty($params)) {
        mysqli_stmt_bind_param($stmt_filtered, $param_types, ...$params);
    }
    mysqli_stmt_execute($stmt_filtered);
    $result_filtered = mysqli_stmt_get_result($stmt_filtered);
    $totalFiltered = mysqli_fetch_assoc($result_filtered)['total'] ?? 0;
    mysqli_stmt_close($stmt_filtered);

    // Fetch records
    $query = "SELECT 
                webxl_leads.id as lead_id,
                webxl_leads.com_id,
                webxl_leads.user_id,
                webxl_leads.create_date,
                webxl_company.id as company_id,
                webxl_company.cname,
                webxl_company.assignId,
                webxl_company.created_by,
                webxl_company.country as company_country,
                webxl_company.city as company_city,
                webxl_company.create_date as company_created_date,
                webxl_user.branch as user_branch,
                webxl_user.roleId as user_role
              " . $base_query . " ORDER BY webxl_leads.create_date DESC LIMIT ? OFFSET ?";
              
    $params[] = $length;
    $params[] = $start;
    $param_types .= "ii";
    
    $stmt = mysqli_prepare($con, $query);
    if (!empty($params)) {
        mysqli_stmt_bind_param($stmt, $param_types, ...$params);
    }
    mysqli_stmt_execute($stmt);
    $result = mysqli_stmt_get_result($stmt);
    $companies = mysqli_fetch_all($result, MYSQLI_ASSOC);
    mysqli_stmt_close($stmt);
    
    $data = [];
    $i = $start;
    foreach ($companies as $company) {
        $i++;
        
        $created_date = new DateTime($company['create_date']);
        $current_date = new DateTime();
        $days_diff = $current_date->diff($created_date)->days;
        
        $status_class = '';
        $status_text = '';
        if ($days_diff == 0) {
            $status_class = 'bg-success';
            $status_text = 'Today';
        } elseif ($days_diff <= 7) {
            $status_class = 'bg-info';
            $status_text = $days_diff . ' days ago';
        } elseif ($days_diff <= 30) {
            $status_class = 'bg-warning';
            $status_text = $days_diff . ' days ago';
        } else {
            $status_class = 'bg-secondary';
            $status_text = $days_diff . ' days ago';
        }
        
        $cname = htmlspecialchars($company['cname']);
        $cname_html = "<a href='company-detail=" . $company['com_id'] . "' class='text-primary fw-bold'>" . $cname . "</a>";
        $creator = username($company['created_by']);
        $creator_html = "<span class='badge bg-info text-white'>" . $creator . "</span>";
        $time_html = "<i class='bx bx-time text-muted me-1'></i>" . date("h:i A", strtotime($company['create_date']));
        $date_html = "<span class='badge rounded-pill badge-soft-primary font-size-11'>" . date("d-m-Y", strtotime($company['create_date'])) . "</span>";
        $country_html = "<span class='badge bg-secondary'>" . htmlspecialchars($company['company_country']) . "</span>";
        $city_html = "<span class='badge bg-primary'>" . htmlspecialchars($company['company_city'] ?? 'N/A') . "</span>";
        $status_html = "<span class='badge " . $status_class . " font-size-11'>" . $status_text . "</span>";
        $assignee = username($company['assignId']);
        $assignee_html = "<span class='badge bg-warning text-white'>" . $assignee . "</span>";
        
        $action_html = "<a href='company-edit=" . $company['com_id'] . "' class='btn btn-sm btn-outline-success me-1'><i class='bx bx-edit me-1'></i>Edit</a> " .
                       "<button class='btn btn-sm btn-outline-primary' type='button' onclick=\"openTransferModal('" . $company['lead_id'] . "', '" . $company['com_id'] . "', '" . addslashes($cname) . "')\"><i class='bx bx-transfer me-1'></i>Transfer</button>";

        $data[] = [
            $i,
            $cname_html,
            $creator_html,
            $time_html,
            $date_html,
            $country_html,
            $city_html,
            $status_html,
            $assignee_html,
            $action_html
        ];
    }
    
    echo json_encode([
        'draw' => $draw,
        'recordsTotal' => $totalRecords,
        'recordsFiltered' => $totalFiltered,
        'data' => $data
    ]);
    exit;
}

