// Domain/Hosting Renewal Report AJAX Handler
if (isset($_POST['action']) && $_POST['action'] == 'get_domain_renewal_report') {
    while (ob_get_level()) { ob_end_clean(); }
    error_reporting(0);
    header('Content-Type: application/json');
    global $con;
    
    $start_date = mysqli_real_escape_string($con, $_POST['start_date']);
    $end_date = mysqli_real_escape_string($con, $_POST['end_date']);
    
    // Make sure we include the full end date time
    $end_date = $end_date . ' 23:59:59';
    $start_date = $start_date . ' 00:00:00';

    // 1. Fetch all domains expiring in this date range
    $q2 = "SELECT s.com_id, c.cname, MAX(sp.end_date) as expire_date 
           FROM webxl_sell s 
           JOIN webxl_sell_products sp ON s.id = sp.sell_id 
           JOIN webxl_company c ON s.com_id = c.id 
           WHERE sp.pro_type IN ('domain', 'hosting', 'ssl') 
           AND (sp.deactive_reason = '' OR sp.deactive_reason IS NULL) 
           AND sp.end_date BETWEEN DATE('$start_date') AND DATE('$end_date')
           GROUP BY s.com_id, c.cname";
    $run2 = mysqli_query($con, $q2);
    
    $invoice_data = [];
    if($run2) {
        while($row = mysqli_fetch_assoc($run2)) {
            $com_id = $row['com_id'];
            
            // Check if there's a recent renewal invoice for this company (e.g., created in the last 6 months)
            // If so, it's a current invoice. Otherwise, we fetch the previous invoice to show the amount.
            $q_inv = "SELECT invoice_id, grand_total, pay, DATE(create_date) as create_date, domain_renewal FROM webxl_invoice WHERE com_id = '$com_id' ORDER BY invoice_id DESC LIMIT 1";
            $run_inv = mysqli_query($con, $q_inv);
            if($run_inv && $inv_row = mysqli_fetch_assoc($run_inv)) {
                $row['invoice_id'] = $inv_row['invoice_id'];
                $row['grand_total'] = $inv_row['grand_total'];
                $row['pay'] = $inv_row['pay'];
                $row['create_date'] = $inv_row['create_date'];
                
                // If it's a recent invoice and marked as domain_renewal, we treat it as an actual invoice for this renewal
                $six_months_ago = strtotime('-6 months');
                if ($inv_row['domain_renewal'] == 1 && strtotime($inv_row['create_date']) >= $six_months_ago) {
                    $row['source'] = 'invoice';
                } else {
                    $row['source'] = 'domain'; // treating it as previous amount
                }
            } else {
                $row['invoice_id'] = '-';
                $row['grand_total'] = 0;
                $row['pay'] = 0;
                $row['create_date'] = '-';
                $row['source'] = 'domain';
            }
            $invoice_data[] = $row;
        }
    }
    $data = [];
    $total_invoices = 0;
    $total_paid_count = 0;
    $total_upcoming_count = 0;
    $total_expired_count = 0;
    
    $sum_grand_total = 0;
    $sum_paid = 0;
    $sum_pending = 0;
    
    $today = date('Y-m-d');
    
    foreach ($invoice_data as $row) {
        $grand_total = (float)$row['grand_total'];
        $paid = (float)$row['pay'];
        $pendingAmount = $grand_total - $paid;
        
        $expire_date = $row['expire_date'];
        
        $total_invoices++;
        $sum_grand_total += $grand_total;
        $sum_paid += $paid;
        $sum_pending += $pendingAmount;
        
        // If it's an actual renewal invoice in this date range and it's paid
        if ($row['source'] == 'invoice' && $pendingAmount <= 0) {
            $total_paid_count++;
            $row['category'] = 'Paid';
        } else {
            if (empty($expire_date) || $expire_date == '0000-00-00') {
                // Default to upcoming if no date
                $total_upcoming_count++;
                $row['category'] = 'Upcoming';
            } else {
                if ($expire_date < $today) {
                    $total_expired_count++;
                    $row['category'] = 'Expired';
                } else {
                    $total_upcoming_count++;
                    $row['category'] = 'Upcoming';
                }
            }
        }
        
        $data[] = $row;
    }
    
    $response = [
        'summary' => [
            'total_invoices' => $total_invoices,
            'total_paid' => $total_paid_count,
            'total_upcoming' => $total_upcoming_count,
            'total_expired' => $total_expired_count,
            'sum_grand_total' => $sum_grand_total,
            'sum_paid' => $sum_paid,
            'sum_pending' => $sum_pending
        ],
        'data' => $data
    ];
    
    echo json_encode($response);
    exit;
}

