/**
 * Function to get pending BV records with user filter support
 */
function getPendingBVRecords()
{
    global $con;

    try {
        // Check connection
        if (!$con) {
            throw new Exception("Database connection not available");
        }

        // Get user filter if provided
        $selectedUser = isset($_POST['user_id']) && !empty($_POST['user_id']) && $_POST['user_id'] !== 'All'
            ? mysqli_real_escape_string($con, $_POST['user_id']) : '';

        // Base query with user filter capability
        $mainQuery = "SELECT DISTINCT 
                        vg.com_id,
                        vg.member_id,
                        vg.user_id as assigned_user_id,
                        ga.user_bv_date,
                        ga.bvDate,
                        ga.startData,
                        ga.endData,
                        c.cname as company_name,
                        u.name as user_name
                     FROM webxl_verify_gm vg
                     INNER JOIN webxl_gmaccount ga ON vg.com_id = ga.com_id
                     LEFT JOIN webxl_company c ON vg.com_id = c.id
                     LEFT JOIN webxl_user u ON vg.user_id = u.user_id
                     WHERE vg.acc_disc_status = 'Approved' 
                     AND vg.ceo_disc_status = 'Approved' 
                     AND vg.webxl_pay_status = 'Yes' 
                     AND vg.renwal = 0
                     AND vg.webxl_pay_date IS NOT NULL
                     AND ga.renwal = 0";

        // Add user filter if specified
        if ($selectedUser) {
            $mainQuery .= " AND vg.user_id = '$selectedUser'";
        }

        $mainQuery .= " ORDER BY vg.com_id ASC";

        $result = mysqli_query($con, $mainQuery);

        if (!$result) {
            throw new Exception("Database query failed: " . mysqli_error($con));
        }

        $pendingRecords = array();

        while ($row = mysqli_fetch_assoc($result)) {
            $record = array(
                'com_id' => $row['com_id'] ?? '',
                'member_id' => $row['member_id'] ?? 'N/A',
                'company_name' => $row['company_name'] ?? 'N/A',
                'assigned_user_id' => $row['assigned_user_id'] ?? '',
                'user_name' => $row['user_name'] ?? 'N/A',
                'user_bv_date' => $row['user_bv_date'] ?? '',
                'ab_pay_date' => $row['webxl_pay_date'] ?? '',
                'bvDate' => $row['bvDate'] ?? '',
                'startData' => $row['startData'] ?? '',
                'endData' => $row['endData'] ?? ''
            );

            $pendingRecords[] = $record;
        }

        mysqli_free_result($result);

        // Clean output and return JSON
        echo json_encode(array(
            'success' => true,
            'data' => $pendingRecords,
            'message' => 'Data fetched successfully',
            'total_records' => count($pendingRecords),
            'filtered_by_user' => !empty($selectedUser)
        ));
    } catch (Exception $e) {
        echo json_encode(array(
            'success' => false,
            'message' => $e->getMessage(),
            'data' => array()
        ));
    }
}

/**
 * Function to search BV records with filters including user filter
 */
function searchBVRecords()
{
    global $con;

    try {
        if (!$con) {
            throw new Exception("Database connection not available");
        }

        // Get and clean filter parameters
        $startDate = isset($_POST['start_date']) && !empty($_POST['start_date'])
            ? mysqli_real_escape_string($con, $_POST['start_date']) : '';
        $endDate = isset($_POST['end_date']) && !empty($_POST['end_date'])
            ? mysqli_real_escape_string($con, $_POST['end_date']) : '';
        $searchText = isset($_POST['search_text']) && !empty($_POST['search_text'])
            ? mysqli_real_escape_string($con, $_POST['search_text']) : '';
        $selectedUser = isset($_POST['user_id']) && !empty($_POST['user_id']) && $_POST['user_id'] !== 'All'
            ? mysqli_real_escape_string($con, $_POST['user_id']) : '';

        // Base query with user information
        $mainQuery = "SELECT DISTINCT 
                        vg.com_id,
                        vg.member_id,
                        vg.user_id as assigned_user_id,
                        ga.user_bv_date,
                        ga.bvDate,
                        ga.startData,
                        ga.endData,
                        c.cname as company_name,
                        u.name as user_name
                     FROM webxl_verify_gm vg
                     INNER JOIN webxl_gmaccount ga ON vg.com_id = ga.com_id
                     LEFT JOIN webxl_company c ON vg.com_id = c.id
                     LEFT JOIN webxl_user u ON vg.user_id = u.user_id
                     WHERE vg.acc_disc_status = 'Approved' 
                     AND vg.ceo_disc_status = 'Approved' 
                     AND vg.webxl_pay_status = 'Yes' 
                     AND vg.webxl_pay_date IS NOT NULL
                     AND vg.renwal = 0
                     AND ga.renwal = 0";

        // Add user filter
        if ($selectedUser) {
            $mainQuery .= " AND vg.user_id = '$selectedUser'";
        }

        // Add date range filters
        if ($startDate) {
            $mainQuery .= " AND (ga.user_bv_date >= '$startDate' OR ga.bvDate >= '$startDate' 
                           OR ga.startData >= '$startDate' OR ga.endData >= '$startDate')";
        }

        if ($endDate) {
            $mainQuery .= " AND (ga.user_bv_date <= '$endDate' OR ga.bvDate <= '$endDate' 
                           OR ga.startData <= '$endDate' OR ga.endData <= '$endDate')";
        }

        // Add text search
        if ($searchText) {
            $mainQuery .= " AND (vg.com_id LIKE '%$searchText%' 
                           OR vg.member_id LIKE '%$searchText%' 
                           OR c.cname LIKE '%$searchText%'
                           OR u.name LIKE '%$searchText%')";
        }

        $mainQuery .= " ORDER BY vg.com_id ASC";

        $result = mysqli_query($con, $mainQuery);

        if (!$result) {
            throw new Exception("Search query failed: " . mysqli_error($con));
        }

        $pendingRecords = array();

        while ($row = mysqli_fetch_assoc($result)) {
            $record = array(
                'com_id' => $row['com_id'] ?? '',
                'member_id' => $row['member_id'] ?? 'N/A',
                'company_name' => $row['company_name'] ?? 'N/A',
                'assigned_user_id' => $row['assigned_user_id'] ?? '',
                'user_name' => $row['user_name'] ?? 'N/A',
                'renewal_type' => '0',
                'user_bv_date' => $row['user_bv_date'] ?? '',
                'bvDate' => $row['bvDate'] ?? '',
                'startData' => $row['startData'] ?? '',
                'endData' => $row['endData'] ?? ''
            );

            $pendingRecords[] = $record;
        }

        mysqli_free_result($result);

        // Build filter description for response
        $filterDescription = [];
        if ($selectedUser)
            $filterDescription[] = "User filtered";
        if ($startDate || $endDate)
            $filterDescription[] = "Date range applied";
        if ($searchText)
            $filterDescription[] = "Text search applied";

        $filterMsg = empty($filterDescription) ? 'All records' : implode(', ', $filterDescription);

        echo json_encode(array(
            'success' => true,
            'data' => $pendingRecords,
            'message' => 'Search completed successfully',
            'total_records' => count($pendingRecords),
            'filter_description' => $filterMsg
        ));
    } catch (Exception $e) {
        echo json_encode(array(
            'success' => false,
            'message' => $e->getMessage(),
            'data' => array()
        ));
    }
}

/**
 * Function to update BV record - No changes needed for user filter
 */
function updateBVRecord()
{
    global $con;

    try {
        if (!$con) {
            throw new Exception("Database connection not available");
        }

        // Validate required data
        if (!isset($_POST['com_id']) || empty($_POST['com_id'])) {
            throw new Exception("Company ID is required");
        }

        $comId = mysqli_real_escape_string($con, $_POST['com_id']);
        $userBvDate = isset($_POST['user_bv_date']) && !empty($_POST['user_bv_date'])
            ? mysqli_real_escape_string($con, $_POST['user_bv_date']) : null;
        $bvDate = isset($_POST['bvDate']) && !empty($_POST['bvDate'])
            ? mysqli_real_escape_string($con, $_POST['bvDate']) : null;
        $startData = isset($_POST['startData']) && !empty($_POST['startData'])
            ? mysqli_real_escape_string($con, $_POST['startData']) : null;
        $endData = isset($_POST['endData']) && !empty($_POST['endData'])
            ? mysqli_real_escape_string($con, $_POST['endData']) : null;

        // Check if record exists
        $checkQuery = "SELECT COUNT(*) as count FROM webxl_gmaccount 
                      WHERE com_id = '$comId' AND renwal = 0";
        $checkResult = mysqli_query($con, $checkQuery);

        if (!$checkResult) {
            throw new Exception("Error checking record: " . mysqli_error($con));
        }

        $checkRow = mysqli_fetch_assoc($checkResult);
        mysqli_free_result($checkResult);

        if ($checkRow['count'] == 0) {
            throw new Exception("No record found for Company ID: $comId");
        }

        // Build update query
        $updateFields = array();
        if ($userBvDate !== null) {
            $updateFields[] = "user_bv_date = '$userBvDate'";
        } else {
            $updateFields[] = "user_bv_date = NULL";
        }

        if ($bvDate !== null) {
            $updateFields[] = "bvDate = '$bvDate'";
        } else {
            $updateFields[] = "bvDate = NULL";
        }

        if ($startData !== null) {
            $updateFields[] = "startData = '$startData'";
        } else {
            $updateFields[] = "startData = NULL";
        }

        if ($endData !== null) {
            $updateFields[] = "endData = '$endData'";
        } else {
            $updateFields[] = "endData = NULL";
        }

        $updateQuery = "UPDATE webxl_gmaccount SET " . implode(', ', $updateFields) .
            " WHERE com_id = '$comId' AND renwal = 0";

        $updateResult = mysqli_query($con, $updateQuery);

        if (!$updateResult) {
            throw new Exception("Update failed: " . mysqli_error($con));
        }

        $affectedRows = mysqli_affected_rows($con);

        echo json_encode(array(
            'success' => true,
            'message' => 'Record updated successfully',
            'affected_rows' => $affectedRows
        ));
    } catch (Exception $e) {
        echo json_encode(array(
            'success' => false,
            'message' => $e->getMessage()
        ));
    }
}


