//Chart of Account New

if (isset($_GET['action']) && $_GET['action'] == 'fetch_chart') {

    $head_filter = $_POST['head_filter'] ?? 'All';
    $is_active = $_POST['is_active'] ?? '1';

    $where_parent = "WHERE is_active = 1";
    if ($head_filter != 'All') {
        $where_parent .= " AND account_code = '$head_filter'";
    }
    if ($is_active != 'All') {
        $where_parent .= " AND is_active = $is_active";
    }

    $parents = $con->query("SELECT * FROM webxl_coa_parent_heads $where_parent ORDER BY account_code ASC");

    if ($parents->num_rows == 0) {
        echo "<div class='alert alert-warning'>No records found!</div>";
        exit;
    }

    // Fetch all parents into array to get next code
    $parentArray = [];
    while ($row = $parents->fetch_assoc()) {
        $parentArray[] = $row;
    }

    $output = '<div class="row g-3">';

    for ($i = 0; $i < count($parentArray); $i++) {
        $parent = $parentArray[$i];
        $startCode = $parent['account_code'];

        // Calculate end code based on next parent's start code
        if (isset($parentArray[$i + 1])) {
            $endCode = $parentArray[$i + 1]['account_code'] - 1;
        } else {
            // Last parent: calculate gap from previous and apply same
            if (isset($parentArray[$i - 1])) {
                $gap = $startCode - $parentArray[$i - 1]['account_code'];
                $endCode = $startCode + $gap - 1;
            } else {
                // Only one parent exists, use default +4999
                $endCode = $startCode + 4999;
            }
        }

        $uniqueId = 'collapse_' . $parent['id'];

        $output .= '<div class="col-md-6 col-lg-4">';
        $output .= '<div class="card border h-100 shadow-sm">';

        // Header with collapse toggle
        $output .= '<div class="card-header d-flex justify-content-between align-items-center" style="background-color: #ffd6d6; border-bottom: 2px solid #ff9999; cursor: pointer;" data-bs-toggle="collapse" data-bs-target="#' . $uniqueId . '" aria-expanded="false">';
        $output .= '<h6 class="mb-0 text-dark"><strong>(' . htmlspecialchars($startCode) . '-' . htmlspecialchars($endCode) . ') ' . htmlspecialchars($parent['head_name']) . '</strong></h6>';
