        $output .= '<button class="btn btn-xs btn-success add-child-btn" style="padding: 2px 6px; font-size: 10px;" data-parent-id="' . $parent['id'] . '" data-parent-name="' . htmlspecialchars($parent['head_name']) . '" data-parent-code="' . $parent['account_code'] . '"  data-bs-toggle="tooltip">';
        $output .= '<i class="fas fa-plus-circle"></i>';
        $output .= '</button>';
        $output .= '<i class="fas fa-chevron-down toggle-icon" style="font-size: 12px; transition: transform 0.3s;"></i>';
        $output .= '</div>';
        $output .= '</div>';

        // Collapsible body - default collapsed
        $output .= '<div id="' . $uniqueId . '" class="collapse">';
        $output .= '<div class="card-body p-0">';
        $output .= '<table class="table table-sm table-hover mb-0">';

        $output .= '<thead style="background-color: #f8f9fa; border-bottom: 2px solid #dee2e6;">';
        $output .= '<tr>';
        $output .= '<th class="py-2 ps-3 fw-semibold" style="width: 40px; color: #495057;">S.No</th>';
        $output .= '<th class="py-2 fw-semibold" style="width: 70px; color: #495057;">Code</th>';
        $output .= '<th class="py-2 fw-semibold" style="color: #495057;">Head</th>';
        $output .= '<th class="py-2 fw-semibold text-center" style="width: 80px; color: #495057;">Action</th>';
        $output .= '</tr>';
        $output .= '</thead>';

        $output .= '<tbody>';

        $children = $con->query("SELECT * FROM webxl_coa_child_heads WHERE parent_id = {$parent['id']} AND is_active = 1 ORDER BY account_code ASC");

        if ($children->num_rows > 0) {
            $childIndex = 1;
            while ($child = $children->fetch_assoc()) {
                $rowBg = ($childIndex % 2 == 0) ? 'style="background-color: #f9f9f9;"' : '';

                $output .= '<tr class="border-bottom" ' . $rowBg . '>';
                $output .= '<td class="py-2 ps-3 text-center"><span class="badge bg-secondary">' . $childIndex . '</span></td>';
                $output .= '<td class="py-2"><span class="badge bg-success">' . htmlspecialchars($child['account_code']) . '</span></td>';
                $output .= '<td class="py-2"><strong style="color: #212529;">' . htmlspecialchars($child['head_name']) . '</strong>';

                $transactions = $con->query("SELECT * FROM webxl_coa_transactional_heads WHERE child_id = {$child['id']} AND is_active = 1 ORDER BY account_code ASC");

                if ($transactions->num_rows > 0) {
                    $output .= '<ul class="list-unstyled mb-0 mt-2 ms-2 small">';
                    while ($t = $transactions->fetch_assoc()) {
                        $output .= '<li class="mb-1" style="color: #6c757d; padding-left: 8px; border-left: 2px solid #0dcaf0;">';

                        // Transaction head row
                        $output .= '<div class="d-flex justify-content-between align-items-center mb-1">';
                        $output .= '<span>';
                        $output .= '<span class="badge bg-info text-dark" style="font-size: 0.7rem;">' . htmlspecialchars($t['account_code']) . '</span> ';
                        $output .= '→ ' . htmlspecialchars($t['head_name']);
                        $output .= '</span>';
                        $output .= '<div class="btn-group" role="group">';
                        $output .= '<button class="btn btn-xs btn-success add-sub-transaction-btn" style="padding: 1px 4px; font-size: 9px; margin-right: 2px;" data-trans-id="' . $t['id'] . '" data-trans-name="' . htmlspecialchars($t['head_name']) . '" data-trans-code="' . htmlspecialchars($t['account_code']) . '"  data-bs-toggle="tooltip">';
                        $output .= '<i class="fas fa-plus"></i>';
                        $output .= '</button>';
                        $output .= '<button class="btn btn-xs btn-warning edit-transaction-btn" style="padding: 1px 4px; font-size: 9px;" data-trans-id="' . $t['id'] . '" data-trans-name="' . htmlspecialchars($t['head_name']) . '" data-trans-desc="' . htmlspecialchars($t['description']) . '" title="Edit Transaction" data-bs-toggle="tooltip">';
                        $output .= '<i class="fas fa-edit"></i>';
                        $output .= '</button>';
                        $output .= '</div>';
                        $output .= '</div>';

                        // Fetch and display sub-transactional heads
                        $subTransactions = $con->query("SELECT * FROM webxl_coa_sub_transactional_heads WHERE transactional_id = {$t['id']} AND is_active = 1 ORDER BY account_code ASC");

                        if ($subTransactions->num_rows > 0) {
                            $output .= '<ul class="list-unstyled mb-0 ms-3" style="font-size: 9px;">';
                            while ($st = $subTransactions->fetch_assoc()) {
                                $output .= '<li class="mb-1 d-flex justify-content-between align-items-center" style="color: #495057; padding-left: 8px; border-left: 2px solid #20c997;">';
                                $output .= '<span>';
                                $output .= '<span class="badge bg-success" style="font-size: 9px;">' . htmlspecialchars($st['account_code']) . '</span> ';
                                $output .= '↳ ' . htmlspecialchars($st['head_name']);
                                $output .= '</span>';
                                $output .= '<button class="btn btn-xs btn-warning edit-sub-transaction-btn" style="padding: 1px 4px; font-size: 8px;" data-sub-trans-id="' . $st['id'] . '" data-sub-trans-name="' . htmlspecialchars($st['head_name']) . '" data-sub-trans-desc="' . htmlspecialchars($st['description']) . '" title="Edit Sub-Transaction" data-bs-toggle="tooltip">';
                                $output .= '<i class="fas fa-edit"></i>';
                                $output .= '</button>';
                                $output .= '</li>';
                            }
                            $output .= '</ul>';
                        }

                        $output .= '</li>';
                    }
                    $output .= '</ul>';
                }

                $output .= '</td>';
                $output .= '<td class="py-2 text-center">';
                $output .= '<button class="btn btn-xs btn-primary add-transaction-btn" style="padding: 2px 6px; font-size: 10px; margin-right: 2px;" data-parent-id="' . $parent['id'] . '" data-parent-name="' . htmlspecialchars($parent['head_name']) . '" data-child-id="' . $child['id'] . '" data-child-name="' . htmlspecialchars($child['head_name']) . '" data-child-code="' . $child['account_code'] . '" title="Add Transaction" data-bs-toggle="tooltip">';
                $output .= '<i class="fas fa-plus"></i>';
                $output .= '</button>';
                $output .= '<button class="btn btn-xs btn-warning edit-child-btn" style="padding: 2px 6px; font-size: 10px;" data-child-id="' . $child['id'] . '" data-child-name="' . htmlspecialchars($child['head_name']) . '" data-child-desc="' . htmlspecialchars($child['description']) . '" title="Edit Child Head" data-bs-toggle="tooltip">';
                $output .= '<i class="fas fa-edit"></i>';
                $output .= '</button>';
                $output .= '</td>';
                $output .= '</tr>';
                $childIndex++;
            }
        } else {
            $output .= '<tr><td colspan="4" class="text-center text-muted py-3" style="background-color: #fff3cd;">No Child Heads</td></tr>';
        }

        $output .= '</tbody>';
        $output .= '</table>';
        $output .= '</div>';
        $output .= '</div>'; // Close collapse div
        $output .= '</div>';
        $output .= '</div>';
    }

    $output .= '</div>';

    // Add CSS for icon rotation
    $output .= '<style>
    .toggle-icon {
        transition: transform 0.3s ease;
    }
    .rotate-180 {
        transform: rotate(180deg);
    }
    .card-header[data-bs-toggle="collapse"]:hover {
        background-color: #ffcccc !important;
    }
    </style>';

    echo $output;
}

