if (isset($_GET['action']) && $_GET['action'] == 'get_next_parent_code') {
    $query = $con->query("SELECT account_code FROM webxl_coa_parent_heads ORDER BY account_code ASC");

    $nextCode = 10000;

    if ($query->num_rows > 0) {
        $codes = [];
        while ($row = $query->fetch_assoc()) {
            $codes[] = intval($row['account_code']);
        }

        if (count($codes) >= 2) {
            $gap = $codes[count($codes) - 1] - $codes[count($codes) - 2];
        } else {
            $gap = 5000;
        }

        $lastCode = $codes[count($codes) - 1];
        $nextCode = $lastCode + $gap;
    }

    echo json_encode([
        'success' => true,
        'next_code' => $nextCode
    ]);
    exit;
}

if (isset($_POST['add_parent_head'])) {
    $parent_head = trim($_POST['add_parent_head']);
    $account_type = trim($_POST['account_type']);
    $description = isset($_POST['description']) ? trim($_POST['description']) : '';
    $account_code = isset($_POST['account_code']) ? intval($_POST['account_code']) : 0;


    if (empty($parent_head) || empty($account_type)) {
        echo json_encode(['status' => 'error', 'message' => 'Head name and account type are required']);
        exit;
    }


    $allowedTypes = ['Asset', 'Liability', 'Equity', 'Revenue', 'Expense'];
    if (!in_array($account_type, $allowedTypes)) {
        echo json_encode(['status' => 'error', 'message' => 'Invalid account type']);
        exit;
    }


    if ($account_code <= 0) {
        $query = $con->query("SELECT MAX(account_code) as max_code FROM webxl_coa_parent_heads");
        $result = $query->fetch_assoc();
        $account_code = 1000;
        if ($result['max_code'] !== null) {
            $account_code = intval($result['max_code']) + 1000;
        }
    }


    $check = $con->prepare("SELECT id FROM webxl_coa_parent_heads WHERE head_name = ?");
    $check->bind_param("s", $parent_head);
    $check->execute();
    $exists = $check->get_result();
    if ($exists->num_rows > 0) {
        echo json_encode(['status' => 'error', 'message' => 'Parent head already exists!']);
        exit;
    }


    $stmt = $con->prepare("INSERT INTO webxl_coa_parent_heads (account_code, head_name, account_type, description, is_active, created_by, created_at, updated_at)
                           VALUES (?, ?, ?, ?, 1, ?, NOW(), NOW())");
    $created_by = isset($_COOKIE['id']) ? intval($_COOKIE['id']) : 0;
    $stmt->bind_param("isssi", $account_code, $parent_head, $account_type, $description, $created_by);

    if ($stmt->execute()) {
        echo json_encode(['status' => 'success', 'message' => 'Parent head added successfully!']);
    } else {
        echo json_encode(['status' => 'error', 'message' => 'Insert failed: ' . $stmt->error]);
    }

    $stmt->close();
    exit;
}

if (isset($_GET['action']) && $_GET['action'] == 'get_next_child_code') {
    $parent_id = intval($_GET['parent_id']);

    $parentQuery = $con->query("SELECT account_code FROM webxl_coa_parent_heads WHERE id = $parent_id");
    $parentResult = $parentQuery->fetch_assoc();
    $parentCode = intval($parentResult['account_code']);

    $nextParentQuery = $con->query("SELECT account_code FROM webxl_coa_parent_heads WHERE account_code > $parentCode ORDER BY account_code ASC LIMIT 1");

    if ($nextParentQuery->num_rows > 0) {
        $nextParentResult = $nextParentQuery->fetch_assoc();
        $maxAllowed = intval($nextParentResult['account_code']) - 1;
    } else {
        $allParentsQuery = $con->query("SELECT account_code FROM webxl_coa_parent_heads ORDER BY account_code ASC");
        $codes = [];
        while ($row = $allParentsQuery->fetch_assoc()) {
            $codes[] = intval($row['account_code']);
        }

        if (count($codes) >= 2) {
            $gap = $codes[count($codes) - 1] - $codes[count($codes) - 2];
        } else {
            $gap = 5000;
        }

        $maxAllowed = $parentCode + $gap - 1;
    }

    $query = $con->query("SELECT MAX(account_code) as max_code FROM webxl_coa_child_heads WHERE parent_id = $parent_id");
    $result = $query->fetch_assoc();

    if ($result['max_code'] === null) {
        $nextCode = $parentCode + 100;
    } else {
        $nextCode = intval($result['max_code']) + 100;
    }

    if ($nextCode > $maxAllowed) {
        echo json_encode([
            'success' => false,
            'message' => 'Cannot add more child heads. Range exceeded.'
        ]);
    } else {
        $endRange = $nextCode + 99;

        echo json_encode([
            'success' => true,
            'next_code' => $nextCode,
            'end_range' => $endRange
        ]);
    }
    exit;
}
if (isset($_GET['action']) && $_GET['action'] == 'get_parent_range') {
    $parentCode = intval($_GET['parent_code']);

    $nextParentQuery = $con->query("SELECT account_code FROM webxl_coa_parent_heads WHERE account_code > $parentCode ORDER BY account_code ASC LIMIT 1");

    if ($nextParentQuery->num_rows > 0) {
