// Add child head
if (isset($_POST['add_child_head'])) {
    $parent_id = intval($_POST['parent_id']);
    $head_name = trim($_POST['add_child_head']);
    $description = isset($_POST['description']) ? trim($_POST['description']) : '';
    $account_code = isset($_POST['account_code']) ? intval($_POST['account_code']) : 0;

    $created_by = isset($_COOKIE['id']) ? intval($_COOKIE['id']) : 0;

    // If account_code is not provided, generate it
    if ($account_code <= 0) {
        // Get parent account code
        $parentQuery = $con->query("SELECT account_code FROM webxl_coa_parent_heads WHERE id = $parent_id");
        $parentResult = $parentQuery->fetch_assoc();
        $parentCode = intval($parentResult['account_code']);

        // Get max child code for this parent
        $query = $con->query("SELECT MAX(account_code) as max_code FROM webxl_coa_child_heads WHERE parent_id = $parent_id");
        $result = $query->fetch_assoc();

        // If no child exists, start from parent code + 100, otherwise increment by 100
        if ($result['max_code'] === null) {
            $account_code = $parentCode + 100;
        } else {
            $account_code = intval($result['max_code']) + 100;
        }

        // Check if next code exceeds parent range (parent_code + 999)
        $maxAllowed = $parentCode + 999;
        if ($account_code > $maxAllowed) {
            echo json_encode([
                'status' => 'error',
                'message' => 'Cannot add more child heads. Range exceeded for this parent.'
            ]);
            exit;
        }
    }

    // Check if child head with same name exists under this parent
    $checkQuery = $con->prepare("SELECT id FROM webxl_coa_child_heads WHERE head_name = ? AND parent_id = ?");
    $checkQuery->bind_param("si", $head_name, $parent_id);
    $checkQuery->execute();
    $checkResult = $checkQuery->get_result();

    if ($checkResult->num_rows > 0) {
        echo json_encode([
            'status' => 'error',
            'message' => 'Child head with this name already exists under this parent!'
        ]);
        exit;
    }

    // Insert new child head
    $stmt = $con->prepare("INSERT INTO webxl_coa_child_heads (parent_id, account_code, head_name, description, is_active, created_by, created_at, updated_at) VALUES (?, ?, ?, ?, 1, ?, NOW(), NOW())");

    if (!$stmt) {
        echo json_encode([
            'status' => 'error',
            'message' => 'Database error: ' . $con->error
        ]);
        exit;
    }

    $stmt->bind_param("iissi", $parent_id, $account_code, $head_name, $description, $created_by);

    if ($stmt->execute()) {
        echo json_encode([
            'status' => 'success',
            'message' => 'Child head added successfully! Code: ' . $account_code
        ]);
    } else {
        echo json_encode([
            'status' => 'error',
            'message' => 'Error saving: ' . $stmt->error
        ]);
    }

    $stmt->close();
    exit;
}
