if (isset($_POST['expense_type_id'])) {
    $expense_type_id = $_POST['expense_type_id'];

    $response = array(
        'success' => false,
        'data' => array()
    );

    // Fetch parent head and its children based on expense type (parent head id)
    $query = "SELECT DISTINCT 
                p.id as parent_id,
                p.head_name as parent_name,
                p.account_code as parent_code
              FROM webxl_coa_parent_heads p
              WHERE p.id = ? 
              AND p.is_active = 1
              ORDER BY p.head_name ASC";

    $stmt = $con->prepare($query);
    $stmt->bind_param('i', $expense_type_id);
    $stmt->execute();
    $result = $stmt->get_result();

    if ($result && mysqli_num_rows($result) > 0) {
        while ($parent = mysqli_fetch_assoc($result)) {
            // Fetch child heads for this parent
            $childQuery = "SELECT id, head_name, account_code 
                          FROM webxl_coa_child_heads 
                          WHERE parent_id = ? 
                          AND is_active = 1 
                          ORDER BY head_name ASC";

            $childStmt = $con->prepare($childQuery);
            $childStmt->bind_param('i', $parent['parent_id']);
            $childStmt->execute();
            $childResult = $childStmt->get_result();

            $children = array();
            if ($childResult && mysqli_num_rows($childResult) > 0) {
                while ($child = mysqli_fetch_assoc($childResult)) {
                    $children[] = array(
                        'id' => $child['id'],
                        'head_name' => $child['head_name'],
                        'account_code' => $child['account_code']
                    );
                }
            }
            $childStmt->close();

            $response['data'][] = array(
                'parent_id' => $parent['parent_id'],
                'parent_name' => $parent['parent_name'],
                'parent_code' => $parent['parent_code'],
                'children' => $children
            );
        }
        $response['success'] = true;
    }

    $stmt->close();
    echo json_encode($response);
}
















if (isset($_POST['searchGlobalCompany'])) {
    $search = mysqli_real_escape_string($con, $_POST['searchGlobalCompany']);
    $action = $_POST['searchAction'] ?? 'followup';
    
    $query = "SELECT * FROM `webxl_company` WHERE (TRIM(cname) LIKE '%$search%' OR com_id LIKE '%$search%') ORDER BY id DESC LIMIT 20";
    $retval = mysqli_query($con, $query);
    $cot = mysqli_num_rows($retval);
    if ($cot > 0) {
        while ($row = mysqli_fetch_assoc($retval)) {
            $query1 = "SELECT name, email, phone FROM webxl_com_detail WHERE com_id = '" . $row['id'] . "'";
            $retval1 = mysqli_query($con, $query1);
            $row1 = mysqli_fetch_assoc($retval1);

            $assignedTo = "N/A";
            if ($row['assignId']) {
                $q2 = mysqli_query($con, "SELECT username FROM webxl_user WHERE id = '" . $row['assignId'] . "'");
                if ($r2 = mysqli_fetch_assoc($q2)) $assignedTo = $r2['username'];
            }

            echo '<tr>
                <td>' . $row['com_id'] . '</td>
                <td>' . $row['cname'] . '</td>
                <td>' . ($row1['name'] ?? '') . '</td>
                <td>' . ($row1['email'] ?? '') . '</td>
                <td>' . ($row1['phone'] ?? '') . '</td>
                <td>' . $assignedTo . '</td>
                <td>';
            
            if ($action == 'quotation') {
                echo '<a href="new-quote=' . $row['id'] . '" class="btn btn-success btn-sm">Add Quotation</a>';
            } else {
                echo '<button type="button" onclick="followUpCustomer(\'' . $row['id'] . '\',\'' . $row['cname'] . '\')" data-bs-toggle="modal" data-bs-target=".bs-example-modal-lg-follow" class="btn btn-primary btn-sm">Add Follow-up</button>';
            }
                
            echo '</td>
            </tr>';
        }
    } else {
        echo '<tr><td colspan="7" class="text-center">No Companies Found</td></tr>';
    }
    exit;
}





